  `gamme` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":null,"story":"Torpedo (52 x 152 mm). Assemblage nicaraguayen, cape Habano oscuro d''Équateur, force Full. Notes de cèdre rouge, de café macchiato, de poivre cubèbe. Dans le nom, 1922 serait l''année de naissance du père de Pepín, dit un détaillant (Cigarsdirect) ; la maison ne le précise pas sur sa page d''accueil.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro d''Équateur"},{"name":"My Father No.1","color":"#722F37","force":null,"story":"Cape Connecticut naturel d''Équateur sur tripe nicaraguayenne. Notes de crème, de noisette, d''épices légères. Le nom de la ligne figure sur la page de la maison ; son année de lancement n''y est pas donnée.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut d''Équateur"},{"name":"La Antigüedad","color":"#A0522D","force":null,"story":"Cape maduro Connecticut Broadleaf sur tripe nicaraguayenne. Notes de chocolat noir, de café froid, de mélasse. Le nom (« l''ancienneté ») renvoie, dit un détaillant, à une ancienne marque cubaine dont l''artwork a été recherché ; plus doux que le Le Bijou 1922.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":null,"story":"Ligne au nom du fils de Pepín, cape Broadleaf du Connecticut.","vitolas":[],"wrapper":"Broadleaf du Connecticut"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":null,"story":"Puro nicaraguayen, cape cultivée au soleil ; la maison la liste parmi ses autres marques, sa version Maduro aussi.","vitolas":[],"wrapper":"Puro nicaraguayen"},{"name":"La Dueña","color":"#8B1A6B","force":null,"story":"Ligne que la fiche rattache à Janny García, la fille de la maison ; cape Broadleaf du Connecticut.","vitolas":[],"wrapper":"Broadleaf du Connecticut"},{"name":"El Centurión","color":"#7A2E1E","force":null,"story":"Ligne listée par la maison (versions H-2K-CT et Maduro comprises) ; cape Habano du Nicaragua.","vitolas":[],"wrapper":"Habano du Nicaragua"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","story":"En octobre 2026, le détaillant Cigarsdaily la dit la première marque maison de My Father en short filler (S.F. pour short filler), mais une critique de 2010 décrit un remplissage mixte, environ 70 % de long filler de graine cubaine, fait des chutes de la production de Pepin García. Cape Habano du Nicaragua sur liant et tripe nicaraguayens, en Robusto 5 x 50, vendu à cette date, et en Corona 6 x 46 en 2010.","vitolas":[],"wrapper":"Habano du Nicaragua"}]',
  `gamme_en` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":null,"story":"Torpedo (52 x 152 mm). Nicaraguan blend, Ecuadorian Habano oscuro wrapper, full strength. Notes of red cedar, macchiato coffee and cubeb pepper. The 1922 in the name is said to be the birth year of Pepín''s father, says a retailer (Cigarsdirect); the house does not state this on its home page.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Ecuadorian Habano Oscuro"},{"name":"My Father No.1","color":"#722F37","force":null,"story":"Ecuadorian Connecticut natural wrapper over Nicaraguan filler. Notes of cream, hazelnut and light spice. The line''s name appears on the house''s page; its year of launch is not given there.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Ecuadorian Connecticut"},{"name":"La Antigüedad","color":"#A0522D","force":null,"story":"Connecticut Broadleaf maduro wrapper over Nicaraguan filler. Notes of dark chocolate, cold coffee and molasses. The name (''seniority'') refers, says a retailer, to an old Cuban brand whose artwork was researched; milder than the Le Bijou 1922.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":null,"story":"Line named after Pepín''s son, Connecticut Broadleaf wrapper.","vitolas":[],"wrapper":"Connecticut broadleaf"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":null,"story":"Nicaraguan puro, sun-grown wrapper; the house lists it among its other brands, its Maduro version too.","vitolas":[],"wrapper":"Nicaraguan puro"},{"name":"La Dueña","color":"#8B1A6B","force":null,"story":"Line that the profile links to Janny García, the house''s daughter; Connecticut Broadleaf wrapper.","vitolas":[],"wrapper":"Connecticut broadleaf"},{"name":"El Centurión","color":"#7A2E1E","force":null,"story":"Line listed by the house (H-2K-CT and Maduro versions included); Nicaraguan Habano wrapper.","vitolas":[],"wrapper":"Nicaraguan Habano"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","story":"In October 2026, the retailer Cigarsdaily calls it My Father''s first house brand in short filler (S.F. for short filler), but a 2010 review describes a mixed filler, about 70% long filler of Cuban seed, made from offcuts of Pepin García''s production. Habano wrapper from Nicaragua over Nicaraguan binder and filler, in Robusto 5 x 50, on sale at that date, and in Corona 6 x 46 in 2010.","vitolas":[],"wrapper":"Nicaraguan Habano"}]',
  `gamme_es` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":null,"story":"Torpedo (52 x 152 mm). Ligada nicaragüense, capa Habano oscuro de Ecuador, fuerza plena. Notas de cedro rojo, de café macchiato, de pimienta cubeba. En el nombre, 1922 sería el año de nacimiento del padre de Pepín, dice un detallista (Cigarsdirect); la casa no lo precisa en su página de inicio.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro de Ecuador"},{"name":"My Father No.1","color":"#722F37","force":null,"story":"Capa Connecticut natural de Ecuador sobre tripa nicaragüense. Notas de crema, de avellana, de especias ligeras. El nombre de la línea figura en la página de la casa; su año de lanzamiento no se da allí.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut de Ecuador"},{"name":"La Antigüedad","color":"#A0522D","force":null,"story":"Capa maduro Connecticut Broadleaf sobre tripa nicaragüense. Notas de chocolate negro, de café frío, de melaza. El nombre, que significa ''la antigüedad'', remite, dice un detallista, a una antigua marca cubana cuyo diseño gráfico se investigó; más suave que la Le Bijou 1922.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":null,"story":"Línea con el nombre del hijo de Pepín, capa Broadleaf de Connecticut.","vitolas":[],"wrapper":"Broadleaf de Connecticut"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":null,"story":"Puro nicaragüense, capa cultivada al sol; la casa la incluye entre sus otras marcas, también su versión Maduro.","vitolas":[],"wrapper":"Puro nicaragüense"},{"name":"La Dueña","color":"#8B1A6B","force":null,"story":"Línea que la ficha vincula a Janny García, la hija de la casa; capa Broadleaf de Connecticut.","vitolas":[],"wrapper":"Broadleaf de Connecticut"},{"name":"El Centurión","color":"#7A2E1E","force":null,"story":"Línea que figura en la lista de la casa (con las versiones H-2K-CT y Maduro); capa Habano de Nicaragua.","vitolas":[],"wrapper":"Habano de Nicaragua"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","story":"En octubre de 2026, el minorista Cigarsdaily la presenta como la primera marca de la casa de My Father en short filler, abreviado S.F., pero una reseña de 2010 describe un relleno mixto, de alrededor de un 70 % de longfiller de semilla cubana, hecho con recortes de la producción de Pepin García. Capa Habano de Nicaragua sobre capote y tripa nicaragüenses, en Robusto 5 x 50, a la venta en esa fecha, y en Corona 6 x 46 en 2010.","vitolas":[],"wrapper":"Habano de Nicaragua"}]',
  `gamme_de` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":null,"story":"Torpedo (52 x 152 mm). Nicaraguanische Mischung, Deckblatt Habano Oscuro aus Ecuador, volle Stärke. Noten von Roter Zeder, Café Macchiato und Kubebenpfeffer. Die 1922 im Namen soll das Geburtsjahr von Pepíns Vater sein, sagt ein Einzelhändler (Cigarsdirect); das Haus nennt dies auf seiner Startseite nicht.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro aus Ecuador"},{"name":"My Father No.1","color":"#722F37","force":null,"story":"Deckblatt Connecticut Natural aus Ecuador über nicaraguanischer Einlage. Noten von Sahne, Haselnuss und leichten Gewürzen. Der Name der Linie steht auf der Seite des Hauses; ein Einführungsjahr wird dort nicht genannt.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut aus Ecuador"},{"name":"La Antigüedad","color":"#A0522D","force":null,"story":"Deckblatt Maduro Connecticut Broadleaf über nicaraguanischer Einlage. Noten von Zartbitterschokolade, kaltem Kaffee und Melasse. Der Name (''das lange Bestehen'') verweist, sagt ein Einzelhändler, auf eine alte kubanische Marke, deren Bildgestaltung erforscht wurde; milder als die Le Bijou 1922.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":null,"story":"Linie im Namen von Pepíns Sohn, Deckblatt Connecticut Broadleaf.","vitolas":[],"wrapper":"Connecticut-Broadleaf"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":null,"story":"Nicaraguanischer Puro, sonnengereiftes Deckblatt; das Haus führt sie unter seinen anderen Marken auf, auch ihre Maduro-Version.","vitolas":[],"wrapper":"Nicaraguanischer Puro"},{"name":"La Dueña","color":"#8B1A6B","force":null,"story":"Linie, die das Profil Janny García, der Tochter des Hauses, zuordnet; Deckblatt Connecticut Broadleaf.","vitolas":[],"wrapper":"Connecticut-Broadleaf"},{"name":"El Centurión","color":"#7A2E1E","force":null,"story":"Vom Haus geführte Linie (einschließlich der Versionen H-2K-CT und Maduro); nicaraguanisches Habano-Deckblatt.","vitolas":[],"wrapper":"Nicaraguanisches Habano"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","story":"Im Oktober 2026 bezeichnet der Einzelhändler Cigarsdaily sie als die erste Hausmarke von My Father mit Shortfiller (S.F. für Short Filler), doch eine Rezension von 2010 beschreibt eine gemischte Einlage, etwa 70 % Longfiller kubanischer Saat, hergestellt aus Produktionsresten von Pepin García. Habano-Deckblatt aus Nicaragua über nicaraguanischem Umblatt und nicaraguanischer Einlage, im Robusto 5 x 50, zu diesem Zeitpunkt im Verkauf, und im Corona 6 x 46 im Jahr 2010.","vitolas":[],"wrapper":"Habano aus Nicaragua"}]',
  `gamme_zh` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":null,"story":"鱼雷型（52 x 152 毫米）。尼加拉瓜配方，厄瓜多尔深色哈瓦那茄衣，烈度为浓烈。红雪松、玛奇朵咖啡、荜澄茄胡椒的气息。名称中的1922，据一位零售商（Cigarsdirect）所说，应是佩平父亲的出生年份；该公司在其首页上并未说明。","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"厄瓜多尔 Habano Oscuro"},{"name":"My Father No.1","color":"#722F37","force":null,"story":"厄瓜多尔康涅狄格自然色茄衣，芯叶为尼加拉瓜烟叶。奶油、榛子、轻盈香料的气息。该系列的名称见于公司页面；页面上未给出其推出年份。","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"厄瓜多尔 Connecticut"},{"name":"La Antigüedad","color":"#A0522D","force":null,"story":"康涅狄格宽叶马杜罗茄衣，芯叶为尼加拉瓜烟叶。黑巧克力、冷咖啡、糖蜜的气息。名称（意为资历）据一位零售商称，指向一个古巴旧品牌，其包装图案经过考据；比 Le Bijou 1922 更柔和。","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":null,"story":"以佩平之子命名的系列，康涅狄格 Broadleaf 茄衣。","vitolas":[],"wrapper":"康涅狄格 broadleaf"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":null,"story":"尼加拉瓜纯料，日晒茄衣；公司把它列在其他品牌之中，其 Maduro 版本也在列。","vitolas":[],"wrapper":"尼加拉瓜纯料"},{"name":"La Dueña","color":"#8B1A6B","force":null,"story":"该资料页将这个系列与公司之女詹妮·加西亚联系在一起；康涅狄格 Broadleaf 茄衣。","vitolas":[],"wrapper":"康涅狄格 broadleaf"},{"name":"El Centurión","color":"#7A2E1E","force":null,"story":"公司列出的系列（包括 H-2K-CT 与 Maduro 版本）；尼加拉瓜 Habano 茄衣。","vitolas":[],"wrapper":"尼加拉瓜 Habano"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","story":"2026年十月，零售商Cigarsdaily称其为My Father首个short filler自有品牌（简称S.F.），但2010年的一篇评论描述其茄芯为混合式，约70%为古巴种子的longfiller，取自Pepin García生产过程中的边角料。茄衣为尼加拉瓜Habano，茄套与茄芯均为尼加拉瓜所产，规格为Robusto 5 x 50，当时在售；2010年另有Corona 6 x 46。","vitolas":[],"wrapper":"尼加拉瓜Habano"}]',
  `gamme_ar` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":null,"story":"توربيدو (52 × 152 مم). خلطة نيكاراغوية، وغلاف هابانو داكن من الإكوادور، وقوة كاملة. نفحات من الأرز الأحمر وقهوة الماكياتو وفلفل الكبابة. أما 1922 في الاسم فيُقال إنه سنة ولادة والد بيبين، بحسب أحد بائعي التجزئة (Cigarsdirect)؛ ولا توضح الدار ذلك في صفحتها الرئيسية.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro من الإكوادور"},{"name":"My Father No.1","color":"#722F37","force":null,"story":"غلاف كونيتيكت طبيعي من الإكوادور فوق حشوة نيكاراغوية. نفحات من القشدة والبندق والتوابل الخفيفة. يرد اسم الخط في صفحة الدار؛ ولا يُذكر فيها عام إطلاقه.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut من الإكوادور"},{"name":"La Antigüedad","color":"#A0522D","force":null,"story":"غلاف مادورو كونيتيكت برودليف فوق حشوة نيكاراغوية. نفحات من الشوكولاتة الداكنة والقهوة الباردة والدبس. يحيل الاسم (ومعناه العراقة)، بحسب أحد بائعي التجزئة، إلى علامة كوبية قديمة جرى البحث عن تصميمها الفني؛ وهي أنعم من Le Bijou 1922.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":null,"story":"خط باسم ابن بيبين، غلاف برودليف كونيتيكت.","vitolas":[],"wrapper":"برودليف كونيتيكت"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":null,"story":"سيجار نيكاراغوي خالص، غلاف مزروع تحت الشمس؛ وتدرجه الدار بين علاماتها الأخرى، ومعه نسخته مادورو.","vitolas":[],"wrapper":"نيكاراغوي خالص"},{"name":"La Dueña","color":"#8B1A6B","force":null,"story":"خط تربطه البطاقة بجاني غارسيا، ابنة الدار؛ غلاف برودليف كونيتيكت.","vitolas":[],"wrapper":"برودليف كونيتيكت"},{"name":"El Centurión","color":"#7A2E1E","force":null,"story":"خط تدرجه الدار (بما في ذلك نسختا H-2K-CT وMaduro)؛ غلاف هابانو نيكاراغوي.","vitolas":[],"wrapper":"هابانو نيكاراغوي"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","story":"في أكتوبر 2026 يصفها تاجر التجزئة Cigarsdaily بأنها أول علامة خاصة لدى My Father من نوع short filler، ويُرمز إليه بـ S.F.، غير أن مراجعة تعود إلى 2010 تصف حشوة مختلطة، نحو 70% منها longfiller من بذور كوبية، مصنوعة من بقايا إنتاج Pepin García. غلاف خارجي Habano من نيكاراغوا فوق رابط وحشوة نيكاراغويين، بمقاس Robusto 5 x 50 المعروض للبيع في ذلك التاريخ، وبمقاس Corona 6 x 46 في 2010.","vitolas":[],"wrapper":"Habano من نيكاراغوا"}]',
  `celebrities` = '[{"name":"José ''Pepin'' García","anecdote":"Né à Cuba en 1950, dit la maison. Il ouvre El Rey de los Habanos à Miami, dans Little Havana, au début des années 2000, puis la Tabacalera Cubana à Estelí en 2006, d''après la presse du métier. Son fils Jaime a créé la marque My Father en 2008."}]',
  `celebrities_en` = '[{"name":"José ''Pepin'' García","anecdote":"Born in Cuba in 1950, says the house. He opens El Rey de los Habanos in Miami, in Little Havana, in the early 2000s, then La Tabacalera Cubana in Estelí in 2006, according to the trade press. His son Jaime created the My Father brand in 2008."}]',
  `celebrities_es` = '[{"name":"José ''Pepin'' García","anecdote":"Nacido en Cuba en 1950, dice la casa. Abre El Rey de los Habanos en Miami, en Little Havana, a principios de los años 2000, y después la Tabacalera Cubana en Estelí en 2006, según la prensa del sector. Su hijo Jaime creó la marca My Father en 2008."}]',
  `celebrities_de` = '[{"name":"José ''Pepin'' García","anecdote":"Geboren 1950 in Kuba, sagt das Haus. Er eröffnet El Rey de los Habanos in Miami, in Little Havana, Anfang der 2000er Jahre, dann die Tabacalera Cubana in Estelí 2006, laut der Fachpresse. Sein Sohn Jaime schuf die Marke My Father 2008."}]',
  `celebrities_zh` = '[{"name":"José ''Pepin'' García","anecdote":"据该公司称，他1950年出生于古巴。据行业媒体，他于21世纪初在迈阿密的 Little Havana 开设 El Rey de los Habanos，2006年又在埃斯特利开设 Tabacalera Cubana。其子 Jaime 于2008年创立 My Father 品牌。"}]',
  `celebrities_ar` = '[{"name":"José ''Pepin'' García","anecdote":"وُلد في كوبا عام 1950، كما تقول الدار. افتتح El Rey de los Habanos في ميامي، في Little Havana، مطلع سنوات الألفين، ثم La Tabacalera Cubana في إستيلي عام 2006، بحسب الصحافة المتخصصة. وأنشأ ابنه Jaime علامة My Father عام 2008."}]',
  `pairings` = '[{"type":"Rhum","name":"Ron Flor de Caña Centenario 25 ans","notes":"Un rhum nicaraguayen vieilli : un accord de terroir avec les cigares d''Estelí, sur les notes de cacao et de canne."},{"type":"Café","name":"Nicaraguan Jinotega single origin","notes":"Café de Jinotega, au nord du pays ; ses notes de fruits noirs et de cacao s''accordent aux assemblages corsés."}]',
  `pairings_en` = '[{"type":"Rum","name":"Ron Flor de Caña Centenario 25 years","notes":"An aged Nicaraguan rum: a pairing of shared terroir with the cigars of Estelí, on notes of cocoa and cane."},{"type":"Coffee","name":"Nicaraguan Jinotega single origin","notes":"Coffee from Jinotega, in the north of the country; its dark-fruit and cocoa notes go well with full-bodied blends."}]',
  `pairings_es` = '[{"type":"Ron","name":"Ron Flor de Caña Centenario 25 years","notes":"Un ron nicaragüense envejecido: un maridaje de terruño con los puros de Estelí, sobre notas de cacao y caña."},{"type":"Café","name":"Nicaraguan Jinotega single origin","notes":"Café de Jinotega, en el norte del país; sus notas de frutos negros y cacao casan con las ligas recias."}]',
  `pairings_de` = '[{"type":"Rum","name":"Ron Flor de Caña Centenario 25 years","notes":"Ein gereifter nicaraguanischer Rum: eine Terroir-Verbindung mit den Zigarren aus Estelí, auf Noten von Kakao und Zuckerrohr."},{"type":"Kaffee","name":"Nicaraguan Jinotega single origin","notes":"Kaffee aus Jinotega, im Norden des Landes; seine Noten von dunklen Früchten und Kakao passen zu den kräftigen Mischungen."}]',
  `pairings_zh` = '[{"type":"朗姆酒","name":"Ron Flor de Caña Centenario 25 years","notes":"陈年的尼加拉瓜朗姆：与埃斯特利的雪茄是风土上的呼应，围绕可可与甘蔗的气息。"},{"type":"咖啡","name":"Nicaraguan Jinotega single origin","notes":"来自希诺特加、位于该国北部的咖啡；其黑色水果与可可气息与浓郁的配方相契合。"}]',
  `pairings_ar` = '[{"type":"الروم","name":"Ron Flor de Caña Centenario 25 years","notes":"روم نيكاراغوي معتَّق: توافق تربة واحدة مع سيجار إستيلي، على نفحات من الكاكاو وقصب السكر."},{"type":"القهوة","name":"Nicaraguan Jinotega single origin","notes":"قهوة من خينوتيغا، في شمال البلاد؛ وتتوافق نفحاتها من الفواكه الداكنة والكاكاو مع الخلطات القوية."}]',
  `source` = IF(LOCATE(CAST('myfathercigars.com (accueil, octobre 2026 : Pepín né à Cuba ' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'myfathercigars.com (accueil, octobre 2026 : Pepín né à Cuba en 1950, troisième génération, 3 fabriques dont Estelí, El Paraíso et Doral, 24 marques, liste des lignes sans années) ; cigaraficionado.com « The Mission of My Father » (départ de Cuba 2001, El Rey de los Habanos 2003 à Little Havana avec Aganorsa, Tabacalera Cubana 2006, marque My Father 2008 par Jaime, usine 2009) ; cigarsdirect.com Le Bijou 1922 (détaillant, résultat de recherche : 1922 = année de naissance du père de Pepín)')),
  `updated_at` = NOW()
 WHERE `name` = 'My Father';

-- ── Oliva ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''histoire de la famille Oliva commence dans la province de Pinar del Río, à Cuba, en 1886 — quand elle planta pour la première fois du tabac à l''extrémité ouest de l''île, dans ce qu''on allait appeler la Vuelta Abajo. Pendant plus de soixante ans, les Oliva cultivèrent dans cette terre rouge, y acquérant le savoir que leurs descendants emporteraient en exil.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''histoire de la famille Oliva commence dans la province de Pinar del Río, à Cuba, en 1886 — quand elle planta pour la première fois du tabac à l''extrémité ouest de l''île, dans ce qu''on allait appeler la Vuelta Abajo. Pendant plus de soixante ans, les Oliva cultivèrent dans cette terre rouge, y acquérant le savoir que leurs descendants emporteraient en exil.', 'L''histoire de la famille Oliva commence à Pinar del Río, à Cuba : selon la maison, Melanio Oliva y cultiva du tabac pour la première fois en 1886, interrompit ses cultures pour la guerre d''indépendance cubaine, puis les reprit. Son fils Facundo, dit la maison, prit la suite au début des années 1920 (Wikipédia nomme Hipolito).'), `history`),
  `history_en` = IF(LOCATE(CAST(CONCAT('The Oliva family story begins in Pinar del Río Province, Cuba, in 1886 — when the family first planted tobacco in the western end of the island that would become known as Vuelta Abajo. For over sixty years, the Olivas grew tobacco in that red soil, developing the cultivation knowledge that their descendants would carry into exile.', CHAR(13), '
', CHAR(13), '
When Oswaldo Oliva left Cuba after the revolution, he brought seeds, agricultural knowledge, and the understanding that good tobacco required specific conditions to express its quality. After periods in Honduras and Miami, he established plantations in Nicaragua''s Jalapa Valley in 1968 — a growing region where the combination of volcanic soil, altitude, and consistent humidity creates conditions that experienced tasters recognize as the closest analog to Vuelta Abajo outside Cuba.', CHAR(13), '
', CHAR(13), '
For nearly three decades, Oliva was the industry''s best-kept open secret. If you smoked a premium Nicaraguan or Honduran cigar between 1970 and 1995, there was a reasonable probability that the leaf in your hand had been grown on Oliva land and sold to the manufacturer who put their name on the band. Davidoff, Padrón, Ashton, and dozens of others sourced Oliva leaf. The family sold it without complaint and without publicity. They were growers, not brand builders.', CHAR(13), '
', CHAR(13), '
The third generation changed that calculation. In 1995, convinced that the family''s leaf quality deserved its own identity, they launched Oliva Cigars. The family''s structural advantage is ownership. Every leaf that goes into an Oliva cigar was grown on family-owned land in Jalapa or Estelí. Gilberto Oliva Jr. inspects his plantations personally, on horseback, every growing season. This connection between the family and the soil has produced a consistency of quality across three decades of commercial production that no contract-sourcing arrangement can match.

In 2023 Oliva opened the Black Swan series. The name belongs to the American retailer CigarPage, not to the house: every edition of the series is entrusted to a different factory and built on a particular lot of tobacco found there. The Oliva edition is rolled in Nicaragua, under a Connecticut Broadleaf wrapper, over an Ecuadorian binder and Nicaraguan filler. Rocky Patel, E.P. Carrillo and Joya de Nicaragua made the three that followed — all three in this atlas.

Oliva also rolls Rustico, for a single line, which the retailer Atlantic Cigar Company, launched in the late 1990s, sells under the name Rustico Habano. In October 2026, only the Reserve line is given there as made by Oliva, in Nicaragua: Ecuadorian Habano wrapper, Nicaraguan binder and filler, hand-rolled longfiller, in Gordo 4 x 60. The Habano line is given there as Dominican, with no factory named.') AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, CONCAT('The Oliva family story begins in Pinar del Río Province, Cuba, in 1886 — when the family first planted tobacco in the western end of the island that would become known as Vuelta Abajo. For over sixty years, the Olivas grew tobacco in that red soil, developing the cultivation knowledge that their descendants would carry into exile.', CHAR(13), '
', CHAR(13), '
When Oswaldo Oliva left Cuba after the revolution, he brought seeds, agricultural knowledge, and the understanding that good tobacco required specific conditions to express its quality. After periods in Honduras and Miami, he established plantations in Nicaragua''s Jalapa Valley in 1968 — a growing region where the combination of volcanic soil, altitude, and consistent humidity creates conditions that experienced tasters recognize as the closest analog to Vuelta Abajo outside Cuba.', CHAR(13), '
', CHAR(13), '
For nearly three decades, Oliva was the industry''s best-kept open secret. If you smoked a premium Nicaraguan or Honduran cigar between 1970 and 1995, there was a reasonable probability that the leaf in your hand had been grown on Oliva land and sold to the manufacturer who put their name on the band. Davidoff, Padrón, Ashton, and dozens of others sourced Oliva leaf. The family sold it without complaint and without publicity. They were growers, not brand builders.', CHAR(13), '
', CHAR(13), '
The third generation changed that calculation. In 1995, convinced that the family''s leaf quality deserved its own identity, they launched Oliva Cigars. The family''s structural advantage is ownership. Every leaf that goes into an Oliva cigar was grown on family-owned land in Jalapa or Estelí. Gilberto Oliva Jr. inspects his plantations personally, on horseback, every growing season. This connection between the family and the soil has produced a consistency of quality across three decades of commercial production that no contract-sourcing arrangement can match.

In 2023 Oliva opened the Black Swan series. The name belongs to the American retailer CigarPage, not to the house: every edition of the series is entrusted to a different factory and built on a particular lot of tobacco found there. The Oliva edition is rolled in Nicaragua, under a Connecticut Broadleaf wrapper, over an Ecuadorian binder and Nicaraguan filler. Rocky Patel, E.P. Carrillo and Joya de Nicaragua made the three that followed — all three in this atlas.

Oliva also rolls Rustico, for a single line, which the retailer Atlantic Cigar Company, launched in the late 1990s, sells under the name Rustico Habano. In October 2026, only the Reserve line is given there as made by Oliva, in Nicaragua: Ecuadorian Habano wrapper, Nicaraguan binder and filler, hand-rolled longfiller, in Gordo 4 x 60. The Habano line is given there as Dominican, with no factory named.'), 'The history of the Oliva family begins in Pinar del Río, Cuba: according to the house, Melanio Oliva first grew tobacco there in 1886, interrupted his crops for the Cuban war of independence, then resumed them. His son Facundo, says the house, took over in the early 1920s (Wikipedia names Hipolito).

When Cuba changed regime, the grandson Gilberto Oliva moved from growing to tobacco brokerage. According to the house, he left the island in the early 1960s and looked in Honduras, Panama, Mexico and the Philippines for conditions close to the Cuban taste, before settling in Nicaragua. The dates differ: Wikipedia has him leave for Spain in 1964, grow in Nicaragua in 1969, then leave the country in 1979 and return in 1995.

For years the family was grower and broker, with no brand in its own name. His son José says that Gilberto senior grew tobacco every year and put it aside (trade press, December 2017). No page read names the manufacturers who bought.

In 1995, Gilberto Oliva and his son Gilberto Jr. made a cigar in the factory of Néstor Plasencia senior, in Honduras, which they named Gilberto Oliva; a year later they opened their own factory in Nicaragua and shortened the name to Oliva. The Serie V is the house''s flagship line; its year of launch differs between sources (2004 in the former profile, 2006 according to Wikipedia, June 2007 according to Halfwheel).

The family grows Cuban-seed tobacco in Nicaragua, says the house. In July 2016, Oliva Cigar Co. was bought by the Belgian group J. Cortès; in 2021, the trade press describes it as its subsidiary, the family remaining at the head of the company in Miami Lakes (Florida).

In 2023 Oliva opened the Black Swan series. The name belongs to the American retailer CigarPage, not to the house: every edition of the series is entrusted to a different factory and built on a particular lot of tobacco found there. The Oliva edition is rolled in Nicaragua, under a Connecticut Broadleaf wrapper, over an Ecuadorian binder and Nicaraguan filler. Rocky Patel, E.P. Carrillo and Joya de Nicaragua made the three that followed — all three in this atlas.

Oliva also rolls Rustico, for a single line, which the retailer Atlantic Cigar Company, launched in the late 1990s, sells under the name Rustico Habano. In October 2026, only the Reserve line is given there as made by Oliva, in Nicaragua: Ecuadorian Habano wrapper, Nicaraguan binder and filler, hand-rolled longfiller, in Gordo 4 x 60. The Habano line is given there as Dominican, with no factory named.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La historia de la familia Oliva empieza en la provincia de Pinar del Río, en Cuba, en 1886 —cuando plantó por primera vez tabaco en el extremo occidental de la isla, en lo que se llamaría la Vuelta Abajo. Durante más de sesenta años, los Oliva cultivaron en esa tierra roja, adquiriendo allí el saber que sus descendientes se llevarían al exilio.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La historia de la familia Oliva empieza en la provincia de Pinar del Río, en Cuba, en 1886 —cuando plantó por primera vez tabaco en el extremo occidental de la isla, en lo que se llamaría la Vuelta Abajo. Durante más de sesenta años, los Oliva cultivaron en esa tierra roja, adquiriendo allí el saber que sus descendientes se llevarían al exilio.', 'La historia de la familia Oliva empieza en Pinar del Río, en Cuba: según la casa, Melanio Oliva cultivó allí tabaco por primera vez en 1886, interrumpió sus cultivos por la guerra de independencia cubana y luego los retomó. Su hijo Facundo, dice la casa, tomó el relevo a principios de los años 1920 (Wikipedia nombra a Hipolito).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Geschichte der Familie Oliva beginnt 1886 in der Provinz Pinar del Río auf Kuba — als sie zum ersten Mal Tabak am westlichen Ende der Insel pflanzte, in dem, was man später Vuelta Abajo nennen sollte. Über sechzig Jahre lang bauten die Oliva auf dieser roten Erde an und erwarben dort das Wissen, das ihre Nachkommen ins Exil mitnehmen sollten.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Geschichte der Familie Oliva beginnt 1886 in der Provinz Pinar del Río auf Kuba — als sie zum ersten Mal Tabak am westlichen Ende der Insel pflanzte, in dem, was man später Vuelta Abajo nennen sollte. Über sechzig Jahre lang bauten die Oliva auf dieser roten Erde an und erwarben dort das Wissen, das ihre Nachkommen ins Exil mitnehmen sollten.', 'Die Geschichte der Familie Oliva beginnt in Pinar del Río auf Kuba: Laut dem Haus baute Melanio Oliva dort 1886 zum ersten Mal Tabak an, unterbrach seinen Anbau wegen des kubanischen Unabhängigkeitskrieges und nahm ihn dann wieder auf. Sein Sohn Facundo übernahm, sagt das Haus, Anfang der 1920er Jahre (Wikipedia nennt Hipolito).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('奥利瓦家族的故事始于1886年古巴的比那尔德里奥省——那一年，他们第一次在岛的最西端、后来被称作阿巴霍谷的那片土地上种下烟草。六十多年里，奥利瓦一家在这片红土上耕作，也在那里积下了后代日后带去流亡的本事。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '奥利瓦家族的故事始于1886年古巴的比那尔德里奥省——那一年，他们第一次在岛的最西端、后来被称作阿巴霍谷的那片土地上种下烟草。六十多年里，奥利瓦一家在这片红土上耕作，也在那里积下了后代日后带去流亡的本事。', '奥利瓦家族的故事始于古巴的比那尔德里奥：据该公司称，Melanio Oliva 于1886年在那里首次种植烟草，后因古巴独立战争中断种植，随后又恢复。公司称，他的儿子 Facundo 在20世纪20年代初接手（维基百科称是 Hipolito）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('يبدأ تاريخ عائلة أوليفا في مقاطعة بينار ديل ريو بكوبا، عام 1886 — حين زرعت التبغ لأول مرة في أقصى غرب الجزيرة، فيما سيُسمّى لاحقًا فويلتا أباخو. وطوال أكثر من ستين عامًا زرع آل أوليفا هذه الأرض الحمراء، وكسبوا فيها المعرفة التي سيحملها أحفادهم إلى المنفى.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'يبدأ تاريخ عائلة أوليفا في مقاطعة بينار ديل ريو بكوبا، عام 1886 — حين زرعت التبغ لأول مرة في أقصى غرب الجزيرة، فيما سيُسمّى لاحقًا فويلتا أباخو. وطوال أكثر من ستين عامًا زرع آل أوليفا هذه الأرض الحمراء، وكسبوا فيها المعرفة التي سيحملها أحفادهم إلى المنفى.', 'يبدأ تاريخ عائلة أوليفا في بينار ديل ريو بكوبا: فبحسب الدار، زرع Melanio Oliva التبغ هناك لأول مرة عام 1886، وأوقف زراعته بسبب حرب الاستقلال الكوبية ثم استأنفها. وتقول الدار إن ابنه Facundo تولّى الأمر في مطلع عشرينيات القرن الماضي (وتسمّي ويكيبيديا Hipolito).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Quand Oswaldo Oliva quitta Cuba après la révolution, il emporta des semences, un savoir agricole, et la conviction qu''un bon tabac exige des conditions précises pour donner sa mesure. Après des séjours au Honduras et à Miami, il établit en 1968 des plantations dans la vallée nicaraguayenne de Jalapa — une région où sols volcaniques, altitude et humidité constante créent ce que les dégustateurs expérimentés reconnaissent comme l''équivalent le plus proche de la Vuelta Abajo hors de Cuba.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Quand Oswaldo Oliva quitta Cuba après la révolution, il emporta des semences, un savoir agricole, et la conviction qu''un bon tabac exige des conditions précises pour donner sa mesure. Après des séjours au Honduras et à Miami, il établit en 1968 des plantations dans la vallée nicaraguayenne de Jalapa — une région où sols volcaniques, altitude et humidité constante créent ce que les dégustateurs expérimentés reconnaissent comme l''équivalent le plus proche de la Vuelta Abajo hors de Cuba.', 'Quand Cuba changea de régime, le petit-fils Gilberto Oliva passa de la culture au courtage de tabac. Selon la maison, il quitta l''île au début des années 1960 et chercha au Honduras, au Panama, au Mexique et aux Philippines des conditions proches du goût cubain, avant de s''établir au Nicaragua. Les dates divergent : Wikipédia le fait partir pour l''Espagne en 1964, cultiver au Nicaragua en 1969, puis quitter le pays en 1979 pour y revenir en 1995.'), `history`),
  `history_es` = IF(LOCATE(CAST('Cuando Oswaldo Oliva dejó Cuba después de la revolución, se llevó semillas, un saber agrícola y la convicción de que un buen tabaco exige condiciones precisas para dar su medida. Tras estancias en Honduras y en Miami, estableció en 1968 plantaciones en el valle nicaragüense de Jalapa —una región donde suelos volcánicos, altitud y humedad constante crean lo que los catadores experimentados reconocen como el equivalente más cercano a la Vuelta Abajo fuera de Cuba.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Cuando Oswaldo Oliva dejó Cuba después de la revolución, se llevó semillas, un saber agrícola y la convicción de que un buen tabaco exige condiciones precisas para dar su medida. Tras estancias en Honduras y en Miami, estableció en 1968 plantaciones en el valle nicaragüense de Jalapa —una región donde suelos volcánicos, altitud y humedad constante crean lo que los catadores experimentados reconocen como el equivalente más cercano a la Vuelta Abajo fuera de Cuba.', 'Cuando Cuba cambió de régimen, el nieto Gilberto Oliva pasó del cultivo al corretaje de tabaco. Según la casa, dejó la isla a principios de los años 1960 y buscó en Honduras, Panamá, México y Filipinas condiciones cercanas al gusto cubano, antes de establecerse en Nicaragua. Las fechas divergen: Wikipedia lo hace partir a España en 1964, cultivar en Nicaragua en 1969, y luego dejar el país en 1979 para volver en 1995.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Als Oswaldo Oliva Kuba nach der Revolution verließ, nahm er Saatgut mit, ein landwirtschaftliches Wissen und die Überzeugung, dass guter Tabak genaue Bedingungen braucht, um sein Maß zu zeigen. Nach Aufenthalten in Honduras und Miami legte er 1968 Plantagen im nicaraguanischen Tal von Jalapa an — einer Gegend, in der vulkanische Böden, Höhenlage und gleichbleibende Feuchte das schaffen, was erfahrene Verkoster als die nächste Entsprechung zur Vuelta Abajo außerhalb Kubas erkennen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Als Oswaldo Oliva Kuba nach der Revolution verließ, nahm er Saatgut mit, ein landwirtschaftliches Wissen und die Überzeugung, dass guter Tabak genaue Bedingungen braucht, um sein Maß zu zeigen. Nach Aufenthalten in Honduras und Miami legte er 1968 Plantagen im nicaraguanischen Tal von Jalapa an — einer Gegend, in der vulkanische Böden, Höhenlage und gleichbleibende Feuchte das schaffen, was erfahrene Verkoster als die nächste Entsprechung zur Vuelta Abajo außerhalb Kubas erkennen.', 'Als Kuba das Regime wechselte, ging der Enkel Gilberto Oliva vom Anbau zum Tabakmaklergeschäft über. Laut dem Haus verließ er die Insel Anfang der 1960er Jahre und suchte in Honduras, Panama, Mexiko und auf den Philippinen nach Bedingungen, die dem kubanischen Geschmack nahekamen, bevor er sich in Nicaragua niederließ. Die Daten weichen ab: Wikipedia lässt ihn 1964 nach Spanien gehen, 1969 in Nicaragua anbauen, das Land dann 1979 verlassen und 1995 zurückkehren.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('革命之后奥斯瓦尔多·奥利瓦离开古巴时，带走的是种子、一身农艺，以及一个信念：好烟草需要精确的条件才能显出它的分量。在洪都拉斯与迈阿密辗转之后，他于1968年在尼加拉瓜的哈拉帕山谷建起种植园——那里的火山土壤、海拔与恒定湿度，造出了老练的品鉴者公认的、古巴之外最接近阿巴霍谷的条件。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '革命之后奥斯瓦尔多·奥利瓦离开古巴时，带走的是种子、一身农艺，以及一个信念：好烟草需要精确的条件才能显出它的分量。在洪都拉斯与迈阿密辗转之后，他于1968年在尼加拉瓜的哈拉帕山谷建起种植园——那里的火山土壤、海拔与恒定湿度，造出了老练的品鉴者公认的、古巴之外最接近阿巴霍谷的条件。', '古巴政权更迭时，孙辈的 Gilberto Oliva 由种植转向烟草经纪。据该公司称，他在20世纪60年代初离开古巴，先后到洪都拉斯、巴拿马、墨西哥和菲律宾寻找接近古巴口味的条件，之后才在尼加拉瓜安顿下来。各处日期不一：维基百科称他1964年前往西班牙，1969年在尼加拉瓜种植，1979年离开该国，1995年回来。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وحين غادر أوسفالدو أوليفا كوبا بعد الثورة، حمل معه بذورًا، ومعرفة زراعية، وقناعةً بأن التبغ الجيد يحتاج شروطًا دقيقة كي يُظهر قدره. وبعد إقامات في هندوراس وميامي، أنشأ عام 1968 مزارع في وادي خالابا النيكاراغوي — منطقة تخلق فيها التربة البركانية والارتفاع والرطوبة الثابتة ما يعدّه الذوّاقة المتمرّسون أقرب مكافئ لفويلتا أباخو خارج كوبا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وحين غادر أوسفالدو أوليفا كوبا بعد الثورة، حمل معه بذورًا، ومعرفة زراعية، وقناعةً بأن التبغ الجيد يحتاج شروطًا دقيقة كي يُظهر قدره. وبعد إقامات في هندوراس وميامي، أنشأ عام 1968 مزارع في وادي خالابا النيكاراغوي — منطقة تخلق فيها التربة البركانية والارتفاع والرطوبة الثابتة ما يعدّه الذوّاقة المتمرّسون أقرب مكافئ لفويلتا أباخو خارج كوبا.', 'عندما تغيّر النظام في كوبا، انتقل الحفيد Gilberto Oliva من الزراعة إلى سمسرة التبغ. وبحسب الدار، غادر الجزيرة في مطلع ستينيات القرن الماضي، وبحث في هندوراس وبنما والمكسيك والفلبين عن شروط قريبة من الذوق الكوبي، قبل أن يستقر في نيكاراغوا. وتتباين التواريخ: فتجعله ويكيبيديا يغادر إلى إسبانيا عام 1964، ويزرع في نيكاراغوا عام 1969، ثم يترك البلد عام 1979 ليعود إليه عام 1995.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Pendant près de trois décennies, Oliva fut le secret le moins bien gardé du métier. Si vous avez fumé un cigare premium nicaraguayen ou hondurien entre 1970 et 1995, il y a de bonnes chances que la feuille que vous teniez ait poussé sur des terres Oliva avant d''être vendue au fabricant dont le nom figurait sur la bague. Davidoff, Padrón, Ashton et des dizaines d''autres s''y sont approvisionnés. La famille vendait sans se plaindre et sans publicité : ils étaient planteurs, pas bâtisseurs de marque.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Pendant près de trois décennies, Oliva fut le secret le moins bien gardé du métier. Si vous avez fumé un cigare premium nicaraguayen ou hondurien entre 1970 et 1995, il y a de bonnes chances que la feuille que vous teniez ait poussé sur des terres Oliva avant d''être vendue au fabricant dont le nom figurait sur la bague. Davidoff, Padrón, Ashton et des dizaines d''autres s''y sont approvisionnés. La famille vendait sans se plaindre et sans publicité : ils étaient planteurs, pas bâtisseurs de marque.', 'Pendant des années, la famille fut planteuse et courtière, sans marque à son nom. Son fils José raconte que Gilberto père faisait pousser du tabac chaque année et le mettait de côté (presse du métier, décembre 2017). Aucune page lue ne nomme les fabricants acheteurs.'), `history`),
  `history_es` = IF(LOCATE(CAST('Durante casi tres décadas, Oliva fue el secreto peor guardado del oficio. Si usted fumó un puro premium nicaragüense u hondureño entre 1970 y 1995, hay buenas probabilidades de que la hoja que sostenía hubiera crecido en tierras Oliva antes de venderse al fabricante cuyo nombre figuraba en la anilla. Davidoff, Padrón, Ashton y decenas de otros se abastecieron allí. La familia vendía sin quejarse y sin publicidad: eran plantadores, no constructores de marca.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Durante casi tres décadas, Oliva fue el secreto peor guardado del oficio. Si usted fumó un puro premium nicaragüense u hondureño entre 1970 y 1995, hay buenas probabilidades de que la hoja que sostenía hubiera crecido en tierras Oliva antes de venderse al fabricante cuyo nombre figuraba en la anilla. Davidoff, Padrón, Ashton y decenas de otros se abastecieron allí. La familia vendía sin quejarse y sin publicidad: eran plantadores, no constructores de marca.', 'Durante años, la familia fue plantadora y corredora, sin marca a su nombre. Su hijo José cuenta que Gilberto padre hacía crecer tabaco cada año y lo guardaba (prensa del sector, diciembre de 2017). Ninguna página leída nombra a los fabricantes compradores.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Fast drei Jahrzehnte lang war Oliva das schlechtest gehütete Geheimnis des Fachs. Wer zwischen 1970 und 1995 eine nicaraguanische oder honduranische Premiumzigarre rauchte, hielt mit guter Wahrscheinlichkeit ein Blatt in der Hand, das auf Oliva-Land gewachsen war, bevor es an den Hersteller verkauft wurde, dessen Name auf der Banderole stand. Davidoff, Padrón, Ashton und Dutzende andere bezogen dort. Die Familie verkaufte ohne Klage und ohne Werbung: Sie waren Pflanzer, keine Markenbauer.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Fast drei Jahrzehnte lang war Oliva das schlechtest gehütete Geheimnis des Fachs. Wer zwischen 1970 und 1995 eine nicaraguanische oder honduranische Premiumzigarre rauchte, hielt mit guter Wahrscheinlichkeit ein Blatt in der Hand, das auf Oliva-Land gewachsen war, bevor es an den Hersteller verkauft wurde, dessen Name auf der Banderole stand. Davidoff, Padrón, Ashton und Dutzende andere bezogen dort. Die Familie verkaufte ohne Klage und ohne Werbung: Sie waren Pflanzer, keine Markenbauer.', 'Jahrelang war die Familie Pflanzer und Makler, ohne Marke unter eigenem Namen. Sein Sohn José erzählt, dass der Vater Gilberto jedes Jahr Tabak anbaute und ihn zurücklegte (Fachpresse, Dezember 2017). Keine der gelesenen Seiten nennt die kaufenden Hersteller.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('将近三十年里，奥利瓦是这一行里守得最差的秘密。若你在1970年至1995年间抽过一支尼加拉瓜或洪都拉斯的高端雪茄，你手里那片叶子很可能长在奥利瓦的地里，然后才卖给了烟标上署名的那家厂。大卫杜夫、帕德龙、阿什顿，以及几十家别的字号，都从这里进货。这个家族卖得毫无怨言，也不做宣传：他们是种植者，不是品牌营造者。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '将近三十年里，奥利瓦是这一行里守得最差的秘密。若你在1970年至1995年间抽过一支尼加拉瓜或洪都拉斯的高端雪茄，你手里那片叶子很可能长在奥利瓦的地里，然后才卖给了烟标上署名的那家厂。大卫杜夫、帕德龙、阿什顿，以及几十家别的字号，都从这里进货。这个家族卖得毫无怨言，也不做宣传：他们是种植者，不是品牌营造者。', '多年来，这个家族是种植者兼经纪商，没有以自己名字命名的品牌。其子 José 说，老 Gilberto 每年都种烟草并把它留存起来（行业媒体，2017年12月）。所查阅的页面均未点名购买烟叶的制造商。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وطوال ثلاثة عقود تقريبًا، كانت أوليفا أسوأ أسرار المهنة حفظًا. فمن دخّن سيجارًا فاخرًا نيكاراغويًّا أو هندوراسيًّا بين 1970 و1995، يُرجَّح أن الورقة التي بين يديه نبتت في أرض أوليفا قبل أن تُباع إلى الصانع الذي حمل اسمُه الحلقة. دافيدوف، وبادرون، وآشتون، وعشرات غيرهم تزوّدوا من هناك. وكانت العائلة تبيع بلا شكوى وبلا إعلان: كانوا مزارعين، لا بُناة علامات.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وطوال ثلاثة عقود تقريبًا، كانت أوليفا أسوأ أسرار المهنة حفظًا. فمن دخّن سيجارًا فاخرًا نيكاراغويًّا أو هندوراسيًّا بين 1970 و1995، يُرجَّح أن الورقة التي بين يديه نبتت في أرض أوليفا قبل أن تُباع إلى الصانع الذي حمل اسمُه الحلقة. دافيدوف، وبادرون، وآشتون، وعشرات غيرهم تزوّدوا من هناك. وكانت العائلة تبيع بلا شكوى وبلا إعلان: كانوا مزارعين، لا بُناة علامات.', 'ظلّت العائلة سنوات مزارعة وسمسارة، من دون علامة تحمل اسمها. ويروي ابنه José أن Gilberto الأب كان يزرع التبغ كل سنة ويدّخره (الصحافة المتخصصة، كانون الأول/ديسمبر 2017). ولا تذكر أي صفحة مقروءة أسماء المصنّعين المشترين.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La troisième génération changea ce calcul. En 1995, convaincue que la qualité de sa feuille méritait une identité propre, elle lança Oliva Cigars. La Serie V — pour Vuelta, en hommage au Vuelta Abajo cubain — fut lancée en 2004 et devint la gamme sur laquelle la maison serait jugée.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La troisième génération changea ce calcul. En 1995, convaincue que la qualité de sa feuille méritait une identité propre, elle lança Oliva Cigars. La Serie V — pour Vuelta, en hommage au Vuelta Abajo cubain — fut lancée en 2004 et devint la gamme sur laquelle la maison serait jugée.', 'En 1995, Gilberto Oliva et son fils Gilberto Jr. firent un cigare dans la fabrique de Néstor Plasencia père, au Honduras, qu''ils nommèrent Gilberto Oliva ; un an plus tard, ils ouvrirent leur propre fabrique au Nicaragua et raccourcirent le nom en Oliva. La Serie V est la ligne phare de la maison ; son année de lancement diverge selon les sources (2004 dans l''ancienne fiche, 2006 selon Wikipédia, juin 2007 selon Halfwheel).'), `history`),
  `history_es` = IF(LOCATE(CAST('La tercera generación cambió ese cálculo. En 1995, convencida de que la calidad de su hoja merecía una identidad propia, lanzó Oliva Cigars. La Serie V —por Vuelta, en homenaje al Vuelta Abajo cubano— se lanzó en 2004 y se convirtió en la gama por la que se juzgaría a la casa.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La tercera generación cambió ese cálculo. En 1995, convencida de que la calidad de su hoja merecía una identidad propia, lanzó Oliva Cigars. La Serie V —por Vuelta, en homenaje al Vuelta Abajo cubano— se lanzó en 2004 y se convirtió en la gama por la que se juzgaría a la casa.', 'En 1995, Gilberto Oliva y su hijo Gilberto Jr. hicieron un puro en la fábrica de Néstor Plasencia padre, en Honduras, al que llamaron Gilberto Oliva; un año después abrieron su propia fábrica en Nicaragua y acortaron el nombre a Oliva. La Serie V es la línea insignia de la casa; su año de lanzamiento diverge según las fuentes (2004 en la ficha anterior, 2006 según Wikipedia, junio de 2007 según Halfwheel).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die dritte Generation änderte diese Rechnung. 1995, überzeugt, dass die Güte ihres Blattes eine eigene Identität verdiente, gründete sie Oliva Cigars. Die Serie V — für Vuelta, als Verbeugung vor der kubanischen Vuelta Abajo — kam 2004 heraus und wurde zu der Linie, an der das Haus gemessen wird.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die dritte Generation änderte diese Rechnung. 1995, überzeugt, dass die Güte ihres Blattes eine eigene Identität verdiente, gründete sie Oliva Cigars. Die Serie V — für Vuelta, als Verbeugung vor der kubanischen Vuelta Abajo — kam 2004 heraus und wurde zu der Linie, an der das Haus gemessen wird.', '1995 stellten Gilberto Oliva und sein Sohn Gilberto Jr. in der Fabrik von Néstor Plasencia dem Älteren in Honduras eine Zigarre her, die sie Gilberto Oliva nannten; ein Jahr später eröffneten sie ihre eigene Fabrik in Nicaragua und kürzten den Namen zu Oliva. Die Serie V ist die Flaggschiff-Linie des Hauses; ihr Einführungsjahr weicht je nach Quelle ab (2004 im früheren Eintrag, 2006 laut Wikipedia, Juni 2007 laut Halfwheel).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('第三代改变了这笔账。1995年，他们确信自家叶子的品质配得上一个自己的名号，于是推出了奥利瓦雪茄。V系列——V 取自 Vuelta，向古巴的阿巴霍谷致意——于2004年问世，并成为衡量这家字号的那条线。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '第三代改变了这笔账。1995年，他们确信自家叶子的品质配得上一个自己的名号，于是推出了奥利瓦雪茄。V系列——V 取自 Vuelta，向古巴的阿巴霍谷致意——于2004年问世，并成为衡量这家字号的那条线。', '1995年，Gilberto Oliva 与其子 Gilberto Jr. 在洪都拉斯老 Néstor Plasencia 的工厂里做了一款雪茄，取名 Gilberto Oliva；一年后，他们在尼加拉瓜开设了自己的工厂，并把名字缩短为 Oliva。Serie V 是该公司的主打系列；其推出年份因来源而异（旧资料页为2004年，据维基百科为2006年，据 Halfwheel 为2007年6月）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('غيّر الجيل الثالث هذه الحسبة. ففي 1995، اقتناعًا بأن جودة ورقتهم تستحق هوية خاصة، أطلقوا «أوليفا سيغارز». وصدرت السلسلة V — نسبةً إلى فويلتا، تحيةً لفويلتا أباخو الكوبية — عام 2004، وصارت التشكيلة التي تُقاس بها الدار.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'غيّر الجيل الثالث هذه الحسبة. ففي 1995، اقتناعًا بأن جودة ورقتهم تستحق هوية خاصة، أطلقوا «أوليفا سيغارز». وصدرت السلسلة V — نسبةً إلى فويلتا، تحيةً لفويلتا أباخو الكوبية — عام 2004، وصارت التشكيلة التي تُقاس بها الدار.', 'في عام 1995 صنع Gilberto Oliva وابنه Gilberto Jr. سيجارًا في مصنع Néstor Plasencia الأب في هندوراس، وسمّياه Gilberto Oliva؛ وبعد عام افتتحا مصنعهما الخاص في نيكاراغوا واختصرا الاسم إلى Oliva. والـSerie V هي الخط الرئيسي للدار؛ وتختلف سنة إطلاقها بحسب المصادر (2004 في البطاقة السابقة، و2006 بحسب ويكيبيديا، وحزيران/يونيو 2007 بحسب Halfwheel).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''avantage structurel de la maison tient à la propriété : chaque feuille qui entre dans un cigare Oliva a poussé sur des terres familiales, à Jalapa ou à Estelí. Gilberto Oliva Jr. inspecte ses plantations en personne, à cheval, à chaque saison. Ce lien direct entre la famille et le sol explique une régularité que peu d''approvisionnements sous contrat permettent.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''avantage structurel de la maison tient à la propriété : chaque feuille qui entre dans un cigare Oliva a poussé sur des terres familiales, à Jalapa ou à Estelí. Gilberto Oliva Jr. inspecte ses plantations en personne, à cheval, à chaque saison. Ce lien direct entre la famille et le sol explique une régularité que peu d''approvisionnements sous contrat permettent.', 'La famille cultive du tabac de graine cubaine au Nicaragua, dit la maison. En juillet 2016, Oliva Cigar Co. a été rachetée par le groupe belge J. Cortès ; en 2021, la presse du métier la décrit comme sa filiale, la famille restant à la tête de l''entreprise à Miami Lakes (Floride).'), `history`),
  `history_es` = IF(LOCATE(CAST('La ventaja estructural de la casa está en la propiedad: cada hoja que entra en un puro Oliva ha crecido en tierras familiares, en Jalapa o en Estelí. Gilberto Oliva Jr. inspecciona sus plantaciones en persona, a caballo, cada temporada. Ese vínculo directo entre la familia y el suelo explica una regularidad que pocos abastecimientos por contrato permiten.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La ventaja estructural de la casa está en la propiedad: cada hoja que entra en un puro Oliva ha crecido en tierras familiares, en Jalapa o en Estelí. Gilberto Oliva Jr. inspecciona sus plantaciones en persona, a caballo, cada temporada. Ese vínculo directo entre la familia y el suelo explica una regularidad que pocos abastecimientos por contrato permiten.', 'La familia cultiva en Nicaragua tabaco de semilla cubana, dice la casa. En julio de 2016, Oliva Cigar Co. fue comprada por el grupo belga J. Cortès; en 2021, la prensa del sector la describe como su filial, y la familia sigue al frente de la empresa en Miami Lakes (Florida).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der strukturelle Vorteil des Hauses liegt im Besitz: Jedes Blatt, das in eine Oliva-Zigarre eingeht, ist auf Familienland gewachsen, in Jalapa oder Estelí. Gilberto Oliva Jr. begeht seine Plantagen in jeder Saison selbst, zu Pferd. Diese unmittelbare Bindung zwischen Familie und Boden erklärt eine Gleichmäßigkeit, die wenige Lieferverträge zulassen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der strukturelle Vorteil des Hauses liegt im Besitz: Jedes Blatt, das in eine Oliva-Zigarre eingeht, ist auf Familienland gewachsen, in Jalapa oder Estelí. Gilberto Oliva Jr. begeht seine Plantagen in jeder Saison selbst, zu Pferd. Diese unmittelbare Bindung zwischen Familie und Boden erklärt eine Gleichmäßigkeit, die wenige Lieferverträge zulassen.', 'Die Familie baut in Nicaragua Tabak aus kubanischem Saatgut an, sagt das Haus. Im Juli 2016 wurde Oliva Cigar Co. von der belgischen Gruppe J. Cortès übernommen; 2021 beschreibt die Fachpresse sie als deren Tochtergesellschaft, wobei die Familie in Miami Lakes (Florida) weiterhin an der Spitze des Unternehmens steht.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这家字号在结构上的优势在于所有权：进入一支奥利瓦雪茄的每一片叶子，都长在哈拉帕或埃斯特利的家族土地上。吉尔贝托·奥利瓦二世每季都亲自骑马巡视自家的种植园。家族与土地之间这条直接的联系，解释了一种少有合同供货能够保证的稳定。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这家字号在结构上的优势在于所有权：进入一支奥利瓦雪茄的每一片叶子，都长在哈拉帕或埃斯特利的家族土地上。吉尔贝托·奥利瓦二世每季都亲自骑马巡视自家的种植园。家族与土地之间这条直接的联系，解释了一种少有合同供货能够保证的稳定。', '公司称，这个家族在尼加拉瓜种植古巴种子的烟草。2016年7月，Oliva Cigar Co. 被比利时的 J. Cortès 集团收购；2021年，行业媒体称它是该集团的子公司，家族仍在位于 Miami Lakes（佛罗里达）的公司担任领导。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وميزة الدار البنيوية في الملكية: فكل ورقة تدخل سيجار أوليفا نبتت في أرض العائلة، في خالابا أو إستيلي. ويتفقّد غيلبرتو أوليفا الابن مزارعه بنفسه، على ظهر حصان، في كل موسم. وهذه الصلة المباشرة بين العائلة والتربة تفسّر انتظامًا قلّما يتيحه التزوّد بالعقود.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وميزة الدار البنيوية في الملكية: فكل ورقة تدخل سيجار أوليفا نبتت في أرض العائلة، في خالابا أو إستيلي. ويتفقّد غيلبرتو أوليفا الابن مزارعه بنفسه، على ظهر حصان، في كل موسم. وهذه الصلة المباشرة بين العائلة والتربة تفسّر انتظامًا قلّما يتيحه التزوّد بالعقود.', 'تزرع العائلة في نيكاراغوا تبغًا من بذور كوبية، بحسب الدار. وفي تموز/يوليو 2016 اشترت المجموعة البلجيكية J. Cortès شركة Oliva Cigar Co.؛ وفي عام 2021 تصفها الصحافة المتخصصة بأنها شركتها التابعة، مع بقاء العائلة على رأس الشركة في Miami Lakes (فلوريدا).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva';

UPDATE `brands` SET
  `limited_eds` = '["Oliva Serie V 135th Anniversary Edición Limitada"]',
  `founded` = '1886 Cuba ; marque Oliva depuis 1995',
  `gamme` = '[{"name":"Serie V","color":"#8B0000","force":"Full","story":"Ligne phare de la maison ; année de lancement divergente selon les sources. Cape d''Équateur cultivée au soleil, liant nicaraguayen, tripe longfiller nicaraguayenne dont du ligero de Jalapa, dit la maison ; café, chocolat noir et épice subtile. Le Melanio est une ligne distincte sur la page de la maison.","vitolas":["Robusto","Torpedo","Toro","Churchill","Double Toro","Melanio","Figurado"],"wrapper":"Équateur, sun grown"},{"name":"Serie G","color":"#722F37","force":"Medium","story":"Cape Cameroun sur liant et tripe nicaraguayens ; la maison la dit de corps moyen.","vitolas":["No.4","No.5","No.7","Belicoso","Torpedo"],"wrapper":"Cameroun"},{"name":"Nub","color":"#A0522D","force":"Medium","story":"Concept de cigares courts et larges (une dizaine de centimètres, calibres jusqu''à 60), né dans le laboratoire d''idées Studio Tobac d''Oliva ; selon un site spécialisé, l''idée était de donner à tout le cigare la saveur qu''on trouve d''ordinaire dans le dernier tiers (une autre source attribue l''idée à Sam Leccia). Année de lancement : 2008 selon une seule source.","vitolas":["358","460","464","Habano","Connecticut","Cameroon"],"wrapper":"Variable"},{"name":"Cuba Aliados","color":"#7A2E1E","force":"Medium-Full","story":"Marque de la famille Reyes (Honduras) ; Oliva en a racheté la marque déposée en août 2021, avec Puros Indios et Roly, la famille Reyes gardant son activité et sa fabrique. Oliva dit transférer la production du Honduras au Nicaragua. Voir Reyes Family Cigars.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Puros Indios","color":"#6B4226","force":"Medium","story":"Marque de la famille Reyes, apparue en 1995 selon un profil de la presse du métier ; marque déposée rachetée par Oliva en août 2021.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Roly","color":"#5B3A29","force":"Medium","story":"La troisième marque du rachat d''août 2021.","vitolas":[],"wrapper":"Non divulguée"}]',
  `gamme_en` = '[{"name":"Serie V","color":"#8B0000","force":"Full","story":"The house''s flagship line; the year of launch differs between sources. Ecuadorian sun-grown wrapper, Nicaraguan binder, Nicaraguan longfiller filler including Jalapa ligero, says the house; coffee, dark chocolate and subtle spice. The Melanio is a separate line on the house''s page.","vitolas":["Robusto","Torpedo","Toro","Churchill","Double Toro","Melanio","Figurado"],"wrapper":"Ecuador, sun-grown"},{"name":"Serie G","color":"#722F37","force":"Medium","story":"Cameroon wrapper over Nicaraguan binder and filler; the house calls it medium-bodied.","vitolas":["No.4","No.5","No.7","Belicoso","Torpedo"],"wrapper":"Cameroon"},{"name":"Nub","color":"#A0522D","force":"Medium","story":"A concept of short, wide cigars (about ten centimetres, ring gauges up to 60), born in Oliva''s idea laboratory, Studio Tobac; according to a specialist site, the idea was to give the whole cigar the flavour usually found in the last third (another source credits the idea to Sam Leccia). Year of launch: 2008 according to a single source.","vitolas":["358","460","464","Habano","Connecticut","Cameroon"],"wrapper":"Variable"},{"name":"Cuba Aliados","color":"#7A2E1E","force":"Medium-Full","story":"A Reyes family brand (Honduras); Oliva bought the trademark in August 2021, with Puros Indios and Roly, the Reyes family keeping its business and its factory. Oliva says it is moving production from Honduras to Nicaragua. See Reyes Family Cigars.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Puros Indios","color":"#6B4226","force":"Medium","story":"A Reyes family brand, appearing in 1995 according to a trade-press profile; trademark bought by Oliva in August 2021.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Roly","color":"#5B3A29","force":"Medium","story":"The third brand of the August 2021 purchase.","vitolas":[],"wrapper":"Undisclosed"}]',
  `gamme_es` = '[{"name":"Serie V","color":"#8B0000","force":"Full","story":"Línea insignia de la casa; el año de lanzamiento diverge según las fuentes. Capa de Ecuador cultivada al sol, capote nicaragüense, tripa longfiller nicaragüense con ligero de Jalapa, dice la casa; café, chocolate negro y especia sutil. El Melanio es una línea distinta en la página de la casa.","vitolas":["Robusto","Torpedo","Toro","Churchill","Double Toro","Melanio","Figurado"],"wrapper":"Ecuador, cultivada al sol"},{"name":"Serie G","color":"#722F37","force":"Medium","story":"Capa Camerún sobre capote y tripa nicaragüenses; la casa la dice de cuerpo medio.","vitolas":["No.4","No.5","No.7","Belicoso","Torpedo"],"wrapper":"Camerún"},{"name":"Nub","color":"#A0522D","force":"Medium","story":"Concepto de puros cortos y anchos (unos diez centímetros, cepos de hasta 60), nacido en el laboratorio de ideas Studio Tobac de Oliva; según un sitio especializado, la idea era dar a todo el puro el sabor que se encuentra habitualmente en el último tercio (otra fuente atribuye la idea a Sam Leccia). Año de lanzamiento: 2008 según una sola fuente.","vitolas":["358","460","464","Habano","Connecticut","Cameroon"],"wrapper":"Variable"},{"name":"Cuba Aliados","color":"#7A2E1E","force":"Medium-Full","story":"Marca de la familia Reyes (Honduras); Oliva compró la marca registrada en agosto de 2021, con Puros Indios y Roly, y la familia Reyes conserva su actividad y su fábrica. Oliva dice trasladar la producción de Honduras a Nicaragua. Véase Reyes Family Cigars.","vitolas":[],"wrapper":"No divulgada"},{"name":"Puros Indios","color":"#6B4226","force":"Medium","story":"Marca de la familia Reyes, aparecida en 1995 según un perfil de la prensa del sector; marca registrada comprada por Oliva en agosto de 2021.","vitolas":[],"wrapper":"No divulgada"},{"name":"Roly","color":"#5B3A29","force":"Medium","story":"La tercera marca de la compra de agosto de 2021.","vitolas":[],"wrapper":"No divulgada"}]',
  `gamme_de` = '[{"name":"Serie V","color":"#8B0000","force":"Full","story":"Flaggschiff-Linie des Hauses; das Einführungsjahr weicht je nach Quelle ab. Sonnengereiftes Deckblatt aus Ecuador, nicaraguanisches Umblatt, nicaraguanische Longfiller-Einlage, darunter Ligero aus Jalapa, sagt das Haus; Kaffee, Zartbitterschokolade und feine Würze. Das Melanio ist auf der Seite des Hauses eine eigene Linie.","vitolas":["Robusto","Torpedo","Toro","Churchill","Double Toro","Melanio","Figurado"],"wrapper":"Ecuador, sonnengereift"},{"name":"Serie G","color":"#722F37","force":"Medium","story":"Kamerun-Deckblatt über nicaraguanischem Umblatt und nicaraguanischer Einlage; das Haus nennt sie mittelkräftig.","vitolas":["No.4","No.5","No.7","Belicoso","Torpedo"],"wrapper":"Kamerun"},{"name":"Nub","color":"#A0522D","force":"Medium","story":"Konzept kurzer, dicker Zigarren (rund zehn Zentimeter, Ringmaße bis 60), entstanden im Ideenlabor Studio Tobac von Oliva; laut einer Fachseite sollte die ganze Zigarre den Geschmack bekommen, den man gewöhnlich im letzten Drittel findet (eine andere Quelle schreibt die Idee Sam Leccia zu). Einführungsjahr: 2008 laut nur einer Quelle.","vitolas":["358","460","464","Habano","Connecticut","Cameroon"],"wrapper":"Variable"},{"name":"Cuba Aliados","color":"#7A2E1E","force":"Medium-Full","story":"Marke der Familie Reyes (Honduras); Oliva kaufte die eingetragene Marke im August 2021, zusammen mit Puros Indios und Roly; die Familie Reyes behält ihr Geschäft und ihre Fabrik. Oliva gibt an, die Produktion von Honduras nach Nicaragua zu verlegen. Siehe Reyes Family Cigars.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Puros Indios","color":"#6B4226","force":"Medium","story":"Marke der Familie Reyes, laut einem Porträt der Fachpresse 1995 aufgetaucht; die eingetragene Marke wurde im August 2021 von Oliva gekauft.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Roly","color":"#5B3A29","force":"Medium","story":"Die dritte Marke des Kaufs vom August 2021.","vitolas":[],"wrapper":"Nicht angegeben"}]',
  `gamme_zh` = '[{"name":"Serie V","color":"#8B0000","force":"Full","story":"公司的主打系列；各来源给出的推出年份不一。厄瓜多尔日晒茄衣，尼加拉瓜茄套，芯叶为尼加拉瓜 longfiller，其中含哈拉帕的 ligero，据公司称；咖啡、黑巧克力与细腻的香料。Melanio 在公司页面上是另一个独立的系列。","vitolas":["Robusto","Torpedo","Toro","Churchill","Double Toro","Melanio","Figurado"],"wrapper":"厄瓜多尔，日晒"},{"name":"Serie G","color":"#722F37","force":"Medium","story":"喀麦隆茄衣，茄套与芯叶均为尼加拉瓜产；公司称其为中等醇厚。","vitolas":["No.4","No.5","No.7","Belicoso","Torpedo"],"wrapper":"喀麦隆"},{"name":"Nub","color":"#A0522D","force":"Medium","story":"短而粗的雪茄构想（约十厘米，环径可达60），诞生于奥利瓦的创意实验室 Studio Tobac；据一家专业网站，其想法是让整支雪茄都带有通常在末段三分之一才有的风味（另一来源把这一想法归于 Sam Leccia）。推出年份：仅一个来源给出2008年。","vitolas":["358","460","464","Habano","Connecticut","Cameroon"],"wrapper":"Variable"},{"name":"Cuba Aliados","color":"#7A2E1E","force":"Medium-Full","story":"雷耶斯家族（洪都拉斯）的牌子；2021年8月，奥利瓦连同 Puros Indios 与 Roly 一起收购了这一注册商标，雷耶斯家族保留其业务与工厂。奥利瓦称正在把生产从洪都拉斯转到尼加拉瓜。参见 Reyes Family Cigars。","vitolas":[],"wrapper":"未公开"},{"name":"Puros Indios","color":"#6B4226","force":"Medium","story":"雷耶斯家族的牌子，据行业媒体的一篇专题报道，出现于1995年；注册商标于2021年8月被奥利瓦收购。","vitolas":[],"wrapper":"未公开"},{"name":"Roly","color":"#5B3A29","force":"Medium","story":"2021年8月收购的第三个牌子。","vitolas":[],"wrapper":"未公开"}]',
  `gamme_ar` = '[{"name":"Serie V","color":"#8B0000","force":"Full","story":"الخط الرئيسي للدار؛ وتختلف سنة إطلاقه بحسب المصادر. غلاف من الإكوادور مزروع تحت الشمس، وغلاف داخلي نيكاراغوي، وحشوة longfiller نيكاراغوية تتضمن ligero من خالابا، بحسب الدار؛ قهوة وشوكولاتة داكنة وتوابل رقيقة. وMelanio خط مستقل في صفحة الدار.","vitolas":["Robusto","Torpedo","Toro","Churchill","Double Toro","Melanio","Figurado"],"wrapper":"الإكوادور، مزروع تحت الشمس"},{"name":"Serie G","color":"#722F37","force":"Medium","story":"غلاف كاميروني فوق غلاف داخلي وحشوة نيكاراغويين؛ وتصفها الدار بأنها متوسطة الجسم.","vitolas":["No.4","No.5","No.7","Belicoso","Torpedo"],"wrapper":"كاميروني"},{"name":"Nub","color":"#A0522D","force":"Medium","story":"فكرة سيجار قصير وعريض (نحو عشرة سنتيمترات، بقياسات حلقية تصل إلى 60)، وُلدت في مختبر الأفكار Studio Tobac التابع لأوليفا؛ وبحسب موقع متخصص، كانت الفكرة أن يُعطى السيجار كله النكهة التي تُوجد عادةً في الثلث الأخير (ويُنسب مصدر آخر الفكرة إلى Sam Leccia). سنة الإطلاق: 2008 بحسب مصدر واحد فقط.","vitolas":["358","460","464","Habano","Connecticut","Cameroon"],"wrapper":"Variable"},{"name":"Cuba Aliados","color":"#7A2E1E","force":"Medium-Full","story":"علامة لعائلة رييس (هندوراس)؛ اشترت أوليفا العلامة المسجّلة في آب/أغسطس 2021 مع Puros Indios وRoly، وتحتفظ عائلة رييس بنشاطها ومصنعها. وتقول أوليفا إنها تنقل الإنتاج من هندوراس إلى نيكاراغوا. انظر Reyes Family Cigars.","vitolas":[],"wrapper":"غير معلن"},{"name":"Puros Indios","color":"#6B4226","force":"Medium","story":"علامة لعائلة رييس، ظهرت عام 1995 بحسب تعريف في الصحافة المتخصصة؛ واشترت أوليفا العلامة المسجّلة في آب/أغسطس 2021.","vitolas":[],"wrapper":"غير معلن"},{"name":"Roly","color":"#5B3A29","force":"Medium","story":"العلامة الثالثة في صفقة آب/أغسطس 2021.","vitolas":[],"wrapper":"غير معلن"}]',
  `celebrities` = '[{"name":"Gilberto Oliva Jr.","anecdote":"Fils de Gilberto Oliva père et arrière-petit-fils de Melanio, il a fait avec son père le premier cigare de la marque en 1995. Wikipédia le dit chargé de la culture de la feuille au Nicaragua et de la création des mélanges."}]',
  `celebrities_en` = '[{"name":"Gilberto Oliva Jr.","anecdote":"Son of Gilberto Oliva senior and great-grandson of Melanio, he made the brand''s first cigar with his father in 1995. Wikipedia says he is in charge of growing the leaf in Nicaragua and of creating the blends."}]',
  `celebrities_es` = '[{"name":"Gilberto Oliva Jr.","anecdote":"Hijo de Gilberto Oliva padre y bisnieto de Melanio, hizo con su padre el primer puro de la marca en 1995. Wikipedia lo dice encargado del cultivo de la hoja en Nicaragua y de la creación de las mezclas."}]',
  `celebrities_de` = '[{"name":"Gilberto Oliva Jr.","anecdote":"Sohn von Gilberto Oliva dem Älteren und Urenkel von Melanio; er stellte 1995 mit seinem Vater die erste Zigarre der Marke her. Laut Wikipedia ist er für den Anbau des Blattes in Nicaragua und für die Entwicklung der Mischungen zuständig."}]',
  `celebrities_zh` = '[{"name":"Gilberto Oliva Jr.","anecdote":"老 Gilberto Oliva 之子，Melanio 的曾孙；1995年与父亲一起做出了这个品牌的首支雪茄。维基百科称他负责尼加拉瓜的烟叶种植和配方的创制。"}]',
  `celebrities_ar` = '[{"name":"Gilberto Oliva Jr.","anecdote":"ابن Gilberto Oliva الأب، وابن حفيد Melanio؛ صنع مع أبيه أول سيجار للعلامة عام 1995. وتقول ويكيبيديا إنه مكلّف بزراعة الورقة في نيكاراغوا وبابتكار الخلطات."}]',
  `source` = IF(LOCATE(CAST('cape Habano d''Équateur, liant et tripe nicaraguayens, roulé à la main en longfiller, Gordo 4 x 60, en stock)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'cape Habano d''Équateur, liant et tripe nicaraguayens, roulé à la main en longfiller, Gordo 4 x 60, en stock)', 'cape Habano d''Équateur, liant et tripe nicaraguayens, roulé à la main en longfiller, Gordo 4 x 60)'), `source`),
  `source` = IF(LOCATE(CAST('aucune fabrique nommée, en stock)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'aucune fabrique nommée, en stock)', 'aucune fabrique nommée)'), `source`),
  `source` = IF(LOCATE(CAST('Habano Toro, Robusto et Gordo en vente)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'Habano Toro, Robusto et Gordo en vente)', 'Habano Toro, Robusto et Gordo proposés)'), `source`),
  `source` = IF(LOCATE(CAST('olivacigar.com « History » (octobre 2026 : Melanio Oliva cul' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'olivacigar.com « History » (octobre 2026 : Melanio Oliva cultive à Pinar del Río en 1886, Facundo au début des années 1920, Gilberto courtier puis Nicaragua) ; olivacigar.com « Heritage » (octobre 2026 : départ de Cuba au début des années 1960, Honduras, Panama, Mexique, Philippines, Nicaragua) ; olivacigar.com « Serie V » et « Serie G » (octobre 2026 : cape, liant, tripe, vitolas) ; en.wikipedia.org « Oliva Cigar Co. » (octobre 2026 : Hipolito, 1964 Espagne, 1969 Nicaragua, 1995-1996 Gilberto Oliva puis Oliva, Serie V en 2006, rachat J. Cortès 2016) ; cigaraficionado.com « Oliva Cigar Patriarch Gilberto Oliva Sr., 86, Dies » (17 décembre 2017 : 1995 fabrique Plasencia au Honduras, fabrique au Nicaragua un an plus tard, rachat 2016) ; cigar-coop.com « Cigar News: Oliva Cigar Company Acquires Cuba Aliados, Puros Indios and Roly Brands » (6 août 2021 : marques déposées achetées à la famille Reyes, qui garde sa fabrique ; Oliva filiale de J. Cortès depuis 2016) ; cigarinspector.com (recherche, octobre 2026 : Nub, dernier tiers, Studio Tobac)')),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva';

-- ── Perdomo ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le lien de Nick Perdomo avec le tabac nicaraguayen est généalogique avant d''être commercial. Sa famille cultivait le tabac dans la province cubaine de Pinar del Río depuis des générations avant que la révolution ne referme ce chapitre. Les semences et le savoir emportés en exil n''étaient pas des métaphores : les Perdomo, comme les Oliva et les Plasencia, ont conservé du matériel génétique de plants cubains, qu''ils ont fini par mettre en terre au Nicaragua.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le lien de Nick Perdomo avec le tabac nicaraguayen est généalogique avant d''être commercial. Sa famille cultivait le tabac dans la province cubaine de Pinar del Río depuis des générations avant que la révolution ne referme ce chapitre. Les semences et le savoir emportés en exil n''étaient pas des métaphores : les Perdomo, comme les Oliva et les Plasencia, ont conservé du matériel génétique de plants cubains, qu''ils ont fini par mettre en terre au Nicaragua.', 'Nick Perdomo Jr. lance Nick''s Cigar Co. à Miami en août 1992 (dans son garage, selon Wikipédia), sans quitter son poste de contrôleur aérien à l''aéroport de Miami. La famille a des racines cubaines : Wikipédia la rattache à San José de las Lajas, d''où venait son grand-père Silvio, et son père Nick Sr. a travaillé chez Partagás puis chez H. Upmann avant de quitter Cuba après la révolution. Les sources divergent sur les débuts nicaraguayens : la presse du métier de 2001 place une première fabrique à Estelí en 1995 et une plus grande en 1999, Wikipédia une installation en 1997 remplacée en 1999.'), `history`),
  `history_en` = IF(LOCATE(CAST('Nick Perdomo''s relationship with Nicaraguan tobacco is genealogical before it is commercial. His family cultivated tobacco in Cuba''s Pinar del Río province for generations before the revolution that ended that chapter. The seeds and knowledge they carried into exile were not metaphorical — the Perdomo family, like the Olivás and the Plasencias, preserved actual genetic material from Cuban tobacco plants that they eventually planted in Nicaraguan soil.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Nick Perdomo''s relationship with Nicaraguan tobacco is genealogical before it is commercial. His family cultivated tobacco in Cuba''s Pinar del Río province for generations before the revolution that ended that chapter. The seeds and knowledge they carried into exile were not metaphorical — the Perdomo family, like the Olivás and the Plasencias, preserved actual genetic material from Cuban tobacco plants that they eventually planted in Nicaraguan soil.', 'Nick Perdomo Jr. launched Nick''s Cigar Co. in Miami in August 1992 (in his garage, according to Wikipedia), without leaving his job as an air traffic controller at Miami airport. The family has Cuban roots: Wikipedia ties it to San José de las Lajas, where his grandfather Silvio came from, and his father Nick Sr. worked at Partagás and then at H. Upmann before leaving Cuba after the revolution. Sources diverge on the Nicaraguan beginnings: the trade press in 2001 places a first factory in Estelí in 1995 and a larger one in 1999, Wikipedia an installation in 1997 replaced in 1999.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El vínculo de Nick Perdomo con el tabaco nicaragüense es genealógico antes que comercial. Su familia cultivaba tabaco en la provincia cubana de Pinar del Río desde hacía generaciones antes de que la revolución cerrara ese capítulo. Las semillas y el saber llevados al exilio no eran metáforas: los Perdomo, como los Oliva y los Plasencia, conservaron material genético de plantas cubanas, que acabaron sembrando en Nicaragua.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El vínculo de Nick Perdomo con el tabaco nicaragüense es genealógico antes que comercial. Su familia cultivaba tabaco en la provincia cubana de Pinar del Río desde hacía generaciones antes de que la revolución cerrara ese capítulo. Las semillas y el saber llevados al exilio no eran metáforas: los Perdomo, como los Oliva y los Plasencia, conservaron material genético de plantas cubanas, que acabaron sembrando en Nicaragua.', 'Nick Perdomo Jr. lanza Nick''s Cigar Co. en Miami en agosto de 1992 (en su garaje, según Wikipedia), sin dejar su puesto de controlador aéreo en el aeropuerto de Miami. La familia tiene raíces cubanas: Wikipedia la vincula con San José de las Lajas, de donde venía su abuelo Silvio, y su padre Nick Sr. trabajó en Partagás y luego en H. Upmann antes de dejar Cuba tras la revolución. Las fuentes divergen sobre los inicios nicaragüenses: la prensa del sector de 2001 sitúa una primera fábrica en Estelí en 1995 y otra mayor en 1999; Wikipedia, una instalación en 1997 sustituida en 1999.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Bindung von Nick Perdomo an den nicaraguanischen Tabak ist genealogisch, bevor sie kaufmännisch ist. Seine Familie baute in der kubanischen Provinz Pinar del Río seit Generationen Tabak an, ehe die Revolution dieses Kapitel schloss. Saatgut und Wissen, ins Exil mitgenommen, waren keine Bilder: Die Perdomos haben, wie die Olivas und die Plasencias, Erbmaterial kubanischer Pflanzen bewahrt und schließlich in Nicaragua in die Erde gebracht.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Bindung von Nick Perdomo an den nicaraguanischen Tabak ist genealogisch, bevor sie kaufmännisch ist. Seine Familie baute in der kubanischen Provinz Pinar del Río seit Generationen Tabak an, ehe die Revolution dieses Kapitel schloss. Saatgut und Wissen, ins Exil mitgenommen, waren keine Bilder: Die Perdomos haben, wie die Olivas und die Plasencias, Erbmaterial kubanischer Pflanzen bewahrt und schließlich in Nicaragua in die Erde gebracht.', 'Nick Perdomo Jr. gründet Nick''s Cigar Co. im August 1992 in Miami (laut Wikipedia in seiner Garage), ohne seine Stelle als Fluglotse am Flughafen Miami aufzugeben. Die Familie hat kubanische Wurzeln: Wikipedia verbindet sie mit San José de las Lajas, woher sein Großvater Silvio stammte, und sein Vater Nick Sr. arbeitete bei Partagás und danach bei H. Upmann, bevor er Kuba nach der Revolution verließ. Über die nicaraguanischen Anfänge gehen die Quellen auseinander: Die Fachpresse von 2001 nennt eine erste Fabrik in Estelí 1995 und eine größere 1999, Wikipedia eine Niederlassung 1997, die 1999 ersetzt wurde.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('尼克·佩尔多莫与尼加拉瓜烟草的关系，先是血脉的，然后才是生意的。革命合上那一章之前，他家在古巴的比那尔德里奥省已经种了几代烟草。带去流亡的种子与本事并不是比喻：佩尔多莫家和奥利瓦家、普拉森西亚家一样，保住了古巴烟株的遗传材料，最终把它们种进了尼加拉瓜的土里。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '尼克·佩尔多莫与尼加拉瓜烟草的关系，先是血脉的，然后才是生意的。革命合上那一章之前，他家在古巴的比那尔德里奥省已经种了几代烟草。带去流亡的种子与本事并不是比喻：佩尔多莫家和奥利瓦家、普拉森西亚家一样，保住了古巴烟株的遗传材料，最终把它们种进了尼加拉瓜的土里。', '尼克·佩尔多莫（Nick Perdomo Jr.）于1992年8月在迈阿密创办 Nick''s Cigar Co.（据维基百科，地点是他的车库），当时他并未辞去迈阿密机场空中交通管制员的职务。这个家族有古巴渊源：维基百科把它与圣何塞-德拉斯拉赫斯（San José de las Lajas）联系起来，他的祖父西尔维奥（Silvio）即来自那里；其父老尼克（Nick Sr.）先后在 Partagás 与 H. Upmann 工作，革命后离开古巴。关于尼加拉瓜的起步，各方说法不一：2001年的行业媒体称1995年在埃斯特利有首家工厂，1999年有一家更大的；维基百科则称1997年设厂，1999年被取代。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('صلة نيك بيردومو بالتبغ النيكاراغوي نَسَبية قبل أن تكون تجارية. فقد كانت عائلته تزرع التبغ في مقاطعة بينار ديل ريو الكوبية منذ أجيال، قبل أن تغلق الثورة ذلك الفصل. ولم تكن البذور والمعرفة المحمولتان إلى المنفى استعارة: فآل بيردومو، مثل آل أوليفا وآل بلاسينسيا، حفظوا مادة وراثية من شتلات كوبية، وانتهوا إلى غرسها في نيكاراغوا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'صلة نيك بيردومو بالتبغ النيكاراغوي نَسَبية قبل أن تكون تجارية. فقد كانت عائلته تزرع التبغ في مقاطعة بينار ديل ريو الكوبية منذ أجيال، قبل أن تغلق الثورة ذلك الفصل. ولم تكن البذور والمعرفة المحمولتان إلى المنفى استعارة: فآل بيردومو، مثل آل أوليفا وآل بلاسينسيا، حفظوا مادة وراثية من شتلات كوبية، وانتهوا إلى غرسها في نيكاراغوا.', 'أطلق نيك بيردومو الابن شركة Nick''s Cigar Co. في ميامي في أغسطس 1992 (في مرآبه، بحسب ويكيبيديا)، دون أن يترك عمله مراقبًا جويًّا في مطار ميامي. وللعائلة جذور كوبية: تربطها ويكيبيديا بسان خوسيه دي لاس لاخاس، التي جاء منها جدّه سيلفيو، وقد عمل أبوه نيك الأب في Partagás ثم في H. Upmann قبل أن يغادر كوبا بعد الثورة. وتتباين المصادر في بدايات نيكاراغوا: فالصحافة المتخصصة عام 2001 تضع مصنعًا أول في إستيلي عام 1995 ومصنعًا أوسع منه عام 1999، وتذكر ويكيبيديا منشأة عام 1997 حلّت محلها أخرى عام 1999.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Perdomo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Cette continuité compte, parce que l''argument central de la maison — le tabac nicaraguayen de la vallée de Jalapa peut rivaliser de complexité et de profondeur avec le cubain — n''est pas une formule publicitaire mais la conclusion de quelqu''un qui a grandi avec les deux. Le père de Nick Perdomo savait le goût du tabac de la Vuelta Abajo parce qu''il l''avait cultivé. Nick le savait parce que son père le lui avait montré. La comparaison qu''il fait en décrivant sa feuille nicaraguayenne s''appuie sur une mémoire sensorielle transmise.

' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Cette continuité compte, parce que l''argument central de la maison — le tabac nicaraguayen de la vallée de Jalapa peut rivaliser de complexité et de profondeur avec le cubain — n''est pas une formule publicitaire mais la conclusion de quelqu''un qui a grandi avec les deux. Le père de Nick Perdomo savait le goût du tabac de la Vuelta Abajo parce qu''il l''avait cultivé. Nick le savait parce que son père le lui avait montré. La comparaison qu''il fait en décrivant sa feuille nicaraguayenne s''appuie sur une mémoire sensorielle transmise.

', ''), `history`),
  `history_en` = IF(LOCATE(CAST(CONCAT('That continuity matters because Perdomo''s central argument — that Nicaraguan tobacco from the Jalapa Valley can rival Cuban tobacco in complexity and depth — is not a marketing claim but the conclusion of someone who grew up with both. Nick Perdomo''s father knew what Vuelta Abajo tobacco tasted like because he had grown it. Nick Perdomo knew what it tasted like because his father had shown him. The comparison he makes when describing his Nicaraguan leaf is informed by direct sensory memory transmitted across generations.', CHAR(13), '
', CHAR(13), '
') AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, CONCAT('That continuity matters because Perdomo''s central argument — that Nicaraguan tobacco from the Jalapa Valley can rival Cuban tobacco in complexity and depth — is not a marketing claim but the conclusion of someone who grew up with both. Nick Perdomo''s father knew what Vuelta Abajo tobacco tasted like because he had grown it. Nick Perdomo knew what it tasted like because his father had shown him. The comparison he makes when describing his Nicaraguan leaf is informed by direct sensory memory transmitted across generations.', CHAR(13), '
', CHAR(13), '
'), ''), `history_en`),
  `history_es` = IF(LOCATE(CAST('Esa continuidad cuenta, porque el argumento central de la casa —el tabaco nicaragüense del valle de Jalapa puede rivalizar en complejidad y en profundidad con el cubano— no es una fórmula publicitaria sino la conclusión de alguien que creció con los dos. El padre de Nick Perdomo sabía el sabor del tabaco de la Vuelta Abajo porque lo había cultivado. Nick lo sabía porque su padre se lo había mostrado. La comparación que hace al describir su hoja nicaragüense se apoya en una memoria sensorial transmitida.

' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Esa continuidad cuenta, porque el argumento central de la casa —el tabaco nicaragüense del valle de Jalapa puede rivalizar en complejidad y en profundidad con el cubano— no es una fórmula publicitaria sino la conclusión de alguien que creció con los dos. El padre de Nick Perdomo sabía el sabor del tabaco de la Vuelta Abajo porque lo había cultivado. Nick lo sabía porque su padre se lo había mostrado. La comparación que hace al describir su hoja nicaragüense se apoya en una memoria sensorial transmitida.

', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST('Diese Fortdauer zählt, denn das Kernargument des Hauses — der nicaraguanische Tabak aus dem Tal von Jalapa kann es an Vielschichtigkeit und Tiefe mit dem kubanischen aufnehmen — ist keine Werbeformel, sondern der Schluss eines Menschen, der mit beiden aufgewachsen ist. Nick Perdomos Vater kannte den Geschmack des Tabaks aus der Vuelta Abajo, weil er ihn angebaut hatte. Nick kannte ihn, weil sein Vater ihn ihm gezeigt hatte. Der Vergleich, den er beim Beschreiben seines nicaraguanischen Blattes zieht, stützt sich auf ein weitergegebenes sinnliches Gedächtnis.

' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Diese Fortdauer zählt, denn das Kernargument des Hauses — der nicaraguanische Tabak aus dem Tal von Jalapa kann es an Vielschichtigkeit und Tiefe mit dem kubanischen aufnehmen — ist keine Werbeformel, sondern der Schluss eines Menschen, der mit beiden aufgewachsen ist. Nick Perdomos Vater kannte den Geschmack des Tabaks aus der Vuelta Abajo, weil er ihn angebaut hatte. Nick kannte ihn, weil sein Vater ihn ihm gezeigt hatte. Der Vergleich, den er beim Beschreiben seines nicaraguanischen Blattes zieht, stützt sich auf ein weitergegebenes sinnliches Gedächtnis.

', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这份延续很要紧，因为这家字号的核心主张——哈拉帕山谷的尼加拉瓜烟草能在复杂度与深度上与古巴烟草分庭抗礼——不是一句广告词，而是一个从小同时接触过两者的人得出的结论。尼克的父亲知道阿巴霍谷烟草的味道，因为他种过；尼克知道，因为父亲让他见识过。他描述自家尼加拉瓜叶子时所作的比较，靠的是一份传下来的感官记忆。

' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这份延续很要紧，因为这家字号的核心主张——哈拉帕山谷的尼加拉瓜烟草能在复杂度与深度上与古巴烟草分庭抗礼——不是一句广告词，而是一个从小同时接触过两者的人得出的结论。尼克的父亲知道阿巴霍谷烟草的味道，因为他种过；尼克知道，因为父亲让他见识过。他描述自家尼加拉瓜叶子时所作的比较，靠的是一份传下来的感官记忆。

', ''), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('لهذه الاستمرارية وزنها، لأن حجّة الدار المركزية — أنّ التبغ النيكاراغوي من وادي خالابا قادر على منافسة الكوبي في التركيب والعمق — ليست صيغة إعلانية بل خلاصةَ من نشأ على الاثنين معًا. كان والد نيك بيردومو يعرف طعم تبغ فويلتا أباخو لأنه زرعه. وعرفه نيك لأن أباه أراه إياه. والمقارنة التي يعقدها وهو يصف ورقته النيكاراغوية تستند إلى ذاكرة حسّية متوارثة.

' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'لهذه الاستمرارية وزنها، لأن حجّة الدار المركزية — أنّ التبغ النيكاراغوي من وادي خالابا قادر على منافسة الكوبي في التركيب والعمق — ليست صيغة إعلانية بل خلاصةَ من نشأ على الاثنين معًا. كان والد نيك بيردومو يعرف طعم تبغ فويلتا أباخو لأنه زرعه. وعرفه نيك لأن أباه أراه إياه. والمقارنة التي يعقدها وهو يصف ورقته النيكاراغوية تستند إلى ذاكرة حسّية متوارثة.

', ''), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Perdomo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''exploitation d''Estelí contrôle son approvisionnement plus complètement que la plupart des fabricants du marché américain. Là où les concurrents passent par des courtiers ou des contrats de fourniture, Perdomo cultive une part importante de ses tabacs sur des terres familiales, selon des pratiques affinées depuis un siècle. Les capes des gammes premium — y compris les cas rares où il emploie une cape nicaraguayenne plutôt que le Connecticut Shade d''Équateur que préfèrent la plupart des maisons — représentent des années de sélection variétale et d''essais de fermentation.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''exploitation d''Estelí contrôle son approvisionnement plus complètement que la plupart des fabricants du marché américain. Là où les concurrents passent par des courtiers ou des contrats de fourniture, Perdomo cultive une part importante de ses tabacs sur des terres familiales, selon des pratiques affinées depuis un siècle. Les capes des gammes premium — y compris les cas rares où il emploie une cape nicaraguayenne plutôt que le Connecticut Shade d''Équateur que préfèrent la plupart des maisons — représentent des années de sélection variétale et d''essais de fermentation.', 'En octobre 2026, la maison se dit entreprise familiale et verticalement intégrée, de la culture du tabac à la distribution : siège à Miami, fabrication à Estelí, terres à Estelí, Condega et Jalapa. Ce n''était pas le cas en 2001, quand la presse du métier écrivait que Perdomo ne possédait pas de champs et achetait son tabac à des fournisseurs, dont la famille Perez d''ASP Enterprises à Estelí.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Perdomo operation in Estelí controls its tobacco sourcing more completely than most manufacturers in the American market. Where competitors source leaf through brokers or long-term supply contracts, Perdomo grows significant portions of his tobaccos on family-owned land, using cultivation practices developed over a century of practice. The wrapper tobacco that appears across the premium Perdomo ranges — including the rare cases where he uses Nicaraguan wrapper rather than the Ecuadorian Connecticut shade that most makers prefer — represents years of varietal development and fermentation experimentation.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Perdomo operation in Estelí controls its tobacco sourcing more completely than most manufacturers in the American market. Where competitors source leaf through brokers or long-term supply contracts, Perdomo grows significant portions of his tobaccos on family-owned land, using cultivation practices developed over a century of practice. The wrapper tobacco that appears across the premium Perdomo ranges — including the rare cases where he uses Nicaraguan wrapper rather than the Ecuadorian Connecticut shade that most makers prefer — represents years of varietal development and fermentation experimentation.', 'In October 2026 the house describes itself as a family-owned, vertically integrated company, from tobacco growing to distribution: headquarters in Miami, manufacturing in Estelí, land in Estelí, Condega and Jalapa. That was not the case in 2001, when the trade press wrote that Perdomo owned no fields and bought its tobacco from suppliers, among them the Perez family of ASP Enterprises in Estelí.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La explotación de Estelí controla su abastecimiento más completamente que la mayoría de los fabricantes del mercado estadounidense. Allí donde los competidores pasan por corredores o por contratos de suministro, Perdomo cultiva una parte importante de sus tabacos en tierras familiares, según prácticas afinadas desde hace un siglo. Las capas de las gamas premium —incluidos los casos raros en que emplea una capa nicaragüense antes que el Connecticut Shade de Ecuador que prefieren la mayoría de las casas— representan años de selección varietal y de ensayos de fermentación.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La explotación de Estelí controla su abastecimiento más completamente que la mayoría de los fabricantes del mercado estadounidense. Allí donde los competidores pasan por corredores o por contratos de suministro, Perdomo cultiva una parte importante de sus tabacos en tierras familiares, según prácticas afinadas desde hace un siglo. Las capas de las gamas premium —incluidos los casos raros en que emplea una capa nicaragüense antes que el Connecticut Shade de Ecuador que prefieren la mayoría de las casas— representan años de selección varietal y de ensayos de fermentación.', 'En octubre de 2026, la casa se presenta como empresa familiar y verticalmente integrada, del cultivo del tabaco a la distribución: sede en Miami, fabricación en Estelí, tierras en Estelí, Condega y Jalapa. No era así en 2001, cuando la prensa del sector escribía que Perdomo no poseía campos y compraba su tabaco a proveedores, entre ellos la familia Perez de ASP Enterprises, en Estelí.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der Betrieb in Estelí beherrscht seine Beschaffung vollständiger als die meisten Hersteller des amerikanischen Marktes. Wo Mitbewerber über Makler oder Lieferverträge gehen, baut Perdomo einen erheblichen Teil seiner Tabake auf Familienland an, nach Verfahren, die seit einem Jahrhundert verfeinert werden. Die Deckblätter der Premiumlinien — auch in den seltenen Fällen, in denen ein nicaraguanisches Deckblatt statt des ecuadorianischen Connecticut Shade verwendet wird, das die meisten Häuser vorziehen — stehen für Jahre der Sortenauswahl und der Fermentationsversuche.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der Betrieb in Estelí beherrscht seine Beschaffung vollständiger als die meisten Hersteller des amerikanischen Marktes. Wo Mitbewerber über Makler oder Lieferverträge gehen, baut Perdomo einen erheblichen Teil seiner Tabake auf Familienland an, nach Verfahren, die seit einem Jahrhundert verfeinert werden. Die Deckblätter der Premiumlinien — auch in den seltenen Fällen, in denen ein nicaraguanisches Deckblatt statt des ecuadorianischen Connecticut Shade verwendet wird, das die meisten Häuser vorziehen — stehen für Jahre der Sortenauswahl und der Fermentationsversuche.', 'Im Oktober 2026 bezeichnet sich das Haus als Familienunternehmen und vertikal integriert, vom Tabakanbau bis zum Vertrieb: Sitz in Miami, Fertigung in Estelí, Ländereien in Estelí, Condega und Jalapa. Das war 2001 nicht so, als die Fachpresse schrieb, Perdomo besitze keine Felder und kaufe seinen Tabak bei Lieferanten, darunter die Familie Perez von ASP Enterprises in Estelí.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('埃斯特利的产业对自身供应的掌控，比美国市场上多数厂商都更彻底。同行走的是中间商或供货合同，佩尔多莫则把相当一部分烟草种在家族土地上，用的是打磨了一个世纪的做法。高端产品线的茄衣——包括少数不用多数字号偏爱的厄瓜多尔康涅狄格阴植叶、而用尼加拉瓜茄衣的例子——代表着多年的品种筛选与发酵试验。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '埃斯特利的产业对自身供应的掌控，比美国市场上多数厂商都更彻底。同行走的是中间商或供货合同，佩尔多莫则把相当一部分烟草种在家族土地上，用的是打磨了一个世纪的做法。高端产品线的茄衣——包括少数不用多数字号偏爱的厄瓜多尔康涅狄格阴植叶、而用尼加拉瓜茄衣的例子——代表着多年的品种筛选与发酵试验。', '2026年10月，该厂自称是家族企业，且纵向一体化，从种烟到分销一应俱全：总部在迈阿密，制造在埃斯特利，土地在埃斯特利、孔德加与哈拉帕。2001年并非如此：当时行业媒体写道，佩尔多莫没有自己的田地，烟草购自供应商，其中包括埃斯特利 ASP Enterprises 的佩雷斯（Perez）家族。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تسيطر منشأة إستيلي على تزوّدها بصورة أتمّ من معظم صنّاع السوق الأمريكية. فحيث يمرّ المنافسون عبر وسطاء أو عقود توريد، تزرع بيردومو جزءًا كبيرًا من تبغها في أرض العائلة، وفق ممارسات صُقلت على مدى قرن. أما أغلفة التشكيلات الفاخرة — بما فيها الحالات النادرة التي تستعمل فيها غلافًا نيكاراغويًّا بدل كونيتيكت شيد الإكوادوري الذي تفضّله أغلب الدور — فتمثّل سنوات من انتقاء الأصناف وتجارب التخمير.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تسيطر منشأة إستيلي على تزوّدها بصورة أتمّ من معظم صنّاع السوق الأمريكية. فحيث يمرّ المنافسون عبر وسطاء أو عقود توريد، تزرع بيردومو جزءًا كبيرًا من تبغها في أرض العائلة، وفق ممارسات صُقلت على مدى قرن. أما أغلفة التشكيلات الفاخرة — بما فيها الحالات النادرة التي تستعمل فيها غلافًا نيكاراغويًّا بدل كونيتيكت شيد الإكوادوري الذي تفضّله أغلب الدور — فتمثّل سنوات من انتقاء الأصناف وتجارب التخمير.', 'في أكتوبر 2026 تعرّف الدار نفسها بأنها شركة عائلية متكاملة رأسيًّا، من زراعة التبغ إلى التوزيع: المقر في ميامي، والتصنيع في إستيلي، والأراضي في إستيلي وكونديغا وخالابا. ولم يكن الأمر كذلك عام 2001، حين كتبت الصحافة المتخصصة أن بيردومو لا يملك حقولًا ويشتري تبغه من موردين، منهم عائلة بيريز من ASP Enterprises في إستيلي.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Perdomo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La série 20th Anniversary, sortie en 2012 pour les vingt ans de la maison, en montre clairement l''ambition. La cape oscuro nicaraguayenne — fermentée longuement pour développer le caractère sombre et huileux que le San Andrés Maduro donne plus naturellement — produit sur la tripe de Jalapa un profil de chocolat noir et d''expresso qui défie directement la Serie V d''Oliva sur son propre terrain. Le robusto est la vitole qui a placé Perdomo parmi les maisons dont on discute les hautes expressions à côté de celles de Padrón et d''Oliva.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La série 20th Anniversary, sortie en 2012 pour les vingt ans de la maison, en montre clairement l''ambition. La cape oscuro nicaraguayenne — fermentée longuement pour développer le caractère sombre et huileux que le San Andrés Maduro donne plus naturellement — produit sur la tripe de Jalapa un profil de chocolat noir et d''expresso qui défie directement la Serie V d''Oliva sur son propre terrain. Le robusto est la vitole qui a placé Perdomo parmi les maisons dont on discute les hautes expressions à côté de celles de Padrón et d''Oliva.', 'La 20th Anniversary est présentée à l''IPCPR 2012, pour les vingt ans de la maison : un puro nicaraguayen de graine cubaine, en capes Sun Grown ou Maduro, avec des tabacs des fermes d''Estelí, de Condega et de Jalapa. La maison la propose aujourd''hui aussi avec une cape Connecticut équatorienne ; ses tabacs sont vieillis au moins huit ans et les capes passent ensuite en fût de bourbon.'), `history`),
  `history_en` = IF(LOCATE(CAST('The 2012 20th Anniversary series, released for the company''s first two decades, demonstrated the range''s ambitions clearly. The Nicaraguan Oscuro wrapper — fermented for an extended period to develop the dark, oily character that San Andrés Maduro provides more naturally — produces a profile of dark chocolate and espresso over the Jalapa filler blend. The Robusto is the vitola that placed Perdomo among the houses whose top expressions are discussed alongside Padrón and Oliva.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The 2012 20th Anniversary series, released for the company''s first two decades, demonstrated the range''s ambitions clearly. The Nicaraguan Oscuro wrapper — fermented for an extended period to develop the dark, oily character that San Andrés Maduro provides more naturally — produces a profile of dark chocolate and espresso over the Jalapa filler blend. The Robusto is the vitola that placed Perdomo among the houses whose top expressions are discussed alongside Padrón and Oliva.', 'The 20th Anniversary was presented at IPCPR 2012, for the house''s twenty years: a Nicaraguan puro of Cuban seed, in Sun Grown or Maduro wrappers, with tobaccos from the farms of Estelí, Condega and Jalapa. The house now also offers it with an Ecuadorian Connecticut wrapper; its tobaccos are aged at least eight years and the wrappers then go into bourbon barrels.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La serie 20th Anniversary, salida en 2012 por los veinte años de la casa, muestra claramente esa ambición. La capa oscuro nicaragüense —fermentada largamente para desarrollar el carácter oscuro y aceitoso que el San Andrés Maduro da con más naturalidad— produce sobre la tripa de Jalapa un perfil de chocolate negro y de espresso que desafía directamente a la Serie V de Oliva en su propio terreno. El robusto es la vitola que situó a Perdomo entre las casas cuyas expresiones altas se discuten junto a las de Padrón y de Oliva.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La serie 20th Anniversary, salida en 2012 por los veinte años de la casa, muestra claramente esa ambición. La capa oscuro nicaragüense —fermentada largamente para desarrollar el carácter oscuro y aceitoso que el San Andrés Maduro da con más naturalidad— produce sobre la tripa de Jalapa un perfil de chocolate negro y de espresso que desafía directamente a la Serie V de Oliva en su propio terreno. El robusto es la vitola que situó a Perdomo entre las casas cuyas expresiones altas se discuten junto a las de Padrón y de Oliva.', 'La 20th Anniversary se presenta en la IPCPR 2012, por los veinte años de la casa: un puro nicaragüense de semilla cubana, con capas Sun Grown o Maduro, con tabacos de las fincas de Estelí, Condega y Jalapa. La casa la ofrece hoy también con capa Connecticut ecuatoriana; sus tabacos envejecen al menos ocho años y las capas pasan después a barricas de bourbon.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Serie 20th Anniversary, 2012 zum zwanzigjährigen Bestehen des Hauses erschienen, zeigt diesen Anspruch deutlich. Das nicaraguanische Oscuro-Deckblatt — lange fermentiert, um den dunklen, öligen Charakter zu entwickeln, den das San-Andrés-Maduro von Natur aus eher mitbringt — ergibt auf der Einlage aus Jalapa ein Profil aus Zartbitterschokolade und Espresso, das der Serie V von Oliva auf deren eigenem Feld begegnet. Der Robusto ist das Format, das Perdomo unter jene Häuser gestellt hat, deren hohe Ausdrucksformen neben denen von Padrón und Oliva besprochen werden.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Serie 20th Anniversary, 2012 zum zwanzigjährigen Bestehen des Hauses erschienen, zeigt diesen Anspruch deutlich. Das nicaraguanische Oscuro-Deckblatt — lange fermentiert, um den dunklen, öligen Charakter zu entwickeln, den das San-Andrés-Maduro von Natur aus eher mitbringt — ergibt auf der Einlage aus Jalapa ein Profil aus Zartbitterschokolade und Espresso, das der Serie V von Oliva auf deren eigenem Feld begegnet. Der Robusto ist das Format, das Perdomo unter jene Häuser gestellt hat, deren hohe Ausdrucksformen neben denen von Padrón und Oliva besprochen werden.', 'Die 20th Anniversary wird auf der IPCPR 2012 zum zwanzigjährigen Bestehen des Hauses vorgestellt: ein nicaraguanischer Puro aus kubanischem Saatgut, mit Deckblättern Sun Grown oder Maduro, mit Tabaken aus den Farmen von Estelí, Condega und Jalapa. Das Haus bietet sie heute auch mit ecuadorianischem Connecticut-Deckblatt an; die Tabake reifen mindestens acht Jahre, danach kommen die Deckblätter in Bourbonfässer.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('2012年为字号二十周年推出的 20th Anniversary 系列，把这份雄心摆得很清楚。尼加拉瓜的 oscuro 茄衣——经长时间发酵，养出圣安德烈斯马杜罗更天然带有的那种深色与油润——铺在哈拉帕茄芯之上，造出黑巧克力与意式浓缩的风格，正面挑战奥利瓦 V 系列的地盘。罗布图是那个把佩尔多莫送进「其高端表达可与帕德龙、奥利瓦并置讨论」之列的规格。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '2012年为字号二十周年推出的 20th Anniversary 系列，把这份雄心摆得很清楚。尼加拉瓜的 oscuro 茄衣——经长时间发酵，养出圣安德烈斯马杜罗更天然带有的那种深色与油润——铺在哈拉帕茄芯之上，造出黑巧克力与意式浓缩的风格，正面挑战奥利瓦 V 系列的地盘。罗布图是那个把佩尔多莫送进「其高端表达可与帕德龙、奥利瓦并置讨论」之列的规格。', '20th Anniversary 于 IPCPR 2012 亮相，纪念该厂成立二十周年：这是一支采用古巴种子的尼加拉瓜 puro，茄衣有 Sun Grown 与 Maduro 两种，烟叶来自埃斯特利、孔德加和哈拉帕的农场。该厂如今也提供厄瓜多尔 Connecticut 茄衣的版本；烟叶至少陈化八年，茄衣随后入波本桶。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وتُظهر سلسلة «20th Anniversary»، الصادرة عام 2012 في الذكرى العشرين للدار، هذا الطموح بوضوح. فالغلاف النيكاراغوي «أوسكورو» — المخمَّر طويلًا لتنمية الطابع الداكن الزيتي الذي يعطيه سان أندريس مادورو بصورة أطبع — ينتج فوق حشوة خالابا طابعًا من الشوكولاتة الداكنة والإسبريسو يواجه السلسلة V لدى أوليفا في أرضها نفسها. والروبوستو هو القياس الذي وضع بيردومو بين الدور التي تُناقَش تعبيراتها العليا إلى جانب تعبيرات بادرون وأوليفا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وتُظهر سلسلة «20th Anniversary»، الصادرة عام 2012 في الذكرى العشرين للدار، هذا الطموح بوضوح. فالغلاف النيكاراغوي «أوسكورو» — المخمَّر طويلًا لتنمية الطابع الداكن الزيتي الذي يعطيه سان أندريس مادورو بصورة أطبع — ينتج فوق حشوة خالابا طابعًا من الشوكولاتة الداكنة والإسبريسو يواجه السلسلة V لدى أوليفا في أرضها نفسها. والروبوستو هو القياس الذي وضع بيردومو بين الدور التي تُناقَش تعبيراتها العليا إلى جانب تعبيرات بادرون وأوليفا.', 'قُدِّمت 20th Anniversary في IPCPR 2012 في الذكرى العشرين للدار: سيجار نيكاراغوي خالص (puro) من بذرة كوبية، بغلافين Sun Grown أو Maduro، وبتبغ من مزارع إستيلي وكونديغا وخالابا. وتقدّمها الدار اليوم أيضًا بغلاف Connecticut إكوادوري؛ ويُعتَّق تبغها ثماني سنوات على الأقل، ثم تدخل الأغلفة براميل البوربون.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Perdomo';

UPDATE `brands` SET
  `limited_eds` = '["Perdomo Reserve 10th Anniversary","Perdomo Double Aged 12-Year Vintage","Perdomo 30th Anniversary","Perdomo Edición de Silvio"]',
  `founded` = '1992 — Miami (Floride)',
  `factory` = 'Estelí (Nicaragua) ; fermes à Estelí, Condega et Jalapa ; siège à Miami (Floride), selon la maison en octobre 2026',
  `gamme` = '[{"name":"Perdomo 20th Anniversary","color":"#1C0A00","force":"Medium-Full","story":"Présentée à l''IPCPR 2012. Puro nicaraguayen de graine cubaine, en capes Sun Grown et Maduro (la maison ajoute aujourd''hui une version Connecticut équatorienne). Tabacs vieillis au moins huit ans, capes passées 10 mois (Sun Grown) ou 14 mois (Maduro) en fût de bourbon, force médium à corsée selon la maison en octobre 2026. Finale de chêne et de cèdre (Sun Grown), de chocolat et d''espresso (Maduro), toujours selon la maison. Tailles : Robusto 5 x 56, Epicure 6 x 56, Gordo 6 x 60, Torpedo 6 1/2 x 54, Corona Grande 6 1/2 x 48, Churchill 7 x 56 (pouces).","vitolas":["Robusto","Epicure","Gordo","Torpedo","Corona Grande","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Habano Bourbon Barrel-Aged","color":"#8B4513","force":null,"story":"Ligne de la maison en trois capes : Connecticut équatorien, Sun Grown et Maduro nicaraguayens, sur liant et tripe nicaraguayens de graine cubaine. Tabacs vieillis au moins six ans avant le passage en fût de bourbon : 8 mois (Connecticut), 10 mois (Sun Grown), 14 mois (Maduro). Force légère à moyenne pour le Connecticut, moyenne à corsée pour les deux autres, selon la maison en octobre 2026. Tailles de l''Habanito 4 x 38 au Churchill 7 x 54 (pouces).","vitolas":["Habanito","Robusto","Epicure","Gordo","Torpedo","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Reserve 10th Anniversary","color":"#6B3A1E","force":null,"wrapper":"Champagne, Sun Grown, Maduro","vitolas":[],"story":"Ligne en trois versions selon la maison en octobre 2026 : Champagne (cape Connecticut équatorienne), Sun Grown (10 mois de fût de bourbon) et Maduro (14 mois), sur liant et tripe nicaraguayens de graine cubaine, tabacs vieillis au moins six ans. Neuf tailles pour la Champagne, six pour les deux autres."}]',
  `gamme_en` = '[{"name":"Perdomo 20th Anniversary","color":"#1C0A00","force":"Medium-Full","story":"Presented at IPCPR 2012. Nicaraguan puro of Cuban seed, in Sun Grown and Maduro wrappers (the house now adds an Ecuadorian Connecticut version). Tobaccos aged at least eight years, wrappers spending 10 months (Sun Grown) or 14 months (Maduro) in bourbon barrels; strength medium to full according to the house in October 2026. Finish of oak and cedar (Sun Grown), of chocolate and espresso (Maduro), again according to the house. Sizes: Robusto 5 x 56, Epicure 6 x 56, Gordo 6 x 60, Torpedo 6 1/2 x 54, Corona Grande 6 1/2 x 48, Churchill 7 x 56 (inches).","vitolas":["Robusto","Epicure","Gordo","Torpedo","Corona Grande","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Habano Bourbon Barrel-Aged","color":"#8B4513","force":null,"story":"The house line in three wrappers: Ecuadorian Connecticut, Nicaraguan Sun Grown and Maduro, over Nicaraguan binder and filler of Cuban seed. Tobaccos aged at least six years before the bourbon barrel stage: 8 months (Connecticut), 10 months (Sun Grown), 14 months (Maduro). Strength mild to medium for the Connecticut, medium to full for the other two, according to the house in October 2026. Sizes from the Habanito 4 x 38 to the Churchill 7 x 54 (inches).","vitolas":["Habanito","Robusto","Epicure","Gordo","Torpedo","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Reserve 10th Anniversary","color":"#6B3A1E","force":null,"wrapper":"Champagne, Sun Grown, Maduro","vitolas":[],"story":"A line in three versions according to the house in October 2026: Champagne (Ecuadorian Connecticut wrapper), Sun Grown (10 months in bourbon barrels) and Maduro (14 months), over Nicaraguan binder and filler of Cuban seed, tobaccos aged at least six years. Nine sizes for the Champagne, six for the other two."}]',
  `gamme_es` = '[{"name":"Perdomo 20th Anniversary","color":"#1C0A00","force":"Medium-Full","story":"Presentada en la IPCPR 2012. Puro nicaragüense de semilla cubana, con capas Sun Grown y Maduro (la casa añade hoy una versión Connecticut ecuatoriana). Tabacos envejecidos al menos ocho años; las capas pasan 10 meses (Sun Grown) o 14 meses (Maduro) en barricas de bourbon. Fuerza de media a fuerte según la casa en octubre de 2026. Final de roble y cedro (Sun Grown), de chocolate y espresso (Maduro), también según la casa. Tamaños: Robusto 5 x 56, Epicure 6 x 56, Gordo 6 x 60, Torpedo 6 1/2 x 54, Corona Grande 6 1/2 x 48, Churchill 7 x 56 (pulgadas).","vitolas":["Robusto","Epicure","Gordo","Torpedo","Corona Grande","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Habano Bourbon Barrel-Aged","color":"#8B4513","force":null,"story":"Línea de la casa en tres capas: Connecticut ecuatoriana, Sun Grown y Maduro nicaragüenses, sobre capote y tripa nicaragüenses de semilla cubana. Tabacos envejecidos al menos seis años antes del paso por barrica de bourbon: 8 meses (Connecticut), 10 meses (Sun Grown), 14 meses (Maduro). Fuerza de ligera a media para la Connecticut, de media a fuerte para las otras dos, según la casa en octubre de 2026. Tamaños desde el Habanito 4 x 38 hasta el Churchill 7 x 54 (pulgadas).","vitolas":["Habanito","Robusto","Epicure","Gordo","Torpedo","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Reserve 10th Anniversary","color":"#6B3A1E","force":null,"wrapper":"Champagne, Sun Grown, Maduro","vitolas":[],"story":"Línea en tres versiones según la casa en octubre de 2026: Champagne (capa Connecticut ecuatoriana), Sun Grown (10 meses de barrica de bourbon) y Maduro (14 meses), sobre capote y tripa nicaragüenses de semilla cubana, con tabacos envejecidos al menos seis años. Nueve tamaños para la Champagne, seis para las otras dos."}]',
  `gamme_de` = '[{"name":"Perdomo 20th Anniversary","color":"#1C0A00","force":"Medium-Full","story":"Auf der IPCPR 2012 vorgestellt. Nicaraguanischer Puro aus kubanischem Saatgut, mit Deckblättern Sun Grown und Maduro (das Haus ergänzt heute eine Version mit ecuadorianischem Connecticut). Tabake mindestens acht Jahre gereift, die Deckblätter verbringen 10 Monate (Sun Grown) bzw. 14 Monate (Maduro) in Bourbonfässern; Stärke mittel bis kräftig laut Haus im Oktober 2026. Abgang von Eiche und Zeder (Sun Grown), von Schokolade und Espresso (Maduro), ebenfalls laut Haus. Formate: Robusto 5 x 56, Epicure 6 x 56, Gordo 6 x 60, Torpedo 6 1/2 x 54, Corona Grande 6 1/2 x 48, Churchill 7 x 56 (Zoll).","vitolas":["Robusto","Epicure","Gordo","Torpedo","Corona Grande","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Habano Bourbon Barrel-Aged","color":"#8B4513","force":null,"story":"Hauslinie mit drei Deckblättern: ecuadorianisches Connecticut, nicaraguanisches Sun Grown und Maduro, über Umblatt und Einlage aus Nicaragua, aus kubanischem Saatgut. Tabake mindestens sechs Jahre gereift, bevor sie ins Bourbonfass kommen: 8 Monate (Connecticut), 10 Monate (Sun Grown), 14 Monate (Maduro). Stärke leicht bis mittel beim Connecticut, mittel bis kräftig bei den beiden anderen, laut Haus im Oktober 2026. Formate vom Habanito 4 x 38 bis zum Churchill 7 x 54 (Zoll).","vitolas":["Habanito","Robusto","Epicure","Gordo","Torpedo","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Reserve 10th Anniversary","color":"#6B3A1E","force":null,"wrapper":"Champagne, Sun Grown, Maduro","vitolas":[],"story":"Linie in drei Versionen laut Haus im Oktober 2026: Champagne (ecuadorianisches Connecticut-Deckblatt), Sun Grown (10 Monate Bourbonfass) und Maduro (14 Monate), über Umblatt und Einlage aus Nicaragua, aus kubanischem Saatgut, Tabake mindestens sechs Jahre gereift. Neun Formate für die Champagne, sechs für die beiden anderen."}]',
  `gamme_zh` = '[{"name":"Perdomo 20th Anniversary","color":"#1C0A00","force":"Medium-Full","story":"于 IPCPR 2012 亮相。采用古巴种子的尼加拉瓜 puro，茄衣有 Sun Grown 与 Maduro 两种（该厂如今另有厄瓜多尔 Connecticut 版本）。烟叶至少陈化八年，茄衣在波本桶中停留10个月（Sun Grown）或14个月（Maduro）；据该厂2026年10月所述，力度为中等至浓郁。收尾带橡木与雪松（Sun Grown），或巧克力与浓缩咖啡（Maduro），同样据该厂所述。规格：Robusto 5 x 56，Epicure 6 x 56，Gordo 6 x 60，Torpedo 6 1/2 x 54，Corona Grande 6 1/2 x 48，Churchill 7 x 56（英寸）。","vitolas":["Robusto","Epicure","Gordo","Torpedo","Corona Grande","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Habano Bourbon Barrel-Aged","color":"#8B4513","force":null,"story":"该厂的自家系列，有三种茄衣：厄瓜多尔 Connecticut，以及尼加拉瓜的 Sun Grown 与 Maduro，茄套与茄芯均为古巴种子的尼加拉瓜烟叶。烟叶至少陈化六年，之后入波本桶：8个月（Connecticut）、10个月（Sun Grown）、14个月（Maduro）。据该厂2026年10月所述，Connecticut 力度为轻至中等，另两种为中等至浓郁。规格从 Habanito 4 x 38 到 Churchill 7 x 54（英寸）。","vitolas":["Habanito","Robusto","Epicure","Gordo","Torpedo","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Reserve 10th Anniversary","color":"#6B3A1E","force":null,"wrapper":"Champagne, Sun Grown, Maduro","vitolas":[],"story":"据该厂2026年10月所述，这条产品线有三个版本：Champagne（厄瓜多尔 Connecticut 茄衣）、Sun Grown（波本桶10个月）与 Maduro（14个月），茄套与茄芯均为古巴种子的尼加拉瓜烟叶，烟叶至少陈化六年。Champagne 有九种规格，另两种各有六种。"}]',
  `gamme_ar` = '[{"name":"Perdomo 20th Anniversary","color":"#1C0A00","force":"Medium-Full","story":"قُدِّمت في IPCPR 2012. سيجار نيكاراغوي خالص (puro) من بذرة كوبية، بغلافين Sun Grown وMaduro (وتضيف الدار اليوم نسخة Connecticut إكوادورية). تبغ معتَّق ثماني سنوات على الأقل، وتقضي الأغلفة 10 شهور (Sun Grown) أو 14 شهرًا (Maduro) في براميل البوربون؛ والقوة من متوسطة إلى قوية بحسب الدار في أكتوبر 2026. نهاية من خشب البلوط والأرز (Sun Grown)، ومن الشوكولاتة والإسبريسو (Maduro)، بحسب الدار أيضًا. القياسات: Robusto 5 x 56، وEpicure 6 x 56، وGordo 6 x 60، وTorpedo 6 1/2 x 54، وCorona Grande 6 1/2 x 48، وChurchill 7 x 56 (بالبوصة).","vitolas":["Robusto","Epicure","Gordo","Torpedo","Corona Grande","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Habano Bourbon Barrel-Aged","color":"#8B4513","force":null,"story":"تشكيلة الدار بثلاثة أغلفة: Connecticut إكوادوري، وSun Grown وMaduro نيكاراغويان، فوق غلاف داخلي وحشوة نيكاراغويين من بذرة كوبية. تبغ معتَّق ست سنوات على الأقل قبل المرور ببراميل البوربون: 8 شهور (Connecticut) و10 شهور (Sun Grown) و14 شهرًا (Maduro). القوة من خفيفة إلى متوسطة للـConnecticut، ومن متوسطة إلى قوية للغلافين الآخرين، بحسب الدار في أكتوبر 2026. القياسات من Habanito 4 x 38 إلى Churchill 7 x 54 (بالبوصة).","vitolas":["Habanito","Robusto","Epicure","Gordo","Torpedo","Churchill"],"wrapper":"Connecticut, Sun Grown, Maduro"},{"name":"Perdomo Reserve 10th Anniversary","color":"#6B3A1E","force":null,"wrapper":"Champagne, Sun Grown, Maduro","vitolas":[],"story":"تشكيلة بثلاث نسخ بحسب الدار في أكتوبر 2026: Champagne (غلاف Connecticut إكوادوري)، وSun Grown (10 شهور في براميل البوربون)، وMaduro (14 شهرًا)، فوق غلاف داخلي وحشوة نيكاراغويين من بذرة كوبية، وتبغ معتَّق ست سنوات على الأقل. تسعة قياسات لـChampagne وستة للنسختين الأخريين."}]',
  `celebrities` = '[{"name":"Nick Perdomo","anecdote":"Contrôleur aérien à l''aéroport de Miami, Nick Perdomo Jr. ouvre Nick''s Cigar Co. en août 1992 sans quitter son emploi, selon la presse du métier (2001) et Wikipédia."}]',
  `celebrities_en` = '[{"name":"Nick Perdomo","anecdote":"An air traffic controller at Miami airport, Nick Perdomo Jr. opened Nick''s Cigar Co. in August 1992 without leaving his job, according to the trade press (2001) and Wikipedia."}]',
  `celebrities_es` = '[{"name":"Nick Perdomo","anecdote":"Controlador aéreo en el aeropuerto de Miami, Nick Perdomo Jr. abre Nick''s Cigar Co. en agosto de 1992 sin dejar su empleo, según la prensa del sector (2001) y Wikipedia."}]',
  `celebrities_de` = '[{"name":"Nick Perdomo","anecdote":"Als Fluglotse am Flughafen Miami eröffnet Nick Perdomo Jr. im August 1992 Nick''s Cigar Co., ohne seine Stelle aufzugeben, laut Fachpresse (2001) und Wikipedia."}]',
  `celebrities_zh` = '[{"name":"Nick Perdomo","anecdote":"尼克·佩尔多莫（Nick Perdomo Jr.）原是迈阿密机场的空中交通管制员，据行业媒体（2001年）与维基百科，他于1992年8月开设 Nick''s Cigar Co.，并未辞去工作。"}]',
  `celebrities_ar` = '[{"name":"Nick Perdomo","anecdote":"كان نيك بيردومو الابن مراقبًا جويًّا في مطار ميامي حين افتتح Nick''s Cigar Co. في أغسطس 1992 دون أن يترك عمله، بحسب الصحافة المتخصصة (2001) وويكيبيديا."}]',
  `pairings` = '[{"type":"Whisky","name":"Scotch et bourbon","notes":"Accord suggéré par la maison pour la 20th Anniversary Sun Grown (perdomocigars.com, octobre 2026)."},{"type":"Vin","name":"Cabernet-Sauvignon","notes":"Accord suggéré par la maison pour la 20th Anniversary Maduro (perdomocigars.com, octobre 2026)."},{"type":"Café","name":"Café chaud","notes":"Accord suggéré par la maison pour la 20th Anniversary Connecticut (perdomocigars.com, octobre 2026)."}]',
  `pairings_en` = '[{"type":"Whisky","name":"Scotch and bourbon","notes":"Pairing suggested by the house for the 20th Anniversary Sun Grown (perdomocigars.com, October 2026)."},{"type":"Wine","name":"Cabernet Sauvignon","notes":"Pairing suggested by the house for the 20th Anniversary Maduro (perdomocigars.com, October 2026)."},{"type":"Coffee","name":"Hot coffee","notes":"Pairing suggested by the house for the 20th Anniversary Connecticut (perdomocigars.com, October 2026)."}]',
  `pairings_es` = '[{"type":"Whisky","name":"Scotch y bourbon","notes":"Maridaje sugerido por la casa para la 20th Anniversary Sun Grown (perdomocigars.com, octubre de 2026)."},{"type":"Vino","name":"Cabernet Sauvignon","notes":"Maridaje sugerido por la casa para la 20th Anniversary Maduro (perdomocigars.com, octubre de 2026)."},{"type":"Café","name":"Café caliente","notes":"Maridaje sugerido por la casa para la 20th Anniversary Connecticut (perdomocigars.com, octubre de 2026)."}]',
  `pairings_de` = '[{"type":"Whisky","name":"Scotch und Bourbon","notes":"Vom Haus empfohlene Begleitung zur 20th Anniversary Sun Grown (perdomocigars.com, Oktober 2026)."},{"type":"Wein","name":"Cabernet Sauvignon","notes":"Vom Haus empfohlene Begleitung zur 20th Anniversary Maduro (perdomocigars.com, Oktober 2026)."},{"type":"Kaffee","name":"Heißer Kaffee","notes":"Vom Haus empfohlene Begleitung zur 20th Anniversary Connecticut (perdomocigars.com, Oktober 2026)."}]',
  `pairings_zh` = '[{"type":"威士忌","name":"苏格兰威士忌与波本威士忌","notes":"该厂为 20th Anniversary Sun Grown 推荐的搭配（perdomocigars.com，2026年10月）。"},{"type":"葡萄酒","name":"赤霞珠","notes":"该厂为 20th Anniversary Maduro 推荐的搭配（perdomocigars.com，2026年10月）。"},{"type":"咖啡","name":"热咖啡","notes":"该厂为 20th Anniversary Connecticut 推荐的搭配（perdomocigars.com，2026年10月）。"}]',
  `pairings_ar` = '[{"type":"الويسكي","name":"سكوتش وبوربون","notes":"تناول مقترح من الدار مع 20th Anniversary Sun Grown (perdomocigars.com، أكتوبر 2026)."},{"type":"النبيذ","name":"كابيرنيه سوفينيون","notes":"تناول مقترح من الدار مع 20th Anniversary Maduro (perdomocigars.com، أكتوبر 2026)."},{"type":"القهوة","name":"قهوة ساخنة","notes":"تناول مقترح من الدار مع 20th Anniversary Connecticut (perdomocigars.com، أكتوبر 2026)."}]',
  `source` = IF(LOCATE(CAST('perdomocigars.com et cigaraficionado.com (Nick Perdomo, 1992, la première fabrique de Flagler Street à Miami, Estelí et la vallée de Jalapa) ; jrcigars.com (la gamme Nick''s Sticks)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'perdomocigars.com et cigaraficionado.com (Nick Perdomo, 1992, la première fabrique de Flagler Street à Miami, Estelí et la vallée de Jalapa) ; jrcigars.com (la gamme Nick''s Sticks)', 'perdomocigars.com « PERDOMO 20th Anniversary », « Habano Bourbon Barrel-Aged », « Reserve 10th Anniversary », « 30th Anniversary », « Double Aged 12-Year Vintage », « Experience The Perdomo Way » (octobre 2026 : lignes, capes, tailles, siège à Miami, fabrication et terres à Estelí, Condega, Jalapa) ; cigaraficionado.com « The World According to Perdomo » (novembre/décembre 2001 : Nick''s Cigar Co. août 1992, fabriques d''Estelí 1995 et 1999, pas de champs en propre) ; cigar-coop.com « Cigar Preview: Perdomo 20th Anniversary » (2012-08-01 : IPCPR 2012, capes Sun Grown et Maduro) ; cigar-coop.com « Perdomo Edición de Silvio relaunched at 2016 IPCPR » (2016-08 : relance) ; en.wikipedia.org « Perdomo (cigar brand) » (1992, San José de las Lajas, Estelí 1997 et 1999, Nick''s Sticks inactive)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Perdomo';

-- ── Plasencia ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La famille Plasencia cultive le tabac depuis 1865 — une continuité de cinq générations, sur deux continents, à travers l''un des bouleversements les plus profonds qu''ait connus le métier. Ce qui a commencé dans la province cubaine de Pinar del Río a survécu à la révolution cubaine, à la révolution nicaraguayenne, à la guerre des Contras et à un demi-siècle d''instabilité économique en Amérique centrale — et la famille n''a pas cessé de cultiver.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La famille Plasencia cultive le tabac depuis 1865 — une continuité de cinq générations, sur deux continents, à travers l''un des bouleversements les plus profonds qu''ait connus le métier. Ce qui a commencé dans la province cubaine de Pinar del Río a survécu à la révolution cubaine, à la révolution nicaraguayenne, à la guerre des Contras et à un demi-siècle d''instabilité économique en Amérique centrale — et la famille n''a pas cessé de cultiver.', 'La famille Plasencia cultive le tabac depuis 1865, dit la maison (plasenciacigars.com, octobre 2026), qui compte cinq générations. Selon le blog de Cigars Direct (2020), tout commence avec Eduardo Plasencia, venu des Canaries à Vuelta Abajo, à Cuba.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Plasencia family has grown tobacco since 1865 — a continuity spanning five generations, two continents, and one of the tobacco industry''s most profound upheavals. What began in Cuba''s Pinar del Río province survived the Cuban revolution, the Nicaraguan revolution, the Contra war, and a half-century of economic instability across Central America and the family has kept growing tobacco through all of it.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Plasencia family has grown tobacco since 1865 — a continuity spanning five generations, two continents, and one of the tobacco industry''s most profound upheavals. What began in Cuba''s Pinar del Río province survived the Cuban revolution, the Nicaraguan revolution, the Contra war, and a half-century of economic instability across Central America and the family has kept growing tobacco through all of it.', 'The Plasencia family has grown tobacco since 1865, says the house (plasenciacigars.com, October 2026), which counts five generations. According to the Cigars Direct blog (2020), it all begins with Eduardo Plasencia, who came from the Canary Islands to Vuelta Abajo, in Cuba.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La familia Plasencia cultiva tabaco desde 1865 —una continuidad de cinco generaciones, en dos continentes, a través de uno de los vuelcos más profundos que ha conocido el oficio. Lo que empezó en la provincia cubana de Pinar del Río sobrevivió a la revolución cubana, a la revolución nicaragüense, a la guerra de la Contra y a medio siglo de inestabilidad económica en Centroamérica —y la familia no dejó de cultivar.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La familia Plasencia cultiva tabaco desde 1865 —una continuidad de cinco generaciones, en dos continentes, a través de uno de los vuelcos más profundos que ha conocido el oficio. Lo que empezó en la provincia cubana de Pinar del Río sobrevivió a la revolución cubana, a la revolución nicaragüense, a la guerra de la Contra y a medio siglo de inestabilidad económica en Centroamérica —y la familia no dejó de cultivar.', 'La familia Plasencia cultiva tabaco desde 1865, dice la casa (plasenciacigars.com, octubre de 2026), que cuenta cinco generaciones. Según el blog de Cigars Direct (2020), todo empieza con Eduardo Plasencia, llegado de Canarias a Vuelta Abajo, en Cuba.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Familie Plasencia baut seit 1865 Tabak an — eine Fortdauer über fünf Generationen, auf zwei Erdteilen, durch einen der tiefsten Umbrüche, die das Fach erlebt hat. Was in der kubanischen Provinz Pinar del Río begann, überstand die kubanische Revolution, die nicaraguanische Revolution, den Contra-Krieg und ein halbes Jahrhundert wirtschaftlicher Unsicherheit in Mittelamerika — und die Familie hörte nicht auf anzubauen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Familie Plasencia baut seit 1865 Tabak an — eine Fortdauer über fünf Generationen, auf zwei Erdteilen, durch einen der tiefsten Umbrüche, die das Fach erlebt hat. Was in der kubanischen Provinz Pinar del Río begann, überstand die kubanische Revolution, die nicaraguanische Revolution, den Contra-Krieg und ein halbes Jahrhundert wirtschaftlicher Unsicherheit in Mittelamerika — und die Familie hörte nicht auf anzubauen.', 'Die Familie Plasencia baut seit 1865 Tabak an, sagt das Haus (plasenciacigars.com, Oktober 2026), das fünf Generationen zählt. Laut dem Blog von Cigars Direct (2020) beginnt alles mit Eduardo Plasencia, der von den Kanarischen Inseln nach Vuelta Abajo auf Kuba kam.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('普拉森西亚家族自1865年起种植烟草——五代人的延续，跨越两个大陆，穿过这一行所经历的最深刻的剧变之一。始于古巴比那尔德里奥省的事业，熬过了古巴革命、尼加拉瓜革命、反政府武装战争，以及中美洲半个世纪的经济动荡——而这个家族始终没有停止耕作。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '普拉森西亚家族自1865年起种植烟草——五代人的延续，跨越两个大陆，穿过这一行所经历的最深刻的剧变之一。始于古巴比那尔德里奥省的事业，熬过了古巴革命、尼加拉瓜革命、反政府武装战争，以及中美洲半个世纪的经济动荡——而这个家族始终没有停止耕作。', '据该厂所述（plasenciacigars.com，2026年10月），普拉森西亚家族自1865年起种植烟草，已传五代。据 Cigars Direct 的博客（2020年），一切始于爱德华多·普拉森西亚（Eduardo Plasencia），他从加那利群岛来到古巴的阿巴霍谷。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تزرع عائلة بلاسينسيا التبغ منذ 1865 — استمرارٌ عبر خمسة أجيال، في قارّتين، وعبر واحد من أعمق الانقلابات التي عرفتها المهنة. فما بدأ في مقاطعة بينار ديل ريو الكوبية نجا من الثورة الكوبية، ومن الثورة النيكاراغوية، ومن حرب الكونترا، ومن نصف قرن من عدم الاستقرار الاقتصادي في أمريكا الوسطى — ولم تكفّ العائلة عن الزراعة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تزرع عائلة بلاسينسيا التبغ منذ 1865 — استمرارٌ عبر خمسة أجيال، في قارّتين، وعبر واحد من أعمق الانقلابات التي عرفتها المهنة. فما بدأ في مقاطعة بينار ديل ريو الكوبية نجا من الثورة الكوبية، ومن الثورة النيكاراغوية، ومن حرب الكونترا، ومن نصف قرن من عدم الاستقرار الاقتصادي في أمريكا الوسطى — ولم تكفّ العائلة عن الزراعة.', 'تزرع عائلة بلاسينسيا التبغ منذ 1865، بحسب الدار (plasenciacigars.com، أكتوبر 2026)، وهي تعدّ خمسة أجيال. وبحسب مدونة Cigars Direct (2020)، يبدأ كل شيء مع إدواردو بلاسينسيا، الذي جاء من جزر الكناري إلى فويلتا أباخو في كوبا.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Plasencia';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''exil de Cuba, en 1961, fixa la trajectoire. Comme la plupart des familles de tabac cubaines, les Plasencia emportèrent leurs semences, leur savoir et leurs relations professionnelles. À la différence de la plupart, ils trouvèrent des terres réellement exceptionnelles. La vallée de Jalapa, dans le nord du Nicaragua — un bassin volcanique à 900 mètres d''altitude, dont l''humidité et les amplitudes de température rappellent une partie de ce qui fait la Vuelta Abajo — devint leur base principale.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''exil de Cuba, en 1961, fixa la trajectoire. Comme la plupart des familles de tabac cubaines, les Plasencia emportèrent leurs semences, leur savoir et leurs relations professionnelles. À la différence de la plupart, ils trouvèrent des terres réellement exceptionnelles. La vallée de Jalapa, dans le nord du Nicaragua — un bassin volcanique à 900 mètres d''altitude, dont l''humidité et les amplitudes de température rappellent une partie de ce qui fait la Vuelta Abajo — devint leur base principale.', 'Les sources divergent sur la suite. Selon Cigars Direct (2020), le gouvernement cubain saisit la ferme en 1963, Don Sixto passe par le Mexique puis le Nicaragua, où il plante vers 1965 ; des rebelles sandinistes brûlent ses fermes en 1978 et la famille part au Honduras. Selon la presse du métier, c''est la prise de pouvoir sandiniste de 1979 qui saisit les fermes ; Wikipédia parle du début des années 1980. Néstor Plasencia reprend les opérations de tabac en 1986 (Cigars Direct) ; la fabrique d''Ocotal, au Nicaragua, ouvre en 1992 selon Wikipédia, en 1994 selon la presse du métier.'), `history`),
  `history_en` = IF(LOCATE(CAST('The exile from Cuba in 1961 set the trajectory. Like most Cuban tobacco families, the Plasencias carried their seeds, their knowledge, and their professional contacts into displacement. Unlike most, they found their way to land that proved genuinely exceptional. The Jalapa Valley in northern Nicaragua — a volcanic basin at 900 meters altitude, with consistent humidity and temperature ranges that replicate many of the conditions that make Vuelta Abajo distinctive — became their primary base of operations.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The exile from Cuba in 1961 set the trajectory. Like most Cuban tobacco families, the Plasencias carried their seeds, their knowledge, and their professional contacts into displacement. Unlike most, they found their way to land that proved genuinely exceptional. The Jalapa Valley in northern Nicaragua — a volcanic basin at 900 meters altitude, with consistent humidity and temperature ranges that replicate many of the conditions that make Vuelta Abajo distinctive — became their primary base of operations.', 'Sources diverge on what follows. According to Cigars Direct (2020), the Cuban government seized the farm in 1963, Don Sixto went through Mexico and then Nicaragua, where he planted around 1965; Sandinista rebels burned his farms in 1978 and the family left for Honduras. According to the trade press, it was the Sandinista takeover of 1979 that seized the farms; Wikipedia speaks of the early 1980s. Néstor Plasencia took over the tobacco operations in 1986 (Cigars Direct); the Ocotal factory, in Nicaragua, opened in 1992 according to Wikipedia, in 1994 according to the trade press.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El exilio de Cuba, en 1961, fijó la trayectoria. Como la mayoría de las familias tabaqueras cubanas, los Plasencia se llevaron sus semillas, su saber y sus relaciones profesionales. A diferencia de la mayoría, encontraron tierras realmente excepcionales. El valle de Jalapa, en el norte de Nicaragua —una cuenca volcánica a 900 metros de altitud, cuya humedad y amplitudes de temperatura recuerdan parte de lo que hace la Vuelta Abajo—, se convirtió en su base principal.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El exilio de Cuba, en 1961, fijó la trayectoria. Como la mayoría de las familias tabaqueras cubanas, los Plasencia se llevaron sus semillas, su saber y sus relaciones profesionales. A diferencia de la mayoría, encontraron tierras realmente excepcionales. El valle de Jalapa, en el norte de Nicaragua —una cuenca volcánica a 900 metros de altitud, cuya humedad y amplitudes de temperatura recuerdan parte de lo que hace la Vuelta Abajo—, se convirtió en su base principal.', 'Las fuentes divergen sobre lo que sigue. Según Cigars Direct (2020), el gobierno cubano confisca la finca en 1963, Don Sixto pasa por México y luego por Nicaragua, donde planta hacia 1965; rebeldes sandinistas queman sus fincas en 1978 y la familia parte a Honduras. Según la prensa del sector, es la toma del poder sandinista de 1979 la que confisca las fincas; Wikipedia habla de principios de la década de 1980. Néstor Plasencia retoma las operaciones tabaqueras en 1986 (Cigars Direct); la fábrica de Ocotal, en Nicaragua, abre en 1992 según Wikipedia y en 1994 según la prensa del sector.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das Exil aus Kuba legte 1961 die Bahn fest. Wie die meisten kubanischen Tabakfamilien nahmen die Plasencias ihr Saatgut, ihr Wissen und ihre beruflichen Beziehungen mit. Anders als die meisten fanden sie wirklich außergewöhnliches Land. Das Tal von Jalapa im Norden Nicaraguas — ein vulkanisches Becken auf 900 Metern Höhe, dessen Feuchte und Temperaturspannen einen Teil dessen wachrufen, was die Vuelta Abajo ausmacht — wurde ihre Hauptbasis.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das Exil aus Kuba legte 1961 die Bahn fest. Wie die meisten kubanischen Tabakfamilien nahmen die Plasencias ihr Saatgut, ihr Wissen und ihre beruflichen Beziehungen mit. Anders als die meisten fanden sie wirklich außergewöhnliches Land. Das Tal von Jalapa im Norden Nicaraguas — ein vulkanisches Becken auf 900 Metern Höhe, dessen Feuchte und Temperaturspannen einen Teil dessen wachrufen, was die Vuelta Abajo ausmacht — wurde ihre Hauptbasis.', 'Über den weiteren Verlauf gehen die Quellen auseinander. Laut Cigars Direct (2020) beschlagnahmt die kubanische Regierung die Farm 1963, Don Sixto geht über Mexiko und dann nach Nicaragua, wo er um 1965 pflanzt; sandinistische Rebellen brennen 1978 seine Farmen nieder, und die Familie geht nach Honduras. Laut der Fachpresse ist es die sandinistische Machtübernahme von 1979, die die Farmen beschlagnahmt; Wikipedia nennt den Beginn der 1980er Jahre. Néstor Plasencia übernimmt 1986 die Tabakgeschäfte (Cigars Direct); die Fabrik in Ocotal in Nicaragua eröffnet laut Wikipedia 1992, laut Fachpresse 1994.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('1961年离开古巴的流亡，定下了此后的走向。和多数古巴烟草家族一样，普拉森西亚家带走了种子、本事与职业上的人脉。与多数人不同的是，他们找到了真正出色的土地。尼加拉瓜北部的哈拉帕山谷——一处海拔900米的火山盆地，其湿度与温差让人想起构成阿巴霍谷的一部分条件——成了他们的主基地。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '1961年离开古巴的流亡，定下了此后的走向。和多数古巴烟草家族一样，普拉森西亚家带走了种子、本事与职业上的人脉。与多数人不同的是，他们找到了真正出色的土地。尼加拉瓜北部的哈拉帕山谷——一处海拔900米的火山盆地，其湿度与温差让人想起构成阿巴霍谷的一部分条件——成了他们的主基地。', '关于后来的事，各方说法不一。据 Cigars Direct（2020年），古巴政府于1963年没收了农场，堂·西斯托（Don Sixto）取道墨西哥前往尼加拉瓜，约在1965年于当地种植；桑地诺叛军1978年烧毁了他的农场，家族迁往洪都拉斯。据行业媒体，没收农场的是1979年桑地诺政权的上台；维基百科则说是1980年代初。内斯托·普拉森西亚（Néstor Plasencia）于1986年接手烟草业务（Cigars Direct）；尼加拉瓜的奥科塔尔工厂，据维基百科1992年开业，据行业媒体则为1994年。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('حدّد المنفى من كوبا، عام 1961، المسار. فكما فعلت معظم عائلات التبغ الكوبية، حملت عائلة بلاسينسيا بذورها ومعرفتها وعلاقاتها المهنية. لكنها، خلافًا لمعظمها، وجدت أرضًا استثنائية حقًّا. فصار وادي خالابا في شمال نيكاراغوا — حوض بركاني على ارتفاع 900 متر، تستحضر رطوبته وفوارقه الحرارية جانبًا مما يصنع فويلتا أباخو — قاعدتها الرئيسة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'حدّد المنفى من كوبا، عام 1961، المسار. فكما فعلت معظم عائلات التبغ الكوبية، حملت عائلة بلاسينسيا بذورها ومعرفتها وعلاقاتها المهنية. لكنها، خلافًا لمعظمها، وجدت أرضًا استثنائية حقًّا. فصار وادي خالابا في شمال نيكاراغوا — حوض بركاني على ارتفاع 900 متر، تستحضر رطوبته وفوارقه الحرارية جانبًا مما يصنع فويلتا أباخو — قاعدتها الرئيسة.', 'وتتباين المصادر في ما تلا ذلك. فبحسب Cigars Direct (2020)، صادرت الحكومة الكوبية المزرعة عام 1963، ومرّ دون سيكستو بالمكسيك ثم بنيكاراغوا، حيث زرع نحو عام 1965؛ وأحرق متمرّدون ساندينيون مزارعه عام 1978، فرحلت العائلة إلى هندوراس. وبحسب الصحافة المتخصصة، فإن استيلاء الساندينيين على الحكم عام 1979 هو الذي صادر المزارع؛ أما ويكيبيديا فتتحدث عن مطلع الثمانينيات. وتولّى نستور بلاسينسيا عمليات التبغ عام 1986 (Cigars Direct)؛ وافتُتح مصنع أوكوتال في نيكاراغوا عام 1992 بحسب ويكيبيديا، وعام 1994 بحسب الصحافة المتخصصة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Plasencia';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Pendant des décennies, l''histoire des Plasencia fut invisible pour le fumeur et essentielle pour presque tous les fabricants. La famille a fourni la feuille à Davidoff, qui l''emploie dans le Millennium Blend. À Padrón, qui l''emploie dans la série 1926. À My Father, qui a bâti en partie sur elle son identité nicaraguayenne. Ashton, Rocky Patel, Alec Bradley — la liste des maisons dont la production premium nicaraguayenne dépend de la feuille Plasencia se lit comme un annuaire du marché américain.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Pendant des décennies, l''histoire des Plasencia fut invisible pour le fumeur et essentielle pour presque tous les fabricants. La famille a fourni la feuille à Davidoff, qui l''emploie dans le Millennium Blend. À Padrón, qui l''emploie dans la série 1926. À My Father, qui a bâti en partie sur elle son identité nicaraguayenne. Ashton, Rocky Patel, Alec Bradley — la liste des maisons dont la production premium nicaraguayenne dépend de la feuille Plasencia se lit comme un annuaire du marché américain.', 'Pendant longtemps, la famille a surtout été connue comme cultivatrice et comme fabricante pour compte de tiers. Selon la presse du métier, elle fournit de la feuille à Davidoff et fabrique des cigares pour Rocky Patel et Alec Bradley, entre autres ; Wikipédia ajoute Swisher.'), `history`),
  `history_en` = IF(LOCATE(CAST('For decades, the Plasencia story was invisible to cigar consumers but essential to virtually every major manufacturer. The family supplied leaf to Davidoff, who used it in the Millennium Blend. They supplied Padrón, who used it in the 1926 Series. They supplied My Father, who built his Nicaraguan identity partly on their leaf. Ashton, Rocky Patel, Alec Bradley — the list of houses whose premium Nicaraguan production depends on Plasencia leaf reads like a directory of the American market.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'For decades, the Plasencia story was invisible to cigar consumers but essential to virtually every major manufacturer. The family supplied leaf to Davidoff, who used it in the Millennium Blend. They supplied Padrón, who used it in the 1926 Series. They supplied My Father, who built his Nicaraguan identity partly on their leaf. Ashton, Rocky Patel, Alec Bradley — the list of houses whose premium Nicaraguan production depends on Plasencia leaf reads like a directory of the American market.', 'For a long time, the family was known above all as a grower and as a contract manufacturer. According to the trade press, it supplies leaf to Davidoff and makes cigars for Rocky Patel and Alec Bradley, among others; Wikipedia adds Swisher.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Durante décadas, la historia de los Plasencia fue invisible para el fumador y esencial para casi todos los fabricantes. La familia ha suministrado la hoja a Davidoff, que la emplea en el Millennium Blend. A Padrón, que la emplea en la serie 1926. A My Father, que levantó en parte sobre ella su identidad nicaragüense. Ashton, Rocky Patel, Alec Bradley —la lista de casas cuya producción premium nicaragüense depende de la hoja Plasencia se lee como un directorio del mercado estadounidense.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Durante décadas, la historia de los Plasencia fue invisible para el fumador y esencial para casi todos los fabricantes. La familia ha suministrado la hoja a Davidoff, que la emplea en el Millennium Blend. A Padrón, que la emplea en la serie 1926. A My Father, que levantó en parte sobre ella su identidad nicaragüense. Ashton, Rocky Patel, Alec Bradley —la lista de casas cuya producción premium nicaragüense depende de la hoja Plasencia se lee como un directorio del mercado estadounidense.', 'Durante mucho tiempo, la familia fue conocida sobre todo como cultivadora y como fabricante por cuenta de terceros. Según la prensa del sector, suministra hoja a Davidoff y fabrica puros para Rocky Patel y Alec Bradley, entre otros; Wikipedia añade a Swisher.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Jahrzehntelang war die Geschichte der Plasencias für den Raucher unsichtbar und für fast jeden Hersteller wesentlich. Die Familie hat das Blatt an Davidoff geliefert, das es im Millennium Blend verwendet. An Padrón, das es in der Serie 1926 verwendet. An My Father, das seine nicaraguanische Identität zum Teil darauf gebaut hat. Ashton, Rocky Patel, Alec Bradley — die Liste der Häuser, deren nicaraguanische Premiumproduktion vom Plasencia-Blatt abhängt, liest sich wie ein Verzeichnis des amerikanischen Marktes.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Jahrzehntelang war die Geschichte der Plasencias für den Raucher unsichtbar und für fast jeden Hersteller wesentlich. Die Familie hat das Blatt an Davidoff geliefert, das es im Millennium Blend verwendet. An Padrón, das es in der Serie 1926 verwendet. An My Father, das seine nicaraguanische Identität zum Teil darauf gebaut hat. Ashton, Rocky Patel, Alec Bradley — die Liste der Häuser, deren nicaraguanische Premiumproduktion vom Plasencia-Blatt abhängt, liest sich wie ein Verzeichnis des amerikanischen Marktes.', 'Lange Zeit war die Familie vor allem als Anbauerin und als Lohnfertigerin bekannt. Laut der Fachpresse liefert sie Blatt an Davidoff und fertigt Zigarren unter anderem für Rocky Patel und Alec Bradley; Wikipedia nennt zusätzlich Swisher.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('数十年间，普拉森西亚的故事对烟客是隐形的，对几乎所有厂商却是根本的。这个家族向大卫杜夫供叶，用于千禧配方；向帕德龙供叶，用于1926系列；向 My Father 供叶，后者的尼加拉瓜身份有一部分正建立在它之上。阿什顿、洛基·帕特尔、亚历克·布拉德利——那些高端尼加拉瓜产品依赖普拉森西亚叶子的字号，列出来像一份美国市场的名录。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '数十年间，普拉森西亚的故事对烟客是隐形的，对几乎所有厂商却是根本的。这个家族向大卫杜夫供叶，用于千禧配方；向帕德龙供叶，用于1926系列；向 My Father 供叶，后者的尼加拉瓜身份有一部分正建立在它之上。阿什顿、洛基·帕特尔、亚历克·布拉德利——那些高端尼加拉瓜产品依赖普拉森西亚叶子的字号，列出来像一份美国市场的名录。', '很长一段时间里，这个家族主要以种植者和代工制造商闻名。据行业媒体，它向 Davidoff 供应烟叶，并为 Rocky Patel 和 Alec Bradley 等品牌制造雪茄；维基百科还提到 Swisher。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وطوال عقود، كان تاريخ آل بلاسينسيا غير مرئي للمدخّن وجوهريًّا لكل الصنّاع تقريبًا. فقد زوّدت العائلة بالورقة دافيدوف، التي تستعملها في «ميلينيوم بلند». وبادرون، التي تستعملها في سلسلة 1926. وماي فاذر، التي بنت عليها جزئيًّا هويتها النيكاراغوية. وآشتون، وروكي باتيل، وأليك برادلي — وقائمة الدور التي يعتمد إنتاجها النيكاراغوي الفاخر على ورقة بلاسينسيا تُقرأ كدليل للسوق الأمريكية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وطوال عقود، كان تاريخ آل بلاسينسيا غير مرئي للمدخّن وجوهريًّا لكل الصنّاع تقريبًا. فقد زوّدت العائلة بالورقة دافيدوف، التي تستعملها في «ميلينيوم بلند». وبادرون، التي تستعملها في سلسلة 1926. وماي فاذر، التي بنت عليها جزئيًّا هويتها النيكاراغوية. وآشتون، وروكي باتيل، وأليك برادلي — وقائمة الدور التي يعتمد إنتاجها النيكاراغوي الفاخر على ورقة بلاسينسيا تُقرأ كدليل للسوق الأمريكية.', 'ظلّت العائلة زمنًا طويلًا معروفة قبل كل شيء بوصفها مزارعة ومصنِّعة لحساب الغير. وبحسب الصحافة المتخصصة، تورّد الورقة إلى Davidoff وتصنع سيجارًا لحساب Rocky Patel وAlec Bradley، من بين آخرين؛ وتضيف ويكيبيديا Swisher.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Plasencia';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''Alma Fuerte, lancée en 2018, fut la première tentative sérieuse de la famille de faire des cigares sous sa propre identité. Le nom — âme forte — dit ce que les Plasencia voulaient exprimer après cinquante ans passés à soutenir les marques des autres. L''assemblage réunit leurs meilleurs tabacs du Nicaragua et du Honduras, roulés dans des formats d''une taille et d''une complexité de construction inhabituelles. La réponse du marché fut immédiate : la demande dépassa la production dès la première année.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''Alma Fuerte, lancée en 2018, fut la première tentative sérieuse de la famille de faire des cigares sous sa propre identité. Le nom — âme forte — dit ce que les Plasencia voulaient exprimer après cinquante ans passés à soutenir les marques des autres. L''assemblage réunit leurs meilleurs tabacs du Nicaragua et du Honduras, roulés dans des formats d''une taille et d''une complexité de construction inhabituelles. La réponse du marché fut immédiate : la demande dépassa la production dès la première année.', 'En 2016, la famille crée Plasencia 1865, société de distribution, et sort sous son propre nom la série Alma, dont l''Alma Fuerte (âme forte) est le premier cigare. Selon Cigar Coop (2018), c''est un puro nicaraguayen bâti sur le Criollo ''98, avec des tabacs de Condega, d''Estelí, de Jalapa et d''Ometepe. La série Cosecha, du Honduras, suit fin 2017 avec la Cosecha 146.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Alma Fuerte, launched in 2018, was the family''s first serious effort at creating cigars under their own identity. The name — Strong Soul — signals what the Plasencias wanted to say about themselves after fifty years of supporting other people''s brands. The blend uses the finest tobaccos from across their Nicaraguan and Honduran operations, rolled in formats of unusual size and construction complexity. The market response was immediate: demand outran production within the first year.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Alma Fuerte, launched in 2018, was the family''s first serious effort at creating cigars under their own identity. The name — Strong Soul — signals what the Plasencias wanted to say about themselves after fifty years of supporting other people''s brands. The blend uses the finest tobaccos from across their Nicaraguan and Honduran operations, rolled in formats of unusual size and construction complexity. The market response was immediate: demand outran production within the first year.', 'In 2016 the family created Plasencia 1865, a distribution company, and launched under its own name the Alma series, whose Alma Fuerte (strong soul) is the first cigar. According to Cigar Coop (2018), it is a Nicaraguan puro built on the Criollo ''98, with tobaccos from Condega, Estelí, Jalapa and Ometepe. The Cosecha series, from Honduras, followed at the end of 2017 with the Cosecha 146.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El Alma Fuerte, lanzado en 2018, fue la primera tentativa seria de la familia de hacer puros con su propia identidad. El nombre —alma fuerte— dice lo que los Plasencia querían expresar tras cincuenta años sostiendo las marcas de los demás. La ligada reúne sus mejores tabacos de Nicaragua y de Honduras, liados en formatos de un tamaño y una complejidad de construcción inhabituales. La respuesta del mercado fue inmediata: la demanda superó a la producción desde el primer año.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El Alma Fuerte, lanzado en 2018, fue la primera tentativa seria de la familia de hacer puros con su propia identidad. El nombre —alma fuerte— dice lo que los Plasencia querían expresar tras cincuenta años sostiendo las marcas de los demás. La ligada reúne sus mejores tabacos de Nicaragua y de Honduras, liados en formatos de un tamaño y una complejidad de construcción inhabituales. La respuesta del mercado fue inmediata: la demanda superó a la producción desde el primer año.', 'En 2016, la familia crea Plasencia 1865, sociedad de distribución, y lanza con su propio nombre la serie Alma, de la que el Alma Fuerte (alma fuerte) es el primer puro. Según Cigar Coop (2018), es un puro nicaragüense construido sobre el Criollo ''98, con tabacos de Condega, Estelí, Jalapa y Ometepe. La serie Cosecha, de Honduras, llega a finales de 2017 con la Cosecha 146.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Alma Fuerte, 2018 herausgebracht, war der erste ernsthafte Versuch der Familie, Zigarren unter eigener Identität zu machen. Der Name — starke Seele — sagt, was die Plasencias nach fünfzig Jahren im Dienst fremder Marken ausdrücken wollten. Die Mischung vereint ihre besten Tabake aus Nicaragua und Honduras, gerollt in Formaten von ungewöhnlicher Größe und baulicher Vielschichtigkeit. Die Antwort des Marktes kam sofort: Schon im ersten Jahr überstieg die Nachfrage die Produktion.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Alma Fuerte, 2018 herausgebracht, war der erste ernsthafte Versuch der Familie, Zigarren unter eigener Identität zu machen. Der Name — starke Seele — sagt, was die Plasencias nach fünfzig Jahren im Dienst fremder Marken ausdrücken wollten. Die Mischung vereint ihre besten Tabake aus Nicaragua und Honduras, gerollt in Formaten von ungewöhnlicher Größe und baulicher Vielschichtigkeit. Die Antwort des Marktes kam sofort: Schon im ersten Jahr überstieg die Nachfrage die Produktion.', '2016 gründet die Familie Plasencia 1865, ein Vertriebsunternehmen, und bringt unter eigenem Namen die Serie Alma heraus, deren erste Zigarre die Alma Fuerte (starke Seele) ist. Laut Cigar Coop (2018) ist sie ein nicaraguanischer Puro auf Grundlage des Criollo ''98, mit Tabaken aus Condega, Estelí, Jalapa und Ometepe. Die Serie Cosecha aus Honduras folgt Ende 2017 mit der Cosecha 146.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('2018年推出的 Alma Fuerte，是这个家族第一次认真地以自己的身份做雪茄。这个名字——强悍的灵魂——道出了普拉森西亚家在为别人的品牌撑了五十年之后想要表达的东西。配方汇集了他们在尼加拉瓜与洪都拉斯最好的烟叶，卷成尺寸与结构复杂度都不寻常的规格。市场的回应是即时的：第一年需求就超过了产量。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '2018年推出的 Alma Fuerte，是这个家族第一次认真地以自己的身份做雪茄。这个名字——强悍的灵魂——道出了普拉森西亚家在为别人的品牌撑了五十年之后想要表达的东西。配方汇集了他们在尼加拉瓜与洪都拉斯最好的烟叶，卷成尺寸与结构复杂度都不寻常的规格。市场的回应是即时的：第一年需求就超过了产量。', '2016年，家族创立分销公司 Plasencia 1865，并以自己的名字推出 Alma 系列，其中 Alma Fuerte（强悍的灵魂）是首支雪茄。据 Cigar Coop（2018年），这是一支以 Criollo ''98 为基础的尼加拉瓜 puro，烟叶来自孔德加、埃斯特利、哈拉帕与奥梅特佩。来自洪都拉斯的 Cosecha 系列于2017年底接续推出，首款是 Cosecha 146。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وكانت «ألما فويرتي»، الصادرة عام 2018، أول محاولة جادّة للعائلة لصناعة سيجار بهويتها الخاصة. والاسم — الروح القوية — يقول ما أرادت العائلة التعبير عنه بعد خمسين عامًا في إسناد علامات الآخرين. وتجمع الخلطة أفضل تبغها من نيكاراغوا وهندوراس، ملفوفًا في قياسات غير معتادة في حجمها وفي تعقيد بنائها. وجاء ردّ السوق فوريًّا: تجاوز الطلبُ الإنتاجَ منذ السنة الأولى.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وكانت «ألما فويرتي»، الصادرة عام 2018، أول محاولة جادّة للعائلة لصناعة سيجار بهويتها الخاصة. والاسم — الروح القوية — يقول ما أرادت العائلة التعبير عنه بعد خمسين عامًا في إسناد علامات الآخرين. وتجمع الخلطة أفضل تبغها من نيكاراغوا وهندوراس، ملفوفًا في قياسات غير معتادة في حجمها وفي تعقيد بنائها. وجاء ردّ السوق فوريًّا: تجاوز الطلبُ الإنتاجَ منذ السنة الأولى.', 'في عام 2016 أنشأت العائلة Plasencia 1865، شركة التوزيع، وأطلقت باسمها سلسلة Alma، التي Alma Fuerte (الروح القوية) أول سيجار فيها. وبحسب Cigar Coop (2018)، هو سيجار نيكاراغوي خالص (puro) مبني على Criollo ''98، بتبغ من كونديغا وإستيلي وخالابا وأوميتبي. وتلتها سلسلة Cosecha، من هندوراس، في أواخر 2017 مع Cosecha 146.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Plasencia';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La famille exploite aujourd''hui plus de 3 000 acres de plantations au Nicaragua, au Honduras et au Guatemala. Perfecto García, patriarche de la génération actuelle, arpente encore les champs. L''affaire née dans la Cuba du XIXe siècle n''a jamais cessé de croître.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La famille exploite aujourd''hui plus de 3 000 acres de plantations au Nicaragua, au Honduras et au Guatemala. Perfecto García, patriarche de la génération actuelle, arpente encore les champs. L''affaire née dans la Cuba du XIXe siècle n''a jamais cessé de croître.', 'En octobre 2026, la maison déclare posséder des fermes dans sept terroirs du Nicaragua et du Honduras (Condega, Estelí, vallée de Jalapa et Ometepe ; Jamastrán, Talanga et Azacualpa), sur plus de 4 900 acres.'), `history`),
  `history_en` = IF(LOCATE(CAST('The family now operates over 3,000 acres of plantations across Nicaragua, Honduras, and Guatemala. Perfecto García, the current generation''s patriarch, still walks the fields. The operation that began in nineteenth-century Cuba has never stopped growing.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The family now operates over 3,000 acres of plantations across Nicaragua, Honduras, and Guatemala. Perfecto García, the current generation''s patriarch, still walks the fields. The operation that began in nineteenth-century Cuba has never stopped growing.', 'In October 2026 the house declares that it owns farms in seven growing areas of Nicaragua and Honduras (Condega, Estelí, the Jalapa Valley and Ometepe; Jamastrán, Talanga and Azacualpa), covering over 4,900 acres.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La familia explota hoy más de 3.000 acres de plantaciones en Nicaragua, en Honduras y en Guatemala. Perfecto García, patriarca de la generación actual, recorre todavía los campos. El negocio nacido en la Cuba del siglo XIX no ha dejado de crecer.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La familia explota hoy más de 3.000 acres de plantaciones en Nicaragua, en Honduras y en Guatemala. Perfecto García, patriarca de la generación actual, recorre todavía los campos. El negocio nacido en la Cuba del siglo XIX no ha dejado de crecer.', 'En octubre de 2026, la casa declara poseer fincas en siete terruños de Nicaragua y Honduras (Condega, Estelí, valle de Jalapa y Ometepe; Jamastrán, Talanga y Azacualpa), sobre más de 4.900 acres.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Familie bewirtschaftet heute mehr als 3.000 Acres Plantagen in Nicaragua, Honduras und Guatemala. Perfecto García, Patriarch der jetzigen Generation, geht noch immer über die Felder. Das im Kuba des 19. Jahrhunderts entstandene Unternehmen hat nie aufgehört zu wachsen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Familie bewirtschaftet heute mehr als 3.000 Acres Plantagen in Nicaragua, Honduras und Guatemala. Perfecto García, Patriarch der jetzigen Generation, geht noch immer über die Felder. Das im Kuba des 19. Jahrhunderts entstandene Unternehmen hat nie aufgehört zu wachsen.', 'Im Oktober 2026 erklärt das Haus, Farmen in sieben Anbaugebieten Nicaraguas und von Honduras zu besitzen (Condega, Estelí, Tal von Jalapa und Ometepe; Jamastrán, Talanga und Azacualpa), auf mehr als 4.900 Acres.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这个家族如今在尼加拉瓜、洪都拉斯与危地马拉经营着三千多英亩的种植园。当代家族的长者佩尔费克托·加西亚仍然亲自走田。这门始于19世纪古巴的生意，从未停止生长。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这个家族如今在尼加拉瓜、洪都拉斯与危地马拉经营着三千多英亩的种植园。当代家族的长者佩尔费克托·加西亚仍然亲自走田。这门始于19世纪古巴的生意，从未停止生长。', '2026年10月，该厂宣称在尼加拉瓜与洪都拉斯的七个产区拥有农场（孔德加、埃斯特利、哈拉帕山谷与奥梅特佩；Jamastrán、Talanga 与 Azacualpa），面积达4900多英亩。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وتستثمر العائلة اليوم أكثر من 3000 فدّان من المزارع في نيكاراغوا وهندوراس وغواتيمالا. ولا يزال بيرفكتو غارسيا، شيخ الجيل الحالي، يجوب الحقول. والعمل الذي وُلد في كوبا القرن التاسع عشر لم يتوقّف عن النمو.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وتستثمر العائلة اليوم أكثر من 3000 فدّان من المزارع في نيكاراغوا وهندوراس وغواتيمالا. ولا يزال بيرفكتو غارسيا، شيخ الجيل الحالي، يجوب الحقول. والعمل الذي وُلد في كوبا القرن التاسع عشر لم يتوقّف عن النمو.', 'في أكتوبر 2026 تعلن الدار أنها تملك مزارع في سبع مناطق زراعية من نيكاراغوا وهندوراس (كونديغا وإستيلي ووادي خالابا وأوميتبي؛ وJamastrán وTalanga وAzacualpa)، على ما يزيد على 4900 أكر.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Plasencia';

UPDATE `brands` SET
  `limited_eds` = '["Plasencia Triunfal 2026"]',
  `founded` = '1865 Cuba → Nicaragua (années 1960)',
  `gamme` = '[{"name":"Alma Fuerte","color":"#8B0000","force":null,"story":"Premier cigare de la série Alma, lancé en 2016. Puro nicaraguayen bâti sur le Criollo ''98, avec des tabacs de Condega, d''Estelí, de Jalapa et d''Ometepe, fabriqué chez Plasencia S.A. à Estelí (Cigar Coop, 2018). Formats décrits : Nestor IV (toro box-pressé, 6 1/4 x 54), Generación V (salomon box-pressé) et Sixto II (hexagonal) ; une Robustus I (5 1/4 x 52) s''est ajoutée en 2019. La maison propose la ligne en colorado claro et en oscuro.","vitolas":["Robustus Magnus","Toro Largo","Nestor IV","Generacion V","Sixto I"],"wrapper":"Colorado Claro ou Oscuro"},{"name":"Cosecha 146","color":"#722F37","force":null,"story":"Première de la série Cosecha, arrivée chez les détaillants américains en novembre 2017 (Cigar Coop). Le nom renvoie à la 146e récolte de la famille, celle de 2011-2012, comptée depuis 1865 ; ce n''est pas un assemblage annuel. Cinq formats : La Música (5 x 50), La Vega (5 1/4 x 52), San Luis (5 3/4 x 54), San Agustín (torpedo, 6 1/4 x 52) et Monte Carlo (6 x 58). La maison présente en octobre 2026 des Cosecha 149 et 151.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Honduras"},{"name":"Alma del Campo","color":"#A0522D","force":null,"story":"Deuxième cigare de la série Alma, présenté à l''IPCPR 2017, en tabac nicaraguayen cultivé par Plasencia ; la maison la rattache à la vallée de Jalapa. Format cité : Travesía (6 1/2 x 56).","vitolas":["Travesía","Candela","Toro"],"wrapper":"Nicaragua (Jalapa)"}]',
  `gamme_en` = '[{"name":"Alma Fuerte","color":"#8B0000","force":null,"story":"First cigar of the Alma series, launched in 2016. Nicaraguan puro built on the Criollo ''98, with tobaccos from Condega, Estelí, Jalapa and Ometepe, made at Plasencia S.A. in Estelí (Cigar Coop, 2018). Sizes described: Nestor IV (box-pressed toro, 6 1/4 x 54), Generación V (box-pressed salomon) and Sixto II (hexagonal); a Robustus I (5 1/4 x 52) was added in 2019. The house offers the line in colorado claro and oscuro.","vitolas":["Robustus Magnus","Toro Largo","Nestor IV","Generacion V","Sixto I"],"wrapper":"Colorado Claro or Oscuro"},{"name":"Cosecha 146","color":"#722F37","force":null,"story":"First of the Cosecha series, it reached American retailers in November 2017 (Cigar Coop). The name refers to the family''s 146th harvest, that of 2011-2012, counted from 1865; it is not an annual blend. Five sizes: La Música (5 x 50), La Vega (5 1/4 x 52), San Luis (5 3/4 x 54), San Agustín (torpedo, 6 1/4 x 52) and Monte Carlo (6 x 58). The house presents Cosecha 149 and 151 in October 2026.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Honduran"},{"name":"Alma del Campo","color":"#A0522D","force":null,"story":"Second cigar of the Alma series, presented at IPCPR 2017, in Nicaraguan tobacco grown by Plasencia; the house ties it to the Jalapa Valley. Size cited: Travesía (6 1/2 x 56).","vitolas":["Travesía","Candela","Toro"],"wrapper":"Nicaragua (Jalapa)"}]',
  `gamme_es` = '[{"name":"Alma Fuerte","color":"#8B0000","force":null,"story":"Primer puro de la serie Alma, lanzado en 2016. Puro nicaragüense construido sobre el Criollo ''98, con tabacos de Condega, Estelí, Jalapa y Ometepe, fabricado en Plasencia S.A., en Estelí (Cigar Coop, 2018). Formatos descritos: Nestor IV (toro prensado en caja, 6 1/4 x 54), Generación V (salomón prensado en caja) y Sixto II (hexagonal); en 2019 se añadió un Robustus I (5 1/4 x 52). La casa ofrece la línea en colorado claro y en oscuro.","vitolas":["Robustus Magnus","Toro Largo","Nestor IV","Generacion V","Sixto I"],"wrapper":"Colorado Claro u Oscuro"},{"name":"Cosecha 146","color":"#722F37","force":null,"story":"Primera de la serie Cosecha, llegó a los detallistas estadounidenses en noviembre de 2017 (Cigar Coop). El nombre remite a la 146.ª cosecha de la familia, la de 2011-2012, contada desde 1865; no es una ligada anual. Cinco formatos: La Música (5 x 50), La Vega (5 1/4 x 52), San Luis (5 3/4 x 54), San Agustín (torpedo, 6 1/4 x 52) y Monte Carlo (6 x 58). La casa presenta en octubre de 2026 unas Cosecha 149 y 151.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Honduras"},{"name":"Alma del Campo","color":"#A0522D","force":null,"story":"Segundo puro de la serie Alma, presentado en la IPCPR 2017, en tabaco nicaragüense cultivado por Plasencia; la casa lo vincula con el valle de Jalapa. Formato citado: Travesía (6 1/2 x 56).","vitolas":["Travesía","Candela","Toro"],"wrapper":"Nicaragua (Jalapa)"}]',
  `gamme_de` = '[{"name":"Alma Fuerte","color":"#8B0000","force":null,"story":"Erste Zigarre der Serie Alma, 2016 herausgebracht. Nicaraguanischer Puro auf Grundlage des Criollo ''98, mit Tabaken aus Condega, Estelí, Jalapa und Ometepe, hergestellt bei Plasencia S.A. in Estelí (Cigar Coop, 2018). Beschriebene Formate: Nestor IV (kastengepresster Toro, 6 1/4 x 54), Generación V (kastengepresster Salomon) und Sixto II (sechseckig); 2019 kam ein Robustus I (5 1/4 x 52) hinzu. Das Haus bietet die Linie in Colorado Claro und in Oscuro an.","vitolas":["Robustus Magnus","Toro Largo","Nestor IV","Generacion V","Sixto I"],"wrapper":"Colorado Claro oder Oscuro"},{"name":"Cosecha 146","color":"#722F37","force":null,"story":"Erste der Serie Cosecha, kam im November 2017 zu den amerikanischen Händlern (Cigar Coop). Der Name verweist auf die 146. Ernte der Familie, die von 2011-2012, gezählt ab 1865; es ist keine jährliche Mischung. Fünf Formate: La Música (5 x 50), La Vega (5 1/4 x 52), San Luis (5 3/4 x 54), San Agustín (Torpedo, 6 1/4 x 52) und Monte Carlo (6 x 58). Im Oktober 2026 stellt das Haus Cosecha 149 und 151 vor.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Honduras"},{"name":"Alma del Campo","color":"#A0522D","force":null,"story":"Zweite Zigarre der Serie Alma, auf der IPCPR 2017 vorgestellt, aus nicaraguanischem Tabak, den Plasencia anbaut; das Haus ordnet sie dem Tal von Jalapa zu. Genanntes Format: Travesía (6 1/2 x 56).","vitolas":["Travesía","Candela","Toro"],"wrapper":"Nicaragua (Jalapa)"}]',
  `gamme_zh` = '[{"name":"Alma Fuerte","color":"#8B0000","force":null,"story":"Alma 系列的首支雪茄，2016年推出。尼加拉瓜 puro，以 Criollo ''98 为基础，烟叶来自孔德加、埃斯特利、哈拉帕与奥梅特佩，由埃斯特利的 Plasencia S.A. 制造（Cigar Coop，2018年）。所述规格：Nestor IV（方压 toro，6 1/4 x 54）、Generación V（方压 salomon）与 Sixto II（六角形）；2019年又增加了 Robustus I（5 1/4 x 52）。该厂的这条产品线有 colorado claro 与 oscuro 两种茄衣。","vitolas":["Robustus Magnus","Toro Largo","Nestor IV","Generacion V","Sixto I"],"wrapper":"Colorado Claro 或 Oscuro"},{"name":"Cosecha 146","color":"#722F37","force":null,"story":"Cosecha 系列的首款，2017年11月进入美国零售商渠道（Cigar Coop）。名称指向家族的第146次收成，即2011-2012年那一季，自1865年起算；它不是年度配方。共五种规格：La Música（5 x 50）、La Vega（5 1/4 x 52）、San Luis（5 3/4 x 54）、San Agustín（torpedo，6 1/4 x 52）与 Monte Carlo（6 x 58）。2026年10月，该厂展示了 Cosecha 149 与 151。","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"洪都拉斯"},{"name":"Alma del Campo","color":"#A0522D","force":null,"story":"Alma 系列的第二支雪茄，于 IPCPR 2017 推出，使用由 Plasencia 种植的尼加拉瓜烟草；该厂将其归于哈拉帕山谷。所引规格：Travesía（6 1/2 x 56）。","vitolas":["Travesía","Candela","Toro"],"wrapper":"尼加拉瓜（哈拉帕）"}]',
  `gamme_ar` = '[{"name":"Alma Fuerte","color":"#8B0000","force":null,"story":"أول سيجار في سلسلة Alma، أُطلق عام 2016. سيجار نيكاراغوي خالص (puro) مبني على Criollo ''98، بتبغ من كونديغا وإستيلي وخالابا وأوميتبي، صُنع لدى Plasencia S.A. في إستيلي (Cigar Coop، 2018). القياسات الموصوفة: Nestor IV (تورو مضغوط الشكل، 6 1/4 x 54)، وGeneración V (سالومون مضغوط الشكل)، وSixto II (سداسي)؛ وأُضيف قياس Robustus I (5 1/4 x 52) عام 2019. وتقدّم الدار هذه التشكيلة بغلافي colorado claro وoscuro.","vitolas":["Robustus Magnus","Toro Largo","Nestor IV","Generacion V","Sixto I"],"wrapper":"Colorado Claro أو Oscuro"},{"name":"Cosecha 146","color":"#722F37","force":null,"story":"أولى سلسلة Cosecha، وصلت إلى تجار التجزئة الأمريكيين في نوفمبر 2017 (Cigar Coop). يشير الاسم إلى الحصاد السادس والأربعين بعد المائة للعائلة، حصاد 2011-2012، محسوبًا منذ 1865؛ وهي ليست خلطة سنوية. خمسة قياسات: La Música (5 x 50)، وLa Vega (5 1/4 x 52)، وSan Luis (5 3/4 x 54)، وSan Agustín (تورنيدو، 6 1/4 x 52)، وMonte Carlo (6 x 58). وتقدّم الدار في أكتوبر 2026 Cosecha 149 وCosecha 151.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"هندوراسي"},{"name":"Alma del Campo","color":"#A0522D","force":null,"story":"ثاني سيجار في سلسلة Alma، قُدِّم في IPCPR 2017، من تبغ نيكاراغوي تزرعه Plasencia؛ وتربطه الدار بوادي خالابا. القياس المذكور: Travesía (6 1/2 x 56).","vitolas":["Travesía","Candela","Toro"],"wrapper":"نيكاراغوا (خالابا)"}]',
  `celebrities` = '[{"name":"Néstor Plasencia","anecdote":"Présenté par la maison comme la quatrième génération (Néstor Plasencia Fernández), il reprend en 1986 les opérations de tabac de la famille (Cigars Direct, 2020). La maison présente José Luis, Gustavo, Alina et Néstor Andrés Plasencia comme la cinquième génération. Elle dit contrôler la qualité à la fois par la culture et par la fabrication."}]',
  `celebrities_en` = '[{"name":"Néstor Plasencia","anecdote":"Presented by the house as the fourth generation (Néstor Plasencia Fernández), he took over the family''s tobacco operations in 1986 (Cigars Direct, 2020). The house presents José Luis, Gustavo, Alina and Néstor Andrés Plasencia as the fifth generation. It says it controls quality through both growing and manufacturing."}]',
  `celebrities_es` = '[{"name":"Néstor Plasencia","anecdote":"Presentado por la casa como la cuarta generación (Néstor Plasencia Fernández), retoma en 1986 las operaciones tabaqueras de la familia (Cigars Direct, 2020). La casa presenta a José Luis, Gustavo, Alina y Néstor Andrés Plasencia como la quinta generación. Dice controlar la calidad tanto por el cultivo como por la fabricación."}]',
  `celebrities_de` = '[{"name":"Néstor Plasencia","anecdote":"Vom Haus als vierte Generation vorgestellt (Néstor Plasencia Fernández), übernimmt er 1986 die Tabakgeschäfte der Familie (Cigars Direct, 2020). Das Haus stellt José Luis, Gustavo, Alina und Néstor Andrés Plasencia als fünfte Generation vor. Es sagt, die Qualität sowohl über den Anbau als auch über die Fertigung zu kontrollieren."}]',
  `celebrities_zh` = '[{"name":"Néstor Plasencia","anecdote":"该厂将他称为第四代（Néstor Plasencia Fernández），他于1986年接手家族的烟草业务（Cigars Direct，2020年）。该厂把何塞·路易斯、古斯塔沃、阿利娜和内斯托·安德烈斯·普拉森西亚称为第五代。它自称通过种植与制造两方面把控品质。"}]',
  `celebrities_ar` = '[{"name":"Néstor Plasencia","anecdote":"تقدّمه الدار بوصفه الجيل الرابع (Néstor Plasencia Fernández)، وقد تولّى عام 1986 عمليات التبغ للعائلة (Cigars Direct، 2020). وتقدّم الدار خوسيه لويس وغوستافو وألينا ونستور أندريس بلاسينسيا بوصفهم الجيل الخامس. وتقول إنها تراقب الجودة بالزراعة وبالتصنيع معًا."}]',
  `pairings` = '[{"type":"Rhum","name":"Flor de Caña 25 ans","notes":"Suggestion d''accord : un rhum nicaraguayen vieilli, pour une Alma Fuerte, cigare nicaraguayen."},{"type":"Café","name":"Café de Marcala (Honduras)","notes":"Suggestion d''accord : un café hondurien de Marcala, pour une Cosecha, cigare du Honduras."}]',
  `pairings_en` = '[{"type":"Rum","name":"Flor de Caña 25 years","notes":"Pairing suggestion: an aged Nicaraguan rum, for an Alma Fuerte, a Nicaraguan cigar."},{"type":"Coffee","name":"Marcala coffee (Honduras)","notes":"Pairing suggestion: a Honduran coffee from Marcala, for a Cosecha, a cigar from Honduras."}]',
  `pairings_es` = '[{"type":"Ron","name":"Flor de Caña 25 years","notes":"Sugerencia de maridaje: un ron nicaragüense añejo, para un Alma Fuerte, puro nicaragüense."},{"type":"Café","name":"Café de Marcala (Honduras)","notes":"Sugerencia de maridaje: un café hondureño de Marcala, para un Cosecha, puro de Honduras."}]',
  `pairings_de` = '[{"type":"Rum","name":"Flor de Caña 25 years","notes":"Vorschlag zur Begleitung: ein gereifter nicaraguanischer Rum, zu einer Alma Fuerte, einer nicaraguanischen Zigarre."},{"type":"Kaffee","name":"Kaffee aus Marcala (Honduras)","notes":"Vorschlag zur Begleitung: ein honduranischer Kaffee aus Marcala, zu einer Cosecha, einer Zigarre aus Honduras."}]',
  `pairings_zh` = '[{"type":"朗姆酒","name":"Flor de Caña 25 years","notes":"搭配建议：一款陈年的尼加拉瓜朗姆酒，配 Alma Fuerte 这支尼加拉瓜雪茄。"},{"type":"咖啡","name":"马尔卡拉咖啡（洪都拉斯）","notes":"搭配建议：一款洪都拉斯马尔卡拉的咖啡，配 Cosecha 这支来自洪都拉斯的雪茄。"}]',
  `pairings_ar` = '[{"type":"الروم","name":"Flor de Caña 25 years","notes":"اقتراح تناول: روم نيكاراغوي معتَّق، مع Alma Fuerte، وهو سيجار نيكاراغوي."},{"type":"القهوة","name":"قهوة مركالا (هندوراس)","notes":"اقتراح تناول: قهوة هندوراسية من مركالا، مع Cosecha، وهو سيجار من هندوراس."}]',
  `source` = IF(LOCATE(CAST('plasenciacigars.com page d''accueil (lue le 17 octobre 2026 :' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'plasenciacigars.com page d''accueil (lue le 17 octobre 2026 : depuis 1865, cinq générations, fermes dans sept terroirs du Nicaragua et du Honduras sur plus de 4 900 acres, Triunfal 2026 édition limitée, Cosecha 149 et 151) ; cigarsdirect.com « The History of Plasencia Cigars » (10 mars 2020 : Eduardo Plasencia 1865, saisie 1963, Nicaragua vers 1965, 1978, Néstor 1986) ; cigar-coop.com « Cigar News: Plasencia Cosecha 146 released into U.S. market » (14 novembre 2017 : 146e récolte 2011-2012, cinq formats) ; cigar-coop.com « Agile Cigar Review: Plasencia Alma Fuerte Nestor IV » (octobre 2018 : puro nicaraguayen, Criollo ''98, Plasencia S.A. Estelí) ; en.wikipedia.org « Nestor Plasencia » (Ocotal 1992, début des années 1980)')),
  `updated_at` = NOW()
 WHERE `name` = 'Plasencia';

-- ── Alec Bradley ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La décision d''Alan Rubin de quitter la vente de matériel médical, en 1996, pour entrer dans le cigare tenait à la fois de la passion et du calcul, dans des proportions qu''il n''a jamais précisées. Fumeur sérieux depuis sa vingtaine, il s''était forgé au fil des années une thèse sur ce qui manquait au marché américain : des cigares d''une vraie exigence, vendus à un prix qui permette de fumer tous les jours plutôt que de rationner.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La décision d''Alan Rubin de quitter la vente de matériel médical, en 1996, pour entrer dans le cigare tenait à la fois de la passion et du calcul, dans des proportions qu''il n''a jamais précisées. Fumeur sérieux depuis sa vingtaine, il s''était forgé au fil des années une thèse sur ce qui manquait au marché américain : des cigares d''une vraie exigence, vendus à un prix qui permette de fumer tous les jours plutôt que de rationner.', 'Alec Bradley naît en 1996, aux États-Unis, de la décision d''Alan Rubin de se lancer dans le cigare après la vente de l''affaire familiale d''import de quincaillerie, selon le détaillant Cigars Direct. Il n''avait, d''après la presse du métier, aucun passé dans le tabac.'), `history`),
  `history_en` = IF(LOCATE(CAST(CONCAT('Alan Rubin''s decision to leave medical equipment sales in 1996 and enter the cigar industry was driven by personal passion and commercial calculation in proportions he has never precisely specified. He had been a serious cigar smoker since his twenties and had developed, through years of careful consumption and trade reading, a specific thesis about what was missing from the American market: premium-quality cigars made with genuine seriousness, sold at prices that allowed daily smoking rather than rationing.', CHAR(13), '
', CHAR(13), '
He named the company Alec Bradley after his two sons — a gesture that established from the beginning that this was a personal project as much as a commercial one, and that its success or failure would be measured in terms more significant than quarterly revenue. The early years were precisely as difficult as the trajectory suggests: a salesman driving from account to account, opening the trunk of his car to show samples, building a distribution network one retailer at a time with no track record and no inherited relationships.', CHAR(13), '
', CHAR(13), '
The Honduras connection, developed in the early 2000s through a long-term relationship with the Plasencia family''s manufacturing operations, gave Alec Bradley access to the leaf quality and rolling precision that the brand''s ambitions required. Honduras had been overshadowed commercially by Nicaragua''s emergence as the premium power tobacco region, but the Jamastran Valley''s corojo-influenced soils and the Plasencias'' generational expertise produced leaf that blenders with good taste could work with at the highest level.', CHAR(13), '
', CHAR(13), '
The Prensado release in 2011 demonstrated how completely the investment had paid off. A box-pressed Robusto using Plasencia-grown Honduran corojo wrapper over a Guatemalan and Honduran blend, the Prensado carried the house well beyond the circle of insiders. The allocations sold out within hours of distribution. Retailers reported customers calling daily for months. The waiting list sustained itself for over two years.', CHAR(13), '
', CHAR(13), '
The brand has continued without chasing effect: the Tempus, the Medalist, the Black Market series — each represents a different expression of the Alec Bradley approach: serious Honduran-Guatemalan blends, rolled with precision, sold without ostentatious marketing.') AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, CONCAT('Alan Rubin''s decision to leave medical equipment sales in 1996 and enter the cigar industry was driven by personal passion and commercial calculation in proportions he has never precisely specified. He had been a serious cigar smoker since his twenties and had developed, through years of careful consumption and trade reading, a specific thesis about what was missing from the American market: premium-quality cigars made with genuine seriousness, sold at prices that allowed daily smoking rather than rationing.', CHAR(13), '
', CHAR(13), '
He named the company Alec Bradley after his two sons — a gesture that established from the beginning that this was a personal project as much as a commercial one, and that its success or failure would be measured in terms more significant than quarterly revenue. The early years were precisely as difficult as the trajectory suggests: a salesman driving from account to account, opening the trunk of his car to show samples, building a distribution network one retailer at a time with no track record and no inherited relationships.', CHAR(13), '
', CHAR(13), '
The Honduras connection, developed in the early 2000s through a long-term relationship with the Plasencia family''s manufacturing operations, gave Alec Bradley access to the leaf quality and rolling precision that the brand''s ambitions required. Honduras had been overshadowed commercially by Nicaragua''s emergence as the premium power tobacco region, but the Jamastran Valley''s corojo-influenced soils and the Plasencias'' generational expertise produced leaf that blenders with good taste could work with at the highest level.', CHAR(13), '
', CHAR(13), '
The Prensado release in 2011 demonstrated how completely the investment had paid off. A box-pressed Robusto using Plasencia-grown Honduran corojo wrapper over a Guatemalan and Honduran blend, the Prensado carried the house well beyond the circle of insiders. The allocations sold out within hours of distribution. Retailers reported customers calling daily for months. The waiting list sustained itself for over two years.', CHAR(13), '
', CHAR(13), '
The brand has continued without chasing effect: the Tempus, the Medalist, the Black Market series — each represents a different expression of the Alec Bradley approach: serious Honduran-Guatemalan blends, rolled with precision, sold without ostentatious marketing.'), 'Alec Bradley was born in 1996, in the United States, out of Alan Rubin''s decision to go into cigars after the sale of the family hardware import business, according to the retailer Cigars Direct. According to the trade press, he had no background in tobacco.

He named the company after his two sons, Alec and Bradley.

The early days were hard: the first brand, Bogie Stogies, cigars for golf courses, did not survive the end of the boom, and Rubin began producing brands for retailers. In 2000 the veteran Ralph Montero joined him; with Henke Kelner, master blender at Davidoff, they brought out Occidental Reserve, made in the Dominican Republic, followed by Trilogy (Cigars Direct).

The house owns no factory: it has its lines rolled under contract. Most are rolled at Raíces Cubanas, in Danlí, Honduras; a few at the Plasencia family''s in Nicaragua, and since 2019 lines such as Project 40 at J. Fuego, in Estelí (trade press, Wikipedia). None of the pages read dates a link with the Plasencia factories in Honduras.

The Prensado, presented at the IPCPR in 2009 in five formats, is box-pressed, a first for the house: Corojo wrapper grown in Trojes (Honduras), binder from Jalapa (Nicaragua), filler of Honduran and Nicaraguan tobaccos. Its Churchill was named the number one cigar of 2011 by the trade press, a turning point that the house itself highlights.

Next come Tempus (2007 or 2009 depending on the source), Black Market (2011), Coyol (2014), Magic Toast (2018) and Project 40 (2019). In 2018 Rubin''s sons launched their own brand, Alec & Bradley, from which Kintsugi comes according to Wikipedia. On 1 March 2023 Scandinavian Tobacco Group took over the Alec Bradley portfolio; Rubin remains an adviser and the house is now attached to Forged Cigar Co.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La decisión de Alan Rubin de dejar la venta de material médico, en 1996, para entrar en el puro tenía a la vez de pasión y de cálculo, en proporciones que nunca ha precisado. Fumador serio desde su veintena, se había forjado con los años una tesis sobre lo que faltaba en el mercado estadounidense: puros de verdadera exigencia, vendidos a un precio que permita fumar todos los días antes que racionar.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La decisión de Alan Rubin de dejar la venta de material médico, en 1996, para entrar en el puro tenía a la vez de pasión y de cálculo, en proporciones que nunca ha precisado. Fumador serio desde su veintena, se había forjado con los años una tesis sobre lo que faltaba en el mercado estadounidense: puros de verdadera exigencia, vendidos a un precio que permita fumar todos los días antes que racionar.', 'Alec Bradley nace en 1996, en Estados Unidos, de la decisión de Alan Rubin de lanzarse al puro tras la venta del negocio familiar de importación de ferretería, según el minorista Cigars Direct. Según la prensa del sector, no tenía ningún pasado en el tabaco.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Alan Rubins Entscheidung, 1996 den Vertrieb medizinischen Geräts zu verlassen und in die Zigarre zu gehen, hatte ebenso viel von Leidenschaft wie von Kalkül, in Anteilen, die er nie genannt hat. Seit seinen Zwanzigern ernsthafter Raucher, hatte er sich über die Jahre eine These darüber gebildet, was dem amerikanischen Markt fehlte: Zigarren von wirklichem Anspruch, zu einem Preis verkauft, der das tägliche Rauchen erlaubt, statt es zu rationieren.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Alan Rubins Entscheidung, 1996 den Vertrieb medizinischen Geräts zu verlassen und in die Zigarre zu gehen, hatte ebenso viel von Leidenschaft wie von Kalkül, in Anteilen, die er nie genannt hat. Seit seinen Zwanzigern ernsthafter Raucher, hatte er sich über die Jahre eine These darüber gebildet, was dem amerikanischen Markt fehlte: Zigarren von wirklichem Anspruch, zu einem Preis verkauft, der das tägliche Rauchen erlaubt, statt es zu rationieren.', 'Alec Bradley entsteht 1996 in den Vereinigten Staaten aus Alan Rubins Entscheidung, nach dem Verkauf des familiären Eisenwaren-Importgeschäfts ins Zigarrengeschäft einzusteigen, laut dem Einzelhändler Cigars Direct. Er hatte, nach Angaben der Fachpresse, keinerlei Tabakvergangenheit.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('1996年，艾伦·鲁宾决定离开医疗器械销售、转投雪茄，这个决定里既有热情也有算计，比例如何他从未说明。二十几岁起他就是认真的烟客，多年下来形成了一个关于美国市场缺什么的判断：真正讲究的雪茄，卖在一个让人可以天天抽、而不必省着抽的价位上。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '1996年，艾伦·鲁宾决定离开医疗器械销售、转投雪茄，这个决定里既有热情也有算计，比例如何他从未说明。二十几岁起他就是认真的烟客，多年下来形成了一个关于美国市场缺什么的判断：真正讲究的雪茄，卖在一个让人可以天天抽、而不必省着抽的价位上。', '艾伦·鲁宾决定在卖掉家族的五金进口生意之后投身雪茄，Alec Bradley 于1996年在美国诞生，这是雪茄零售商 Cigars Direct 的说法。据行业媒体，他此前与烟草毫无渊源。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('كان قرار آلان روبين، عام 1996، بترك بيع المعدّات الطبية والدخول إلى عالم السيجار مزيجًا من الشغف والحساب، بنِسَبٍ لم يوضّحها قط. فقد كان مدخّنًا جادًّا منذ العشرينيات من عمره، وكوّن على مرّ السنين أطروحة عمّا ينقص السوق الأمريكية: سيجار ذو تطلّب حقيقي، يُباع بسعر يتيح التدخين كل يوم بدل تقنينه.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'كان قرار آلان روبين، عام 1996، بترك بيع المعدّات الطبية والدخول إلى عالم السيجار مزيجًا من الشغف والحساب، بنِسَبٍ لم يوضّحها قط. فقد كان مدخّنًا جادًّا منذ العشرينيات من عمره، وكوّن على مرّ السنين أطروحة عمّا ينقص السوق الأمريكية: سيجار ذو تطلّب حقيقي، يُباع بسعر يتيح التدخين كل يوم بدل تقنينه.', 'وُلدت Alec Bradley عام 1996 في الولايات المتحدة من قرار آلان روبين دخول عالم السيجار بعد بيع شركة العائلة لاستيراد الخردوات، بحسب تاجر التجزئة Cigars Direct. ولم يكن له، بحسب صحافة المهنة، أي ماضٍ في التبغ.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Alec Bradley';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Il donna à l''entreprise le nom de ses deux fils, Alec et Bradley — et non le sien. Le geste posait d''emblée que l''affaire était personnelle autant que commerciale, et que sa réussite ou son échec se mesureraient autrement qu''en chiffre d''affaires trimestriel.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Il donna à l''entreprise le nom de ses deux fils, Alec et Bradley — et non le sien. Le geste posait d''emblée que l''affaire était personnelle autant que commerciale, et que sa réussite ou son échec se mesureraient autrement qu''en chiffre d''affaires trimestriel.', 'Il donne à l''entreprise le nom de ses deux fils, Alec et Bradley.'), `history`),
  `history_es` = IF(LOCATE(CAST('Dio a la empresa el nombre de sus dos hijos, Alec y Bradley —y no el suyo. El gesto planteaba de entrada que el asunto era personal tanto como comercial, y que su éxito o su fracaso se medirían de otro modo que en cifra de negocio trimestral.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Dio a la empresa el nombre de sus dos hijos, Alec y Bradley —y no el suyo. El gesto planteaba de entrada que el asunto era personal tanto como comercial, y que su éxito o su fracaso se medirían de otro modo que en cifra de negocio trimestral.', 'Da a la empresa el nombre de sus dos hijos, Alec y Bradley.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Er gab dem Unternehmen die Namen seiner beiden Söhne, Alec und Bradley — nicht seinen eigenen. Die Geste stellte von Anfang an klar, dass die Sache persönlich war und nicht nur kaufmännisch, und dass ihr Gelingen oder Scheitern anders zu messen sein würde als am Quartalsumsatz.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Er gab dem Unternehmen die Namen seiner beiden Söhne, Alec und Bradley — nicht seinen eigenen. Die Geste stellte von Anfang an klar, dass die Sache persönlich war und nicht nur kaufmännisch, und dass ihr Gelingen oder Scheitern anders zu messen sein würde als am Quartalsumsatz.', 'Er gibt dem Unternehmen die Namen seiner beiden Söhne, Alec und Bradley.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('他用两个儿子的名字——Alec 与 Bradley——给公司命名，而不是用自己的。这个举动一开始就摆明了：这件事既是生意，也是私事；它的成败，衡量的尺子不是季度营业额。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '他用两个儿子的名字——Alec 与 Bradley——给公司命名，而不是用自己的。这个举动一开始就摆明了：这件事既是生意，也是私事；它的成败，衡量的尺子不是季度营业额。', '他用两个儿子的名字——Alec 与 Bradley——为公司命名。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وأعطى الشركة اسمَي ابنيه، أليك وبرادلي — لا اسمه هو. وقد أعلن هذا التصرّف منذ البداية أن الأمر شخصي بقدر ما هو تجاري، وأن نجاحه أو إخفاقه سيُقاس بغير رقم الأعمال الفصلي.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وأعطى الشركة اسمَي ابنيه، أليك وبرادلي — لا اسمه هو. وقد أعلن هذا التصرّف منذ البداية أن الأمر شخصي بقدر ما هو تجاري، وأن نجاحه أو إخفاقه سيُقاس بغير رقم الأعمال الفصلي.', 'ويعطي الشركة اسمَي ابنيه Alec وBradley.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Alec Bradley';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Les premières années furent aussi difficiles que la suite le laisse deviner. Rubin parcourait les États-Unis d''un compte à l''autre, ouvrant le coffre de sa voiture pour montrer ses échantillons, bâtissant un réseau de distribution détaillant par détaillant, sans antécédents ni relations héritées.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Les premières années furent aussi difficiles que la suite le laisse deviner. Rubin parcourait les États-Unis d''un compte à l''autre, ouvrant le coffre de sa voiture pour montrer ses échantillons, bâtissant un réseau de distribution détaillant par détaillant, sans antécédents ni relations héritées.', 'Les débuts sont difficiles : la première marque, Bogie Stogies, des cigares pour les parcours de golf, ne survit pas à la fin du boom, et Rubin se met à produire des marques pour détaillants. En 2000, le vétéran Ralph Montero le rejoint ; avec Henke Kelner, maître assembleur de Davidoff, ils sortent Occidental Reserve, fabriqué en République dominicaine, puis Trilogy (Cigars Direct).'), `history`),
  `history_es` = IF(LOCATE(CAST('Los primeros años fueron tan difíciles como lo deja adivinar lo que siguió. Rubin recorría Estados Unidos de una cuenta a otra, abriendo el maletero de su coche para mostrar sus muestras, levantando una red de distribución minorista a minorista, sin antecedentes ni relaciones heredadas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Los primeros años fueron tan difíciles como lo deja adivinar lo que siguió. Rubin recorría Estados Unidos de una cuenta a otra, abriendo el maletero de su coche para mostrar sus muestras, levantando una red de distribución minorista a minorista, sin antecedentes ni relaciones heredadas.', 'Los comienzos son difíciles: la primera marca, Bogie Stogies, puros para campos de golf, no sobrevive al final del boom, y Rubin se pone a producir marcas para minoristas. En 2000 se une a él el veterano Ralph Montero; con Henke Kelner, maestro ligador de Davidoff, sacan Occidental Reserve, fabricado en la República Dominicana, y después Trilogy (Cigars Direct).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die ersten Jahre waren so schwer, wie das Folgende ahnen lässt. Rubin fuhr durch die Vereinigten Staaten von einem Kunden zum nächsten, öffnete den Kofferraum seines Wagens, um seine Muster zu zeigen, und baute ein Vertriebsnetz Händler für Händler auf, ohne Vorgeschichte und ohne ererbte Beziehungen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die ersten Jahre waren so schwer, wie das Folgende ahnen lässt. Rubin fuhr durch die Vereinigten Staaten von einem Kunden zum nächsten, öffnete den Kofferraum seines Wagens, um seine Muster zu zeigen, und baute ein Vertriebsnetz Händler für Händler auf, ohne Vorgeschichte und ohne ererbte Beziehungen.', 'Die Anfänge sind schwierig: Die erste Marke, Bogie Stogies, Zigarren für Golfplätze, übersteht das Ende des Booms nicht, und Rubin beginnt, Marken für Händler herzustellen. Im Jahr 2000 stößt der Veteran Ralph Montero zu ihm; mit Henke Kelner, Meistermischer bei Davidoff, bringen sie Occidental Reserve heraus, hergestellt in der Dominikanischen Republik, dann Trilogy (Cigars Direct).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('最初几年之难，从后来的事也猜得出来。鲁宾开车跑遍美国，一个客户接一个客户，掀开后备箱给人看样品，一家零售店一家零售店地搭起分销网络，既无履历，也无继承来的人脉。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '最初几年之难，从后来的事也猜得出来。鲁宾开车跑遍美国，一个客户接一个客户，掀开后备箱给人看样品，一家零售店一家零售店地搭起分销网络，既无履历，也无继承来的人脉。', '起步艰难：首个品牌 Bogie Stogies 是为高尔夫球场而做的雪茄，没能熬过热潮的结束，鲁宾转而为零售商生产品牌。2000年，老手 Ralph Montero 加入；他们与 Davidoff 的首席调配师 Henke Kelner 一起，推出了在多米尼加共和国制造的 Occidental Reserve，随后是 Trilogy（Cigars Direct）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('كانت السنوات الأولى عسيرة بقدر ما يوحي به ما تلاها. كان روبين يجوب الولايات المتحدة من زبون إلى زبون، يفتح صندوق سيارته ليعرض عيّناته، ويبني شبكة توزيع بائعًا بعد بائع، بلا سوابق ولا علاقات موروثة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'كانت السنوات الأولى عسيرة بقدر ما يوحي به ما تلاها. كان روبين يجوب الولايات المتحدة من زبون إلى زبون، يفتح صندوق سيارته ليعرض عيّناته، ويبني شبكة توزيع بائعًا بعد بائع، بلا سوابق ولا علاقات موروثة.', 'البدايات صعبة: فالعلامة الأولى، Bogie Stogies، وهي سيجار لملاعب الغولف، لا تنجو من نهاية الازدهار، ويبدأ روبين بإنتاج علامات لتجّار التجزئة. وفي عام 2000 ينضمّ إليه المحنّك Ralph Montero؛ ومع Henke Kelner، كبير خلّاطي Davidoff، يُصدران Occidental Reserve المصنوع في الجمهورية الدومينيكية، ثم Trilogy (Cigars Direct).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Alec Bradley';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le lien avec le Honduras, noué au début des années 2000 avec les manufactures de la famille Plasencia, donna à la maison la qualité de feuille et la précision de roulage que son ambition réclamait. Le Honduras était alors éclipsé commercialement par l''émergence du Nicaragua, mais les sols de la vallée de Jamastran, marqués par le corojo, et le savoir-faire des Plasencia sur plusieurs générations donnaient un tabac avec lequel un assembleur de goût pouvait travailler au plus haut niveau.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le lien avec le Honduras, noué au début des années 2000 avec les manufactures de la famille Plasencia, donna à la maison la qualité de feuille et la précision de roulage que son ambition réclamait. Le Honduras était alors éclipsé commercialement par l''émergence du Nicaragua, mais les sols de la vallée de Jamastran, marqués par le corojo, et le savoir-faire des Plasencia sur plusieurs générations donnaient un tabac avec lequel un assembleur de goût pouvait travailler au plus haut niveau.', 'La maison ne possède pas de fabrique : elle fait rouler ses lignes en sous-traitance. La plupart le sont à Raíces Cubanas, à Danlí, au Honduras ; quelques-unes chez la famille Plasencia au Nicaragua, et depuis 2019 des lignes comme Project 40 chez J. Fuego, à Estelí (presse du métier, Wikipédia). Aucune page lue ne date un lien avec les manufactures Plasencia au Honduras.'), `history`),
  `history_es` = IF(LOCATE(CAST('El vínculo con Honduras, anudado a principios de los años dos mil con las manufacturas de la familia Plasencia, dio a la casa la calidad de hoja y la precisión de liado que su ambición reclamaba. Honduras estaba entonces eclipsada comercialmente por la emergencia de Nicaragua, pero los suelos del valle de Jamastrán, marcados por el corojo, y el saber hacer de los Plasencia a lo largo de varias generaciones daban un tabaco con el que un ligador de gusto podía trabajar al más alto nivel.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El vínculo con Honduras, anudado a principios de los años dos mil con las manufacturas de la familia Plasencia, dio a la casa la calidad de hoja y la precisión de liado que su ambición reclamaba. Honduras estaba entonces eclipsada comercialmente por la emergencia de Nicaragua, pero los suelos del valle de Jamastrán, marcados por el corojo, y el saber hacer de los Plasencia a lo largo de varias generaciones daban un tabaco con el que un ligador de gusto podía trabajar al más alto nivel.', 'La casa no posee fábrica: hace liar sus líneas por subcontratación. La mayoría se lían en Raíces Cubanas, en Danlí, Honduras; algunas en casa de la familia Plasencia en Nicaragua, y desde 2019 líneas como Project 40 en J. Fuego, en Estelí (prensa del sector, Wikipedia). Ninguna página leída data un vínculo con las manufacturas Plasencia en Honduras.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Verbindung nach Honduras, Anfang der zweitausender Jahre mit den Manufakturen der Familie Plasencia geknüpft, gab dem Haus die Blattgüte und die Rollgenauigkeit, die sein Anspruch verlangte. Honduras stand damals kaufmännisch im Schatten des aufkommenden Nicaragua, doch die vom Corojo geprägten Böden des Tals von Jamastrán und das über mehrere Generationen gewachsene Können der Plasencias ergaben einen Tabak, mit dem ein geschmackssicherer Mischer auf höchstem Niveau arbeiten konnte.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Verbindung nach Honduras, Anfang der zweitausender Jahre mit den Manufakturen der Familie Plasencia geknüpft, gab dem Haus die Blattgüte und die Rollgenauigkeit, die sein Anspruch verlangte. Honduras stand damals kaufmännisch im Schatten des aufkommenden Nicaragua, doch die vom Corojo geprägten Böden des Tals von Jamastrán und das über mehrere Generationen gewachsene Können der Plasencias ergaben einen Tabak, mit dem ein geschmackssicherer Mischer auf höchstem Niveau arbeiten konnte.', 'Das Haus besitzt keine Fabrik: Es lässt seine Linien in Auftragsfertigung rollen. Die meisten entstehen bei Raíces Cubanas in Danlí, Honduras; einige bei der Familie Plasencia in Nicaragua, und seit 2019 Linien wie Project 40 bei J. Fuego in Estelí (Fachpresse, Wikipedia). Keine der gelesenen Seiten datiert eine Verbindung zu den Plasencia-Fabriken in Honduras.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('两千年代初与普拉森西亚家族在洪都拉斯的工厂建立的联系，给了这家字号其雄心所需要的叶子品质与卷制精度。当时的洪都拉斯在商业上被崛起的尼加拉瓜盖过了风头，但哈马斯特兰谷地那片带着科罗霍印记的土壤，加上普拉森西亚家几代人的手艺，长出的烟草足以让一个有品味的调配师在最高水准上工作。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '两千年代初与普拉森西亚家族在洪都拉斯的工厂建立的联系，给了这家字号其雄心所需要的叶子品质与卷制精度。当时的洪都拉斯在商业上被崛起的尼加拉瓜盖过了风头，但哈马斯特兰谷地那片带着科罗霍印记的土壤，加上普拉森西亚家几代人的手艺，长出的烟草足以让一个有品味的调配师在最高水准上工作。', '公司不拥有工厂：旗下系列都由外包卷制。多数在洪都拉斯丹利的 Raíces Cubanas 卷制；少数在尼加拉瓜的普拉森西亚家族处，自2019年起，Project 40 等系列在埃斯特利的 J. Fuego 卷制（行业媒体、维基百科）。所读各页均未给出与洪都拉斯普拉森西亚工厂之间联系的日期。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أما الصلة بهندوراس، المعقودة في مطلع الألفينات مع مصانع عائلة بلاسينسيا، فقد منحت الدار جودة الورقة ودقّة اللفّ اللتين كان طموحها يطلبهما. كانت هندوراس حينها في ظلّ صعود نيكاراغوا تجاريًّا، لكنّ تربة وادي خاماستران، المطبوعة بالكوروخو، وخبرة آل بلاسينسيا عبر أجيال، أعطتا تبغًا يستطيع خلّاط ذو ذوق أن يعمل به عند أعلى مستوى.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أما الصلة بهندوراس، المعقودة في مطلع الألفينات مع مصانع عائلة بلاسينسيا، فقد منحت الدار جودة الورقة ودقّة اللفّ اللتين كان طموحها يطلبهما. كانت هندوراس حينها في ظلّ صعود نيكاراغوا تجاريًّا، لكنّ تربة وادي خاماستران، المطبوعة بالكوروخو، وخبرة آل بلاسينسيا عبر أجيال، أعطتا تبغًا يستطيع خلّاط ذو ذوق أن يعمل به عند أعلى مستوى.', 'لا تملك الدار مصنعًا: فهي تُسند لفَّ خطوطها إلى جهات أخرى. ويُلفّ معظمها في Raíces Cubanas في دانلي بهندوراس؛ وبعضها لدى عائلة Plasencia في نيكاراغوا، ومنذ عام 2019 خطوط مثل Project 40 لدى J. Fuego في إستيلي (صحافة المهنة، ويكيبيديا). ولا تؤرّخ أي صفحة قُرئت صلةً بمصانع Plasencia في هندوراس.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Alec Bradley';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le Prensado, sorti en 2011, montra ce que cet investissement avait produit. Robusto pressé, cape corojo hondurienne cultivée par les Plasencia sur un assemblage guatémaltèque et hondurien, il fit connaître la maison bien au-delà du cercle des initiés — jusque-là, Alec Bradley restait un nom que peu de fumeurs auraient su placer. La liste d''attente se maintint plus de deux ans.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le Prensado, sorti en 2011, montra ce que cet investissement avait produit. Robusto pressé, cape corojo hondurienne cultivée par les Plasencia sur un assemblage guatémaltèque et hondurien, il fit connaître la maison bien au-delà du cercle des initiés — jusque-là, Alec Bradley restait un nom que peu de fumeurs auraient su placer. La liste d''attente se maintint plus de deux ans.', 'Le Prensado, présenté à l''IPCPR en 2009 en cinq formats, est pressé en boîte, une première pour la maison : cape Corojo cultivée à Trojes (Honduras), liant de Jalapa (Nicaragua), tripe de tabacs honduriens et nicaraguayens. Son Churchill est désigné cigare numéro un de 2011 par la presse du métier, un tournant que la maison met elle-même en avant.'), `history`),
  `history_es` = IF(LOCATE(CAST('El Prensado, salido en 2011, mostró lo que esa inversión había producido. Robusto prensado, capa corojo hondureña cultivada por los Plasencia sobre una ligada guatemalteca y hondureña, dio a conocer la casa mucho más allá del círculo de los iniciados —hasta entonces, Alec Bradley seguía siendo un nombre que pocos fumadores habrían sabido situar. La lista de espera se mantuvo más de dos años.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El Prensado, salido en 2011, mostró lo que esa inversión había producido. Robusto prensado, capa corojo hondureña cultivada por los Plasencia sobre una ligada guatemalteca y hondureña, dio a conocer la casa mucho más allá del círculo de los iniciados —hasta entonces, Alec Bradley seguía siendo un nombre que pocos fumadores habrían sabido situar. La lista de espera se mantuvo más de dos años.', 'El Prensado, presentado en el IPCPR en 2009 en cinco formatos, es prensado en caja, una primicia para la casa: capa Corojo cultivada en Trojes (Honduras), capote de Jalapa (Nicaragua), tripa de tabacos hondureños y nicaragüenses. Su Churchill es designado puro número uno de 2011 por la prensa del sector, un punto de inflexión que la propia casa destaca.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die 2011 erschienene Prensado zeigte, was diese Investition hervorgebracht hatte. Gepresster Robusto, honduranisches Corojo-Deckblatt von den Plasencias angebaut, auf einer guatemaltekischen und honduranischen Mischung — sie machte das Haus weit über den Kreis der Eingeweihten hinaus bekannt; bis dahin blieb Alec Bradley ein Name, den wenige Raucher einzuordnen gewusst hätten. Die Warteliste hielt sich über zwei Jahre.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die 2011 erschienene Prensado zeigte, was diese Investition hervorgebracht hatte. Gepresster Robusto, honduranisches Corojo-Deckblatt von den Plasencias angebaut, auf einer guatemaltekischen und honduranischen Mischung — sie machte das Haus weit über den Kreis der Eingeweihten hinaus bekannt; bis dahin blieb Alec Bradley ein Name, den wenige Raucher einzuordnen gewusst hätten. Die Warteliste hielt sich über zwei Jahre.', 'Die Prensado, 2009 auf der IPCPR in fünf Formaten vorgestellt, ist kastengepresst, eine Premiere für das Haus: Corojo-Deckblatt aus Trojes (Honduras), Umblatt aus Jalapa (Nicaragua), Einlage aus honduranischen und nicaraguanischen Tabaken. Ihre Churchill wird von der Fachpresse zur Zigarre Nummer eins des Jahres 2011 erklärt, ein Wendepunkt, den das Haus selbst hervorhebt.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('2011年推出的 Prensado，展示了这笔投入的成果。压制罗布图，普拉森西亚家种植的洪都拉斯科罗霍茄衣，覆在危地马拉与洪都拉斯的配方之上——它让这家字号的名字远远越出了内行的小圈子；在此之前，亚历克·布拉德利还是个多数烟客说不上来路的名字。等货名单维持了两年多。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '2011年推出的 Prensado，展示了这笔投入的成果。压制罗布图，普拉森西亚家种植的洪都拉斯科罗霍茄衣，覆在危地马拉与洪都拉斯的配方之上——它让这家字号的名字远远越出了内行的小圈子；在此之前，亚历克·布拉德利还是个多数烟客说不上来路的名字。等货名单维持了两年多。', 'Prensado 于2009年在 IPCPR 上以五种规格亮相，采用方压工艺，这在公司是头一回：茄衣为特罗赫斯（洪都拉斯）种植的科罗霍，茄套来自哈拉帕（尼加拉瓜），茄芯为洪都拉斯与尼加拉瓜烟叶。其 Churchill 规格被行业媒体评为2011年的头号雪茄，公司自己也格外强调这一转折点。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وأظهرت «برينسادو»، الصادرة عام 2011، ما أثمرته تلك الاستثمارات. روبوستو مضغوط، بغلاف كوروخو هندوراسي زرعه آل بلاسينسيا فوق خلطة غواتيمالية وهندوراسية، عرّف بالدار إلى ما هو أبعد بكثير من دائرة العارفين — إذ ظلّ اسم أليك برادلي حتى ذلك الحين اسمًا قلّ من يعرف أين يضعه من المدخّنين. وبقيت قائمة الانتظار قائمة أكثر من سنتين.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وأظهرت «برينسادو»، الصادرة عام 2011، ما أثمرته تلك الاستثمارات. روبوستو مضغوط، بغلاف كوروخو هندوراسي زرعه آل بلاسينسيا فوق خلطة غواتيمالية وهندوراسية، عرّف بالدار إلى ما هو أبعد بكثير من دائرة العارفين — إذ ظلّ اسم أليك برادلي حتى ذلك الحين اسمًا قلّ من يعرف أين يضعه من المدخّنين. وبقيت قائمة الانتظار قائمة أكثر من سنتين.', 'قُدّمت Prensado في IPCPR عام 2009 بخمسة قياسات، وهي مضغوطة على شكل علبة، وهذه سابقة للدار: غلاف Corojo مزروع في تروخيس (هندوراس)، ورابط من خالابا (نيكاراغوا)، وحشوة من تبوغ هندوراسية ونيكاراغوية. وتضع صحافة المهنة قياس Churchill منها في صدارة سيجارات عام 2011، وهو منعطف تبرزه الدار نفسها.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Alec Bradley';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La maison a continué depuis sans chercher l''effet : le Tempus, le Medalist, la série Black Market déclinent la même approche — des assemblages honduriens et guatémaltèques sérieux, roulés avec précision, vendus sans tapage.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La maison a continué depuis sans chercher l''effet : le Tempus, le Medalist, la série Black Market déclinent la même approche — des assemblages honduriens et guatémaltèques sérieux, roulés avec précision, vendus sans tapage.', 'Viennent ensuite Tempus (2007 ou 2009 selon les sources), Black Market (2011), Coyol (2014), Magic Toast (2018) et Project 40 (2019). En 2018, les fils de Rubin lancent leur propre marque, Alec & Bradley, d''où vient Kintsugi selon Wikipédia. Le 1er mars 2023, Scandinavian Tobacco Group reprend le portefeuille Alec Bradley ; Rubin reste conseiller et la maison est aujourd''hui rattachée à Forged Cigar Co.'), `history`),
  `history_es` = IF(LOCATE(CAST('La casa ha continuado desde entonces sin buscar el efecto: el Tempus, el Medalist, la serie Black Market declinan el mismo enfoque —ligadas hondureñas y guatemaltecas serias, liadas con precisión, vendidas sin estruendo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La casa ha continuado desde entonces sin buscar el efecto: el Tempus, el Medalist, la serie Black Market declinan el mismo enfoque —ligadas hondureñas y guatemaltecas serias, liadas con precisión, vendidas sin estruendo.', 'Vienen después Tempus (2007 o 2009 según las fuentes), Black Market (2011), Coyol (2014), Magic Toast (2018) y Project 40 (2019). En 2018, los hijos de Rubin lanzan su propia marca, Alec & Bradley, de la que viene Kintsugi según Wikipedia. El 1 de marzo de 2023, Scandinavian Tobacco Group se hace con la cartera de Alec Bradley; Rubin sigue como asesor y la casa está hoy vinculada a Forged Cigar Co.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das Haus hat seither weitergemacht, ohne den Effekt zu suchen: die Tempus, die Medalist, die Reihe Black Market wandeln denselben Ansatz ab — ernsthafte honduranische und guatemaltekische Mischungen, genau gerollt, ohne Lärm verkauft.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das Haus hat seither weitergemacht, ohne den Effekt zu suchen: die Tempus, die Medalist, die Reihe Black Market wandeln denselben Ansatz ab — ernsthafte honduranische und guatemaltekische Mischungen, genau gerollt, ohne Lärm verkauft.', 'Es folgen Tempus (2007 oder 2009, je nach Quelle), Black Market (2011), Coyol (2014), Magic Toast (2018) und Project 40 (2019). 2018 bringen Rubins Söhne ihre eigene Marke heraus, Alec & Bradley, von der Kintsugi laut Wikipedia stammt. Am 1. März 2023 übernimmt Scandinavian Tobacco Group das Portfolio von Alec Bradley; Rubin bleibt Berater, und das Haus gehört heute zu Forged Cigar Co.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('此后这家字号继续做事，不追求声势：Tempus、Medalist、Black Market 系列演绎的是同一套路数——认真的洪都拉斯与危地马拉配方，卷得精准，卖得安静。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '此后这家字号继续做事，不追求声势：Tempus、Medalist、Black Market 系列演绎的是同一套路数——认真的洪都拉斯与危地马拉配方，卷得精准，卖得安静。', '随后是 Tempus（依来源不同为2007年或2009年）、Black Market（2011年）、Coyol（2014年）、Magic Toast（2018年）和 Project 40（2019年）。2018年，鲁宾的儿子们推出了自己的品牌 Alec & Bradley，据维基百科，Kintsugi 即出自该品牌。2023年3月1日，Scandinavian Tobacco Group 接手 Alec Bradley 的产品组合；鲁宾继续担任顾问，公司如今隶属 Forged Cigar Co. 旗下。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('ومضت الدار منذ ذلك الحين من دون سعي إلى الإبهار: «تِمبوس» و«ميداليست» وسلسلة «بلاك ماركت» تصرّف المقاربة نفسها — خلطات هندوراسية وغواتيمالية جادّة، ملفوفة بدقّة، ومبيعة بلا ضجيج.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'ومضت الدار منذ ذلك الحين من دون سعي إلى الإبهار: «تِمبوس» و«ميداليست» وسلسلة «بلاك ماركت» تصرّف المقاربة نفسها — خلطات هندوراسية وغواتيمالية جادّة، ملفوفة بدقّة، ومبيعة بلا ضجيج.', 'ثم تأتي Tempus (2007 أو 2009 بحسب المصادر)، وBlack Market (2011)، وCoyol (2014)، وMagic Toast (2018)، وProject 40 (2019). وفي عام 2018 أطلق ابنا روبين علامتهما الخاصة Alec & Bradley، ومنها جاءت Kintsugi بحسب ويكيبيديا. وفي 1 مارس 2023 تولّت Scandinavian Tobacco Group حافظة Alec Bradley؛ ويبقى روبين مستشارًا، وترتبط الدار اليوم بـForged Cigar Co.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Alec Bradley';

UPDATE `brands` SET
  `limited_eds` = '["Black Market Filthy Hooligan","Thirty Years (30e anniversaire)"]',
  `founded` = '1996 — Floride (États-Unis)',
  `factory` = 'Raíces Cubanas à Danlí (Honduras) pour la plupart des lignes ; certaines lignes au Nicaragua (Plasencia, J. Fuego à Estelí)',
  `gamme` = '[{"name":"Prensado","color":"#8B2500","force":"Medium-Full","story":"Présenté en 2009 (presse du métier). Cape hondurienne, liant nicaraguayen, tripe honduro-nicaraguayenne, roulé à Raíces Cubanas, dit la maison (alecbradley.com, octobre 2026), qui l''annonce de corps moyen à plein. Formats du Robusto 5 x 50 au Double Toro 6 x 62, dont le Torpedo 6 1/8 x 52, pressés en boîte.","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"Honduras (Trojes)"},{"name":"Tempus","color":"#722F37","force":null,"story":"Ligne à cape hondurienne, née autour d''un criollo découvert par Rubin dans une petite ferme du Honduras en 2001, selon un détaillant ; son nom est le mot latin pour le temps. Lancement en 2007 (Cigars Direct, Wikipédia) ou 2009 (liste de produits de Wikipédia). Variantes Maduro et Nicaragua citées par la presse du métier en 2022.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Honduras"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","story":"Présenté à l''IPCPR 2011 (titre de presse vu). Cape nicaraguayenne, liant Sumatra, tripe panaméenne et hondurienne, dit la maison, qui parle d''un lot de tabac panaméen rare et de dix-huit assemblages testés. Filthy Hooligan en est l''édition de la Saint-Patrick, apparue en 2013 selon la presse.","vitolas":[],"wrapper":"Nicaragua"},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","story":"Sortie en 2018 selon la presse (octobre, après l''IPCPR). Cape hondurienne, liant et tripe nicaraguayens et honduriens, dit la maison, qui rattache le nom à une nuit de récolte et à un toast sous les étoiles ; la presse raconte plutôt Rubin et Montero trinquant au Glenfiddich dans une ferme du Honduras.","vitolas":[],"wrapper":"Honduras"},{"name":"Project 40","color":"#3E4A6B","force":"Medium","story":"Sortie mondiale en mai 2019. Cape nicaraguayenne, liant Habano brésilien, tripe nicaraguayenne, corps moyen, dit la maison. Le nom renvoie à l''idée qu''environ 40 % du bonheur dépend de nos choix, thèse reprise par la maison et la presse ; roulé à Estelí chez J. Fuego en 2019 selon la presse.","vitolas":[],"wrapper":"Nicaragua"},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","story":"Rattaché à Alec & Bradley, la marque lancée par les fils de Rubin, selon Wikipédia. Annoncé en mars 2020, retardé par la pandémie ; première livraison début décembre 2020 selon la presse du métier, juillet 2021 selon une autre (divergence). Cape hondurienne de Trojes, liant et tripe honduro-nicaraguayens, corps moyen, dit la maison.","vitolas":[],"wrapper":"Honduras (Trojes)"}]',
  `gamme_en` = '[{"name":"Prensado","color":"#8B2500","force":"Medium-Full","story":"Presented in 2009 (trade press). Honduran wrapper, Nicaraguan binder, Honduran-Nicaraguan filler, rolled at Raíces Cubanas, says the house (alecbradley.com, October 2026), which announces it as medium to full in body. Formats from the Robusto 5 x 50 to the Double Toro 6 x 62, including the Torpedo 6 1/8 x 52, box-pressed.","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"Honduras (Trojes)"},{"name":"Tempus","color":"#722F37","force":null,"story":"Line with a Honduran wrapper, built around a criollo that Rubin discovered on a small farm in Honduras in 2001, according to a retailer; its name is the Latin word for time. Launched in 2007 (Cigars Direct, Wikipedia) or 2009 (Wikipedia''s product list). Maduro and Nicaragua variants cited by the trade press in 2022.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Honduras"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","story":"Presented at the IPCPR 2011 (press headline seen). Nicaraguan wrapper, Sumatra binder, Panamanian and Honduran filler, says the house, which speaks of a lot of rare Panamanian tobacco and eighteen blends tested. Filthy Hooligan is its St. Patrick''s edition, which appeared in 2013 according to the press.","vitolas":[],"wrapper":"Nicaragua"},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","story":"Released in 2018 according to the press (October, after the IPCPR). Honduran wrapper, Nicaraguan and Honduran binder and filler, says the house, which ties the name to a harvest night and a toast under the stars; the press instead tells of Rubin and Montero clinking glasses over Glenfiddich on a farm in Honduras.","vitolas":[],"wrapper":"Honduras"},{"name":"Project 40","color":"#3E4A6B","force":"Medium","story":"Worldwide release in May 2019. Nicaraguan wrapper, Brazilian Habano binder, Nicaraguan filler, medium body, says the house. The name refers to the idea that about 40% of happiness depends on our choices, a thesis taken up by the house and the press; rolled in Estelí at J. Fuego in 2019 according to the press.","vitolas":[],"wrapper":"Nicaragua"},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","story":"Attached to Alec & Bradley, the brand launched by Rubin''s sons, according to Wikipedia. Announced in March 2020, delayed by the pandemic; first delivery in early December 2020 according to the trade press, July 2021 according to another (the sources diverge). Honduran wrapper from Trojes, Honduran-Nicaraguan binder and filler, medium body, says the house.","vitolas":[],"wrapper":"Honduras (Trojes)"}]',
  `gamme_es` = '[{"name":"Prensado","color":"#8B2500","force":"Medium-Full","story":"Presentado en 2009 (prensa del sector). Capa hondureña, capote nicaragüense, tripa hondureño-nicaragüense, liado en Raíces Cubanas, dice la casa (alecbradley.com, octubre de 2026), que lo anuncia de cuerpo medio a pleno. Formatos del Robusto 5 x 50 al Double Toro 6 x 62, entre ellos el Torpedo 6 1/8 x 52, prensados en caja.","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"Honduras (Trojes)"},{"name":"Tempus","color":"#722F37","force":null,"story":"Línea de capa hondureña, nacida en torno a un criollo que Rubin descubrió en una pequeña finca de Honduras en 2001, según un minorista; su nombre es la palabra latina para el tiempo. Lanzamiento en 2007 (Cigars Direct, Wikipedia) o 2009 (lista de productos de Wikipedia). Variantes Maduro y Nicaragua citadas por la prensa del sector en 2022.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Honduras"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","story":"Presentado en el IPCPR 2011 (titular de prensa visto). Capa nicaragüense, capote Sumatra, tripa panameña y hondureña, dice la casa, que habla de un lote de tabaco panameño raro y de dieciocho ligas probadas. Filthy Hooligan es su edición de San Patricio, aparecida en 2013 según la prensa.","vitolas":[],"wrapper":"Nicaragua"},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","story":"Salida en 2018 según la prensa (octubre, tras el IPCPR). Capa hondureña, capote y tripa nicaragüenses y hondureños, dice la casa, que vincula el nombre a una noche de cosecha y a un brindis bajo las estrellas; la prensa cuenta más bien a Rubin y Montero brindando con Glenfiddich en una finca de Honduras.","vitolas":[],"wrapper":"Honduras"},{"name":"Project 40","color":"#3E4A6B","force":"Medium","story":"Salida mundial en mayo de 2019. Capa nicaragüense, capote Habano brasileño, tripa nicaragüense, cuerpo medio, dice la casa. El nombre remite a la idea de que cerca del 40 % de la felicidad depende de nuestras decisiones, tesis recogida por la casa y la prensa; liado en Estelí en J. Fuego en 2019 según la prensa.","vitolas":[],"wrapper":"Nicaragua"},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","story":"Vinculado a Alec & Bradley, la marca lanzada por los hijos de Rubin, según Wikipedia. Anunciado en marzo de 2020, retrasado por la pandemia; primera entrega a principios de diciembre de 2020 según la prensa del sector, julio de 2021 según otra (divergencia). Capa hondureña de Trojes, capote y tripa hondureño-nicaragüenses, cuerpo medio, dice la casa.","vitolas":[],"wrapper":"Honduras (Trojes)"}]',
  `gamme_de` = '[{"name":"Prensado","color":"#8B2500","force":"Medium-Full","story":"2009 vorgestellt (Fachpresse). Deckblatt aus Honduras, Umblatt aus Nicaragua, Einlage aus Honduras und Nicaragua, bei Raíces Cubanas gerollt, sagt das Haus (alecbradley.com, Oktober 2026), das sie als Zigarre von mittlerem bis vollem Körper ankündigt. Formate vom Robusto 5 x 50 bis zum Double Toro 6 x 62, darunter der Torpedo 6 1/8 x 52, kastengepresst.","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"Honduras (Trojes)"},{"name":"Tempus","color":"#722F37","force":null,"story":"Linie mit honduranischem Deckblatt, entstanden rund um einen Criollo, den Rubin 2001 auf einer kleinen Farm in Honduras entdeckte, laut einem Händler; ihr Name ist das lateinische Wort für Zeit. Einführung 2007 (Cigars Direct, Wikipedia) oder 2009 (Produktliste von Wikipedia). Varianten Maduro und Nicaragua, 2022 von der Fachpresse genannt.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Honduras"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","story":"Auf der IPCPR 2011 vorgestellt (Pressetitel gesehen). Deckblatt aus Nicaragua, Umblatt Sumatra, Einlage aus Panama und Honduras, sagt das Haus, das von einer seltenen Partie panamaischen Tabaks und achtzehn getesteten Mischungen spricht. Filthy Hooligan ist die St.-Patrick''s-Edition, laut Presse 2013 erschienen.","vitolas":[],"wrapper":"Nicaragua"},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","story":"2018 erschienen laut Presse (Oktober, nach der IPCPR). Deckblatt aus Honduras, Umblatt und Einlage aus Nicaragua und Honduras, sagt das Haus, das den Namen mit einer Erntenacht und einem Trinkspruch unter den Sternen verbindet; die Presse erzählt eher, wie Rubin und Montero auf einer Farm in Honduras mit Glenfiddich anstoßen.","vitolas":[],"wrapper":"Honduras"},{"name":"Project 40","color":"#3E4A6B","force":"Medium","story":"Weltweite Markteinführung im Mai 2019. Deckblatt aus Nicaragua, Umblatt Habano aus Brasilien, Einlage aus Nicaragua, mittlerer Körper, sagt das Haus. Der Name verweist auf die Vorstellung, dass etwa 40 % des Glücks von unseren Entscheidungen abhängen, eine These, die das Haus und die Presse aufgreifen; laut Presse 2019 bei J. Fuego in Estelí gerollt.","vitolas":[],"wrapper":"Nicaragua"},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","story":"Mit Alec & Bradley verbunden, der von Rubins Söhnen gegründeten Marke, laut Wikipedia. Im März 2020 angekündigt, durch die Pandemie verzögert; erste Lieferung Anfang Dezember 2020 laut Fachpresse, Juli 2021 laut einer anderen (Abweichung). Deckblatt aus Trojes in Honduras, Umblatt und Einlage aus Honduras und Nicaragua, mittlerer Körper, sagt das Haus.","vitolas":[],"wrapper":"Honduras (Trojes)"}]',
  `gamme_zh` = '[{"name":"Prensado","color":"#8B2500","force":"Medium-Full","story":"2009年推出（行业媒体）。洪都拉斯茄衣，尼加拉瓜茄套，洪都拉斯与尼加拉瓜混合茄芯，在 Raíces Cubanas 卷制，公司如此表示（alecbradley.com，2026年10月），并称其为中等至浓郁的浓度。规格从 Robusto 5 x 50 到 Double Toro 6 x 62，其中包括 Torpedo 6 1/8 x 52，均为方压。","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"洪都拉斯（特罗赫斯）"},{"name":"Tempus","color":"#722F37","force":null,"story":"茄衣产自洪都拉斯的系列，据一家零售商称，围绕鲁宾2001年在洪都拉斯一座小农场发现的一种 criollo 而诞生；其名称是拉丁语中的“时间”一词。推出时间为2007年（Cigars Direct、维基百科）或2009年（维基百科的产品列表）。2022年行业媒体提到有 Maduro 与 Nicaragua 两种变体。","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"洪都拉斯"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","story":"2011年在 IPCPR 上亮相（见过一则媒体标题）。尼加拉瓜茄衣，Sumatra 茄套，巴拿马与洪都拉斯茄芯，公司如此表示，并提到一批稀有的巴拿马烟叶和试过的十八种配方。据媒体，Filthy Hooligan 是其圣帕特里克节版本，2013年出现。","vitolas":[],"wrapper":"尼加拉瓜"},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","story":"据媒体，2018年问世（10月，IPCPR 之后）。洪都拉斯茄衣，尼加拉瓜与洪都拉斯的茄套和茄芯，公司如此表示，并把名称与一个收获之夜和星空下的一次祝酒联系起来；媒体的说法则更像是鲁宾与 Montero 在洪都拉斯一座农场里用 Glenfiddich 碰杯。","vitolas":[],"wrapper":"洪都拉斯"},{"name":"Project 40","color":"#3E4A6B","force":"Medium","story":"2019年5月全球发行。尼加拉瓜茄衣，巴西 Habano 茄套，尼加拉瓜茄芯，中等浓度，公司如此表示。名称源自这样一种看法：大约40%的幸福取决于我们的选择，这一论点被公司和媒体沿用；据媒体，2019年在埃斯特利的 J. Fuego 卷制。","vitolas":[],"wrapper":"尼加拉瓜"},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","story":"据维基百科，隶属 Alec & Bradley，该品牌由鲁宾的儿子们创立。2020年3月宣布，因疫情推迟；据行业媒体，首批交货在2020年12月初，另一家媒体则称2021年7月（说法有分歧）。来自特罗赫斯的洪都拉斯茄衣，洪都拉斯与尼加拉瓜的茄套和茄芯，中等浓度，公司如此表示。","vitolas":[],"wrapper":"洪都拉斯（特罗赫斯）"}]',
  `gamme_ar` = '[{"name":"Prensado","color":"#8B2500","force":"Medium-Full","story":"قُدّمت عام 2009 (صحافة المهنة). غلاف هندوراسي، ورابط نيكاراغوي، وحشوة هندوراسية-نيكاراغوية، لُفّت في Raíces Cubanas، كما تقول الدار (alecbradley.com، أكتوبر 2026)، وهي تعلنها متوسطة إلى ممتلئة الجسم. القياسات من Robusto 5 x 50 إلى Double Toro 6 x 62، ومنها Torpedo 6 1/8 x 52، كلها مضغوطة في علبة.","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"هندوراس (تروخيس)"},{"name":"Tempus","color":"#722F37","force":null,"story":"خط بغلاف هندوراسي، وُلد حول تبغ criollo اكتشفه روبين في مزرعة صغيرة بهندوراس عام 2001، بحسب أحد تجّار التجزئة؛ واسمه الكلمة اللاتينية الدالة على الزمن. أُطلق عام 2007 (Cigars Direct، ويكيبيديا) أو 2009 (قائمة منتجات ويكيبيديا). ذكرت صحافة المهنة عام 2022 نسختين هما Maduro وNicaragua.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"هندوراس"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","story":"قُدّمت في IPCPR عام 2011 (عنوان صحفي اطّلعنا عليه). غلاف نيكاراغوي، ورابط Sumatra، وحشوة بنمية وهندوراسية، كما تقول الدار، التي تتحدث عن دفعة من تبغ بنمي نادر وثمانية عشر مزيجًا جُرّب. وFilthy Hooligan هو إصدارها لعيد القدّيس باتريك، ظهر عام 2013 بحسب الصحافة.","vitolas":[],"wrapper":"نيكاراغوا"},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","story":"صدرت عام 2018 بحسب الصحافة (في أكتوبر، بعد IPCPR). غلاف هندوراسي، ورابط وحشوة من نيكاراغوا وهندوراس، كما تقول الدار، التي تربط الاسم بليلة حصاد ونخبٍ تحت النجوم؛ أما الصحافة فتروي بالأحرى أن روبين وMontero تبادلا النخب بـGlenfiddich في مزرعة بهندوراس.","vitolas":[],"wrapper":"هندوراس"},{"name":"Project 40","color":"#3E4A6B","force":"Medium","story":"صدرت عالميًا في مايو 2019. غلاف نيكاراغوي، ورابط Habano برازيلي، وحشوة نيكاراغوية، متوسطة الجسم، كما تقول الدار. ويحيل الاسم إلى فكرة أن نحو 40 % من السعادة يتوقف على خياراتنا، وهي أطروحة تتبنّاها الدار والصحافة؛ ولُفّت في إستيلي لدى J. Fuego عام 2019 بحسب الصحافة.","vitolas":[],"wrapper":"نيكاراغوا"},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","story":"ترتبط بـAlec & Bradley، العلامة التي أطلقها ابنا روبين، بحسب ويكيبيديا. أُعلن عنها في مارس 2020 وتأخرت بسبب الجائحة؛ وكانت أول شحنة في مطلع ديسمبر 2020 بحسب صحافة المهنة، وفي يوليو 2021 بحسب صحيفة أخرى (تباين). غلاف هندوراسي من تروخيس، ورابط وحشوة من هندوراس ونيكاراغوا، متوسطة الجسم، كما تقول الدار.","vitolas":[],"wrapper":"هندوراس (تروخيس)"}]',
  `celebrities` = '[]',
  `celebrities_en` = '[]',
  `celebrities_es` = '[]',
  `celebrities_de` = '[]',
  `celebrities_zh` = '[]',
  `celebrities_ar` = '[]',
  `pairings` = '[{"type":"Bourbon et seigle","name":"Uncut Series","notes":"La maison propose, sur son site (octobre 2026), une série de cigares associés à des bourbons et seigles de fût unique."}]',
  `pairings_en` = '[{"type":"Bourbon and rye","name":"Uncut Series","notes":"The house offers, on its website (October 2026), a series of cigars paired with single-barrel bourbons and ryes."}]',
  `pairings_es` = '[{"type":"Bourbon y centeno","name":"Uncut Series","notes":"La casa ofrece, en su sitio web (octubre de 2026), una serie de puros asociados a bourbons y centenos de barril único."}]',
  `pairings_de` = '[{"type":"Bourbon und Roggen","name":"Uncut Series","notes":"Das Haus bietet auf seiner Website (Oktober 2026) eine Serie von Zigarren an, die mit Bourbons und Roggenwhiskeys aus Einzelfässern kombiniert sind."}]',
  `pairings_zh` = '[{"type":"波本与黑麦威士忌","name":"Uncut Series","notes":"公司在其网站上（2026年10月）提供一个系列的雪茄，搭配单桶波本与黑麦威士忌。"}]',
  `pairings_ar` = '[{"type":"البوربون والجاودار","name":"Uncut Series","notes":"تقدّم الدار على موقعها (أكتوبر 2026) سلسلة من السيجار مقرونة ببوربون وجاودار من برميل واحد."}]',
  `source` = IF(LOCATE(CAST('alecbradley.com et cigaraficionado.com (Alan Rubin, 1996, Fort Lauderdale ; Prensado, Cigare de l''Année 2011 ; production hondurienne et nicaraguayenne) ; alecbradley.com (Black Market, 2011 ; Magic Toast, 2019 ; Project 40, 2019 ; Kintsugi, 2021)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'alecbradley.com et cigaraficionado.com (Alan Rubin, 1996, Fort Lauderdale ; Prensado, Cigare de l''Année 2011 ; production hondurienne et nicaraguayenne) ; alecbradley.com (Black Market, 2011 ; Magic Toast, 2019 ; Project 40, 2019 ; Kintsugi, 2021)', 'alecbradley.com, pages Prensado, Black Market, Magic Toast, Project 40, Kintsugi et accueil (lues en octobre 2026 : blends, formats, Thirty Years, Uncut Series, Forged Cigar Co) ; cigarsdirect.com « TSB Alec Bradley Cigars: From The Import Biz to Great Cigars » (détaillant : quincaillerie, 1996, Bogie Stogies, Montero 2000, Tempus 2007, Prensado 2011) ; en.wikipedia.org « Alec Bradley » (noms des fils, Raíces Cubanas, J. Fuego 2019, Alec & Bradley 2018) ; cigaraficionado.com « Cigar Brand Highlight : Alec Bradley » (novembre 2022 : fabriques, lignes, Churchill numéro un de 2011) ; stogiepress.com « Scandinavian Tobacco Group (STG) Acquires Alec Bradley Cigar Company » (1er mars 2023) ; cigaraficionado.com « Alec Bradley''s New Wrapper » (août 2009, résumé de recherche : Prensado) ; cigar-coop.com (avril 2019, résumé de recherche : Project 40)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Alec Bradley';

-- ── CAO ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''histoire de CAO commence avec des pipes, pas des cigares. Cano Ozgener, émigré de Turquie à Nashville dans les années 1960, fonda son affaire en 1968 comme importateur spécialisé de bruyères turques et de pipes en écume de mer — des produits auxquels son origine lui donnait accès par des relations que ses concurrents américains ne pouvaient pas reproduire. Nashville était un lieu improbable pour un négoce de tabac haut de gamme, mais Ozgener avait compris que sa clientèle n''était pas géographique mais démographique : le collectionneur sérieux existe dans chaque ville américaine, et la vente par correspondance permettait de l''atteindre sans boutique.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''histoire de CAO commence avec des pipes, pas des cigares. Cano Ozgener, émigré de Turquie à Nashville dans les années 1960, fonda son affaire en 1968 comme importateur spécialisé de bruyères turques et de pipes en écume de mer — des produits auxquels son origine lui donnait accès par des relations que ses concurrents américains ne pouvaient pas reproduire. Nashville était un lieu improbable pour un négoce de tabac haut de gamme, mais Ozgener avait compris que sa clientèle n''était pas géographique mais démographique : le collectionneur sérieux existe dans chaque ville américaine, et la vente par correspondance permettait de l''atteindre sans boutique.', 'L''histoire de CAO commence avec des pipes, pas des cigares. Selon Cigar Dojo, Cano Aret Ozgener lança la maison à Nashville en 1968 et la nomma d''après ses initiales ; elle fabriquait d''abord des pipes et des humidors. La presse du métier précise qu''Ozgener, né à Istanbul en 1937, ingénieur, avait travaillé chez DuPont en Caroline du Nord, où il réparait des pipes turques en écume de mer défectueuses, et qu''il se consacra à plein temps à la pipe en 1977 : les deux pages ne donnent donc pas le même point de départ (1968 ou 1977).'), `history`),
  `history_en` = IF(LOCATE(CAST('The CAO story begins with pipes, not cigars. Cano Ozgener, who had emigrated from Turkey to Nashville in the 1960s, founded his business in 1968 as a specialist importer of Turkish briars and Meerschaum pipes — products that his cultural background gave him access to through relationships that American competitors could not replicate. Nashville was an unlikely location for a premium tobacco business, but Ozgener understood that his customer base was not geographic but demographic: the serious pipe collector existed in every American city, and direct mail could reach them without a street-level presence.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The CAO story begins with pipes, not cigars. Cano Ozgener, who had emigrated from Turkey to Nashville in the 1960s, founded his business in 1968 as a specialist importer of Turkish briars and Meerschaum pipes — products that his cultural background gave him access to through relationships that American competitors could not replicate. Nashville was an unlikely location for a premium tobacco business, but Ozgener understood that his customer base was not geographic but demographic: the serious pipe collector existed in every American city, and direct mail could reach them without a street-level presence.', 'The CAO story begins with pipes, not cigars. According to Cigar Dojo, Cano Aret Ozgener launched the house in Nashville in 1968 and named it after his initials; it first made pipes and humidors. The trade press adds that Ozgener, born in Istanbul in 1937, an engineer, had worked at DuPont in North Carolina, where he repaired defective Turkish meerschaum pipes, and that he went full time into pipes in 1977: the two pages therefore do not give the same starting point (1968 or 1977).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La historia de CAO empieza con pipas, no con puros. Cano Ozgener, emigrado de Turquía a Nashville en los años sesenta, fundó su negocio en 1968 como importador especializado de brezos turcos y de pipas de espuma de mar —productos a los que su origen le daba acceso por relaciones que sus competidores estadounidenses no podían reproducir. Nashville era un lugar improbable para un comercio de tabaco de gama alta, pero Ozgener había comprendido que su clientela no era geográfica sino demográfica: el coleccionista serio existe en cada ciudad estadounidense, y la venta por correspondencia permitía alcanzarlo sin tienda.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La historia de CAO empieza con pipas, no con puros. Cano Ozgener, emigrado de Turquía a Nashville en los años sesenta, fundó su negocio en 1968 como importador especializado de brezos turcos y de pipas de espuma de mar —productos a los que su origen le daba acceso por relaciones que sus competidores estadounidenses no podían reproducir. Nashville era un lugar improbable para un comercio de tabaco de gama alta, pero Ozgener había comprendido que su clientela no era geográfica sino demográfica: el coleccionista serio existe en cada ciudad estadounidense, y la venta por correspondencia permitía alcanzarlo sin tienda.', 'La historia de CAO empieza con pipas, no con puros. Según Cigar Dojo, Cano Aret Ozgener lanzó la casa en Nashville en 1968 y la nombró por sus iniciales; fabricaba al principio pipas y humidores. La prensa del sector precisa que Ozgener, nacido en Estambul en 1937, ingeniero, había trabajado en DuPont en Carolina del Norte, donde reparaba pipas turcas de espuma de mar defectuosas, y que se dedicó a tiempo completo a la pipa en 1977: las dos páginas no dan, pues, el mismo punto de partida (1968 o 1977).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Geschichte von CAO beginnt mit Pfeifen, nicht mit Zigarren. Cano Ozgener, in den sechziger Jahren aus der Türkei nach Nashville ausgewandert, gründete sein Geschäft 1968 als Facheinführer türkischer Bruyère- und Meerschaumpfeifen — Waren, zu denen ihm seine Herkunft über Beziehungen Zugang verschaffte, die seine amerikanischen Mitbewerber nicht nachbilden konnten. Nashville war ein unwahrscheinlicher Ort für einen gehobenen Tabakhandel, doch Ozgener hatte begriffen, dass seine Kundschaft nicht geografisch war, sondern demografisch: Den ernsthaften Sammler gibt es in jeder amerikanischen Stadt, und der Versandhandel erreichte ihn ohne Ladenlokal.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Geschichte von CAO beginnt mit Pfeifen, nicht mit Zigarren. Cano Ozgener, in den sechziger Jahren aus der Türkei nach Nashville ausgewandert, gründete sein Geschäft 1968 als Facheinführer türkischer Bruyère- und Meerschaumpfeifen — Waren, zu denen ihm seine Herkunft über Beziehungen Zugang verschaffte, die seine amerikanischen Mitbewerber nicht nachbilden konnten. Nashville war ein unwahrscheinlicher Ort für einen gehobenen Tabakhandel, doch Ozgener hatte begriffen, dass seine Kundschaft nicht geografisch war, sondern demografisch: Den ernsthaften Sammler gibt es in jeder amerikanischen Stadt, und der Versandhandel erreichte ihn ohne Ladenlokal.', 'Die Geschichte von CAO beginnt mit Pfeifen, nicht mit Zigarren. Laut Cigar Dojo gründete Cano Aret Ozgener das Haus 1968 in Nashville und benannte es nach seinen Initialen; zunächst stellte es Pfeifen und Humidore her. Die Fachpresse präzisiert, dass Ozgener, 1937 in Istanbul geboren, Ingenieur, bei DuPont in Nord-Carolina gearbeitet hatte, wo er fehlerhafte türkische Meerschaumpfeifen reparierte, und sich 1977 ganz der Pfeife widmete: Die beiden Seiten geben also nicht denselben Ausgangspunkt an (1968 oder 1977).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('CAO 的故事始于烟斗，而不是雪茄。卡诺·奥兹格纳在六十年代从土耳其移居纳什维尔，1968年创办了自己的生意，专做土耳其石楠木烟斗与海泡石烟斗的进口——凭他的出身，他能通过美国同行无法复制的人脉拿到这些货。纳什维尔并不像一个高端烟草生意该在的地方，但奥兹格纳想明白了：他的客群不是地理意义上的，而是人口意义上的——认真的收藏者在每一座美国城市都有，而邮购让他不必开店就能触及他们。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'CAO 的故事始于烟斗，而不是雪茄。卡诺·奥兹格纳在六十年代从土耳其移居纳什维尔，1968年创办了自己的生意，专做土耳其石楠木烟斗与海泡石烟斗的进口——凭他的出身，他能通过美国同行无法复制的人脉拿到这些货。纳什维尔并不像一个高端烟草生意该在的地方，但奥兹格纳想明白了：他的客群不是地理意义上的，而是人口意义上的——认真的收藏者在每一座美国城市都有，而邮购让他不必开店就能触及他们。', 'CAO 的故事始于烟斗，而不是雪茄。据 Cigar Dojo，卡诺·阿雷特·奥兹格纳于1968年在纳什维尔创办了这家公司，并以自己姓名的首字母命名；它起初制作烟斗和雪茄保湿盒。行业媒体补充说，奥兹格纳1937年生于伊斯坦布尔，是工程师，曾在北卡罗来纳州的 DuPont 工作，在那里修理有缺陷的土耳其海泡石烟斗，并于1977年全职投入烟斗：因此两个页面给出的起点并不相同（1968年或1977年）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تبدأ قصة CAO بالغلايين لا بالسيجار. فقد هاجر كانو أوزغنر من تركيا إلى ناشفيل في الستينيات، وأسّس عمله عام 1968 مستوردًا متخصّصًا في غلايين الخلنج التركي وغلايين زبد البحر — بضائع أتاحت له أصولُه الوصول إليها عبر علاقات لم يستطع منافسوه الأمريكيون استنساخها. لم تكن ناشفيل مكانًا مرجَّحًا لتجارة تبغ راقية، لكنّ أوزغنر كان قد فهم أن زبائنه ليسوا جغرافيا بل ديموغرافيا: فالجامع الجادّ موجود في كل مدينة أمريكية، والبيع بالبريد يتيح بلوغه بلا متجر.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تبدأ قصة CAO بالغلايين لا بالسيجار. فقد هاجر كانو أوزغنر من تركيا إلى ناشفيل في الستينيات، وأسّس عمله عام 1968 مستوردًا متخصّصًا في غلايين الخلنج التركي وغلايين زبد البحر — بضائع أتاحت له أصولُه الوصول إليها عبر علاقات لم يستطع منافسوه الأمريكيون استنساخها. لم تكن ناشفيل مكانًا مرجَّحًا لتجارة تبغ راقية، لكنّ أوزغنر كان قد فهم أن زبائنه ليسوا جغرافيا بل ديموغرافيا: فالجامع الجادّ موجود في كل مدينة أمريكية، والبيع بالبريد يتيح بلوغه بلا متجر.', 'تبدأ قصة CAO بالغلايين لا بالسيجار. وبحسب Cigar Dojo أطلق كانو آريت أوزغنر الدار في ناشفيل عام 1968 وسمّاها على أحرف اسمه الأولى؛ وكانت تصنع في البداية الغلايين وحافظات الرطوبة. وتوضّح صحافة المهنة أن أوزغنر، المولود في إسطنبول عام 1937، مهندس، كان قد عمل في DuPont بولاية كارولاينا الشمالية، حيث كان يصلح غلايين زبد البحر التركية المعيبة، وأنه تفرّغ للغليون عام 1977: فالصفحتان لا تعطيان إذن نقطة الانطلاق نفسها (1968 أو 1977).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le passage au cigare, dans les années 1990, fut à la fois opportuniste et réfléchi. L''engouement américain de cette décennie créait une demande que les manufactures établies peinaient à satisfaire, et Ozgener reconnut dans la culture du cigare le même goût de connaisseur qu''il servait depuis vingt ans sur le marché de la pipe. Le client qui avait passé des années à former son goût en bruyère était exactement celui qui apprécierait des cigares sérieux — et Ozgener avait vingt ans de relation avec lui.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le passage au cigare, dans les années 1990, fut à la fois opportuniste et réfléchi. L''engouement américain de cette décennie créait une demande que les manufactures établies peinaient à satisfaire, et Ozgener reconnut dans la culture du cigare le même goût de connaisseur qu''il servait depuis vingt ans sur le marché de la pipe. Le client qui avait passé des années à former son goût en bruyère était exactement celui qui apprécierait des cigares sérieux — et Ozgener avait vingt ans de relation avec lui.', 'Le cigare vient plus tard. Cigar Dojo écrit que la maison tenta le cigare premium en 1980, puis y revint au milieu des années 1990 ; la presse du métier date l''entrée d''Ozgener sur le marché du cigare de 1993 et le premier CAO, roulé au Honduras, de 1995. Au début des années 2000, la marque s''était fait connaître par des mélanges audacieux et contemporains.'), `history`),
  `history_en` = IF(LOCATE(CAST('The transition to cigars in the 1990s was both opportunistic and philosophically motivated. The American cigar boom of that decade was creating demand that the established manufacturers were struggling to meet, and Ozgener recognized in cigar culture the same connoisseurship that he had spent twenty years serving in the pipe market. The customer who had spent years developing their taste in briars was exactly the customer who would appreciate serious cigars, and Ozgener had twenty years of relationship with them.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The transition to cigars in the 1990s was both opportunistic and philosophically motivated. The American cigar boom of that decade was creating demand that the established manufacturers were struggling to meet, and Ozgener recognized in cigar culture the same connoisseurship that he had spent twenty years serving in the pipe market. The customer who had spent years developing their taste in briars was exactly the customer who would appreciate serious cigars, and Ozgener had twenty years of relationship with them.', 'The cigar comes later. Cigar Dojo writes that the house tried the premium cigar in 1980, then returned to it in the mid-1990s; the trade press dates Ozgener''s entry into the cigar market to 1993 and the first CAO, rolled in Honduras, to 1995. By the early 2000s, the brand had made a name for itself with bold, contemporary blends.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El paso al puro, en los años noventa, fue a la vez oportunista y meditado. El entusiasmo estadounidense de esa década creaba una demanda que las manufacturas establecidas apenas satisfacían, y Ozgener reconoció en la cultura del puro el mismo gusto de conocedor que servía desde hacía veinte años en el mercado de la pipa. El cliente que había pasado años formando su gusto en brezo era exactamente el que apreciaría puros serios —y Ozgener llevaba veinte años de relación con él.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El paso al puro, en los años noventa, fue a la vez oportunista y meditado. El entusiasmo estadounidense de esa década creaba una demanda que las manufacturas establecidas apenas satisfacían, y Ozgener reconoció en la cultura del puro el mismo gusto de conocedor que servía desde hacía veinte años en el mercado de la pipa. El cliente que había pasado años formando su gusto en brezo era exactamente el que apreciaría puros serios —y Ozgener llevaba veinte años de relación con él.', 'El puro llega más tarde. Cigar Dojo escribe que la casa probó el puro premium en 1980 y volvió a él a mediados de los años noventa; la prensa del sector fecha la entrada de Ozgener en el mercado del puro en 1993 y el primer CAO, liado en Honduras, en 1995. A principios de los años dos mil, la marca se había dado a conocer por mezclas audaces y contemporáneas.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der Übergang zur Zigarre in den neunziger Jahren war zugleich Gelegenheit und Überlegung. Die amerikanische Begeisterung jenes Jahrzehnts schuf eine Nachfrage, der die eingeführten Manufakturen kaum nachkamen, und Ozgener erkannte in der Zigarrenkultur denselben Kennergeschmack, den er seit zwanzig Jahren im Pfeifenmarkt bediente. Der Kunde, der Jahre darauf verwandt hatte, seinen Geschmack am Bruyère zu bilden, war genau jener, der ernsthafte Zigarren schätzen würde — und Ozgener hatte zwanzig Jahre Beziehung zu ihm.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der Übergang zur Zigarre in den neunziger Jahren war zugleich Gelegenheit und Überlegung. Die amerikanische Begeisterung jenes Jahrzehnts schuf eine Nachfrage, der die eingeführten Manufakturen kaum nachkamen, und Ozgener erkannte in der Zigarrenkultur denselben Kennergeschmack, den er seit zwanzig Jahren im Pfeifenmarkt bediente. Der Kunde, der Jahre darauf verwandt hatte, seinen Geschmack am Bruyère zu bilden, war genau jener, der ernsthafte Zigarren schätzen würde — und Ozgener hatte zwanzig Jahre Beziehung zu ihm.', 'Die Zigarre kommt später. Cigar Dojo schreibt, das Haus habe es 1980 mit der Premiumzigarre versucht und sei Mitte der neunziger Jahre darauf zurückgekommen; die Fachpresse datiert Ozgeners Einstieg in den Zigarrenmarkt auf 1993 und die erste CAO, in Honduras gerollt, auf 1995. Anfang der zweitausender Jahre hatte sich die Marke durch kühne, zeitgemäße Mischungen einen Namen gemacht.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('九十年代转向雪茄，既是抓住时机，也是深思之后的选择。那十年的美国热潮造出了成熟工厂难以满足的需求，而奥兹格纳在雪茄文化里认出了他二十年来在烟斗市场服务的同一种行家口味。那位花了多年在石楠木上养成品味的客人，恰恰就是会欣赏认真雪茄的人——而奥兹格纳与他已有二十年的交情。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '九十年代转向雪茄，既是抓住时机，也是深思之后的选择。那十年的美国热潮造出了成熟工厂难以满足的需求，而奥兹格纳在雪茄文化里认出了他二十年来在烟斗市场服务的同一种行家口味。那位花了多年在石楠木上养成品味的客人，恰恰就是会欣赏认真雪茄的人——而奥兹格纳与他已有二十年的交情。', '雪茄是后来的事。据 Cigar Dojo，公司在1980年尝试过高端雪茄，之后在1990年代中期重新回到雪茄；行业媒体则把奥兹格纳进入雪茄市场的时间定在1993年，把在洪都拉斯卷制的首支 CAO 定在1995年。到2000年代初，这个品牌已凭大胆而当代的配方为人所知。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وكان الانتقال إلى السيجار، في التسعينيات، اغتنامًا للفرصة وتفكيرًا في آن. فحماسة ذلك العقد الأمريكية خلقت طلبًا كادت المصانع الراسخة لا تلبّيه، ورأى أوزغنر في ثقافة السيجار ذوق العارفين نفسه الذي كان يخدمه منذ عشرين عامًا في سوق الغليون. فالزبون الذي أمضى سنوات يبني ذائقته على الخلنج هو بالضبط من سيقدّر سيجارًا جادًّا — وكانت تربط أوزغنر به عشرون سنة من العلاقة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وكان الانتقال إلى السيجار، في التسعينيات، اغتنامًا للفرصة وتفكيرًا في آن. فحماسة ذلك العقد الأمريكية خلقت طلبًا كادت المصانع الراسخة لا تلبّيه، ورأى أوزغنر في ثقافة السيجار ذوق العارفين نفسه الذي كان يخدمه منذ عشرين عامًا في سوق الغليون. فالزبون الذي أمضى سنوات يبني ذائقته على الخلنج هو بالضبط من سيقدّر سيجارًا جادًّا — وكانت تربط أوزغنر به عشرون سنة من العلاقة.', 'ويأتي السيجار لاحقًا. تكتب Cigar Dojo أن الدار جرّبت السيجار الفاخر عام 1980، ثم عادت إليه في منتصف التسعينيات؛ وتؤرّخ صحافة المهنة دخول أوزغنر سوق السيجار بعام 1993، وأول CAO، الملفوف في هندوراس، بعام 1995. ومع مطلع الألفينات كانت العلامة قد عُرفت بخلطات جريئة ومعاصرة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''identité de CAO fut d''emblée différente de celle des maisons établies. Là où Arturo Fuente parle d''héritage et de continuité familiale, et Davidoff de précision suisse et d''ascendance cubaine, CAO parle d''innovation et de référence culturelle. La gamme Flathead, nommée d''après l''esthétique des moteurs V-twin Harley-Davidson d''époque et dessinée autour d''elle, en fut la déclaration la plus explicite : un cigare premium qui s''adressait directement au monde de l''amateur américain, au lieu de traduire en tabac les conventions du luxe européen. L''assemblage nicaraguayen et hondurien à l''intérieur, lui, était sérieux.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''identité de CAO fut d''emblée différente de celle des maisons établies. Là où Arturo Fuente parle d''héritage et de continuité familiale, et Davidoff de précision suisse et d''ascendance cubaine, CAO parle d''innovation et de référence culturelle. La gamme Flathead, nommée d''après l''esthétique des moteurs V-twin Harley-Davidson d''époque et dessinée autour d''elle, en fut la déclaration la plus explicite : un cigare premium qui s''adressait directement au monde de l''amateur américain, au lieu de traduire en tabac les conventions du luxe européen. L''assemblage nicaraguayen et hondurien à l''intérieur, lui, était sérieux.', 'CAO a cultivé un registre à part, tourné vers l''imagerie américaine. La gamme Flathead, lancée en 2013 selon Cigar Dojo, puise dans l''univers des hot rods, des pin-up et des motos custom ; ses formats portent des noms de pièces de moteur (Carb, Camshaft, Piston, Big Block). La page de la maison, en octobre 2026, la décrit bâtie sur une cape Connecticut Broadleaf, sans citer de marque de moto.'), `history`),
  `history_en` = IF(LOCATE(CAST('CAO''s early cigar identity was deliberately different from the established houses. Where Arturo Fuente communicated heritage and family continuity, and Davidoff communicated Swiss precision and Cuban ancestry, CAO communicated innovation and cultural reference. The Flathead range, named for and designed around the aesthetic of vintage Harley-Davidson V-twin engines, was the most explicit statement of this identity: a premium cigar that addressed the American enthusiast''s world directly rather than translating European luxury conventions into tobacco form. The Nicaraguan-Honduran blend inside was serious. The packaging and marketing spoke a language the established Havana-influenced houses would not have recognized.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'CAO''s early cigar identity was deliberately different from the established houses. Where Arturo Fuente communicated heritage and family continuity, and Davidoff communicated Swiss precision and Cuban ancestry, CAO communicated innovation and cultural reference. The Flathead range, named for and designed around the aesthetic of vintage Harley-Davidson V-twin engines, was the most explicit statement of this identity: a premium cigar that addressed the American enthusiast''s world directly rather than translating European luxury conventions into tobacco form. The Nicaraguan-Honduran blend inside was serious. The packaging and marketing spoke a language the established Havana-influenced houses would not have recognized.', 'CAO cultivated a register of its own, turned towards American imagery. The Flathead range, launched in 2013 according to Cigar Dojo, draws on the world of hot rods, pin-ups and custom motorcycles; its formats bear the names of engine parts (Carb, Camshaft, Piston, Big Block). The house''s page, in October 2026, describes it as built on a Connecticut Broadleaf wrapper, without citing any motorcycle make.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La identidad de CAO fue desde el principio distinta de la de las casas establecidas. Allí donde Arturo Fuente habla de herencia y de continuidad familiar, y Davidoff de precisión suiza y de ascendencia cubana, CAO habla de innovación y de referencia cultural. La gama Flathead, nombrada según la estética de los motores V-twin Harley-Davidson de época y dibujada en torno a ella, fue su declaración más explícita: un puro premium que se dirigía directamente al mundo del aficionado estadounidense, en lugar de traducir en tabaco las convenciones del lujo europeo. La ligada nicaragüense y hondureña del interior, en cambio, era seria.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La identidad de CAO fue desde el principio distinta de la de las casas establecidas. Allí donde Arturo Fuente habla de herencia y de continuidad familiar, y Davidoff de precisión suiza y de ascendencia cubana, CAO habla de innovación y de referencia cultural. La gama Flathead, nombrada según la estética de los motores V-twin Harley-Davidson de época y dibujada en torno a ella, fue su declaración más explícita: un puro premium que se dirigía directamente al mundo del aficionado estadounidense, en lugar de traducir en tabaco las convenciones del lujo europeo. La ligada nicaragüense y hondureña del interior, en cambio, era seria.', 'CAO ha cultivado un registro aparte, orientado a la imaginería estadounidense. La gama Flathead, lanzada en 2013 según Cigar Dojo, bebe del universo de los hot rods, las pin-up y las motos custom; sus formatos llevan nombres de piezas de motor (Carb, Camshaft, Piston, Big Block). La página de la casa, en octubre de 2026, la describe construida sobre una capa Connecticut Broadleaf, sin citar ninguna marca de moto.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Identität von CAO war von Anfang an eine andere als die der eingeführten Häuser. Wo Arturo Fuente von Erbe und familiärer Fortdauer spricht und Davidoff von Schweizer Genauigkeit und kubanischer Abstammung, spricht CAO von Neuerung und kultureller Anspielung. Die Linie Flathead, nach der Ästhetik der alten V-Twin-Motoren von Harley-Davidson benannt und um sie herum gezeichnet, war die ausdrücklichste Ansage: eine Premiumzigarre, die sich unmittelbar an die Welt des amerikanischen Liebhabers richtete, statt die Konventionen europäischen Luxus in Tabak zu übersetzen. Die nicaraguanische und honduranische Mischung im Inneren war dagegen ernst gemeint.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Identität von CAO war von Anfang an eine andere als die der eingeführten Häuser. Wo Arturo Fuente von Erbe und familiärer Fortdauer spricht und Davidoff von Schweizer Genauigkeit und kubanischer Abstammung, spricht CAO von Neuerung und kultureller Anspielung. Die Linie Flathead, nach der Ästhetik der alten V-Twin-Motoren von Harley-Davidson benannt und um sie herum gezeichnet, war die ausdrücklichste Ansage: eine Premiumzigarre, die sich unmittelbar an die Welt des amerikanischen Liebhabers richtete, statt die Konventionen europäischen Luxus in Tabak zu übersetzen. Die nicaraguanische und honduranische Mischung im Inneren war dagegen ernst gemeint.', 'CAO hat ein eigenes Register gepflegt, das sich der amerikanischen Bildwelt zuwendet. Die Linie Flathead, laut Cigar Dojo 2013 eingeführt, schöpft aus der Welt der Hot Rods, der Pin-ups und der Custom-Motorräder; ihre Formate tragen die Namen von Motorteilen (Carb, Camshaft, Piston, Big Block). Die Seite des Hauses beschreibt sie im Oktober 2026 als auf einem Deckblatt Connecticut Broadleaf aufgebaut, ohne eine Motorradmarke zu nennen.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('CAO 的气质从一开始就与老字号不同。阿图罗·富恩特讲的是传承与家族的延续，大卫杜夫讲的是瑞士式的精确与古巴血统，CAO 讲的则是创新与文化引用。Flathead 系列以哈雷戴维森老式 V-twin 发动机的美学命名并据此设计，是这一姿态最直白的宣示：一支直接对着美国爱好者的世界说话的高端雪茄，而不是把欧洲奢侈品的成规翻译成烟草。至于里面的尼加拉瓜与洪都拉斯配方，则是认真的。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'CAO 的气质从一开始就与老字号不同。阿图罗·富恩特讲的是传承与家族的延续，大卫杜夫讲的是瑞士式的精确与古巴血统，CAO 讲的则是创新与文化引用。Flathead 系列以哈雷戴维森老式 V-twin 发动机的美学命名并据此设计，是这一姿态最直白的宣示：一支直接对着美国爱好者的世界说话的高端雪茄，而不是把欧洲奢侈品的成规翻译成烟草。至于里面的尼加拉瓜与洪都拉斯配方，则是认真的。', 'CAO 经营着一条独立的路线，朝向美国意象。据 Cigar Dojo，Flathead 系列于2013年推出，取材于改装老爷车（hot rod）、海报女郎（pin-up）和定制摩托的世界；其规格以发动机零件命名（Carb、Camshaft、Piston、Big Block）。公司页面在2026年10月称其以 Connecticut Broadleaf 茄衣为基础，未提及任何摩托车品牌。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وكانت هوية CAO منذ البداية مختلفة عن هوية الدور الراسخة. فحيث تتحدّث أرتورو فوينتي عن الإرث واستمرار العائلة، ودافيدوف عن الدقّة السويسرية والنسب الكوبي، تتحدّث CAO عن الابتكار والإحالة الثقافية. وكانت تشكيلة «فلاتهيد»، المسمّاة على جماليات محرّكات هارلي ديفيدسون ثنائية الأسطوانة القديمة والمرسومة حولها، أوضح إعلان عن ذلك: سيجار فاخر يخاطب عالم الهاوي الأمريكي مباشرة، بدل أن يترجم أعراف الترف الأوروبي إلى تبغ. أما الخلطة النيكاراغوية والهندوراسية في الداخل فكانت جادّة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وكانت هوية CAO منذ البداية مختلفة عن هوية الدور الراسخة. فحيث تتحدّث أرتورو فوينتي عن الإرث واستمرار العائلة، ودافيدوف عن الدقّة السويسرية والنسب الكوبي، تتحدّث CAO عن الابتكار والإحالة الثقافية. وكانت تشكيلة «فلاتهيد»، المسمّاة على جماليات محرّكات هارلي ديفيدسون ثنائية الأسطوانة القديمة والمرسومة حولها، أوضح إعلان عن ذلك: سيجار فاخر يخاطب عالم الهاوي الأمريكي مباشرة، بدل أن يترجم أعراف الترف الأوروبي إلى تبغ. أما الخلطة النيكاراغوية والهندوراسية في الداخل فكانت جادّة.', 'نمّت CAO نمطًا خاصًا بها، متجهًا إلى الصور الأمريكية. وتستمد تشكيلة Flathead، التي أُطلقت عام 2013 بحسب Cigar Dojo، من عالم السيارات المعدَّلة (hot rods) والـpin-up والدراجات النارية المصمَّمة حسب الطلب؛ وتحمل قياساتها أسماء قطع المحرّك (Carb وCamshaft وPiston وBig Block). وتصفها صفحة الدار، في أكتوبر 2026، بأنها مبنية على غلاف Connecticut Broadleaf، من دون أن تذكر ماركة دراجة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('General Cigar racheta CAO en 2007, faisant entrer ce caractère inventif dans un portefeuille auquel la solidité commerciale de Macanudo ne pouvait pas l''apporter. L''acquisition a préservé le rôle de CAO comme marque qui prend les risques du groupe : celle dont les amateurs suivent le calendrier de sorties pour la nouveauté, quand ils comptent sur Macanudo pour la régularité.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'General Cigar racheta CAO en 2007, faisant entrer ce caractère inventif dans un portefeuille auquel la solidité commerciale de Macanudo ne pouvait pas l''apporter. L''acquisition a préservé le rôle de CAO comme marque qui prend les risques du groupe : celle dont les amateurs suivent le calendrier de sorties pour la nouveauté, quand ils comptent sur Macanudo pour la régularité.', 'En 2007, CAO fut rachetée par Henri Wintermans, division de ST Tobacco, selon la presse du métier ; Cigar Dojo nomme l''actuel Scandinavian Tobacco Group. La marque quitta Nashville pour le siège de General Cigar à Richmond, en Virginie. Tim Ozgener, fils du fondateur, resta président jusqu''en 2010 ; Cano Ozgener est mort le 9 juin 2018 à Nashville, à 81 ans. En octobre 2026, le site caocigars.com porte la mention General Cigar Co., Inc. ; selon les lignes, les cigares sont roulés à Estelí (Nicaragua), au Honduras ou chez General Cigar Dominicana (République dominicaine).'), `history`),
  `history_en` = IF(LOCATE(CAST('General Cigar acquired CAO in 2007, bringing the brand''s innovative character into a portfolio that needed what Macanudo''s reliable commercial dominance could not provide. The acquisition has maintained CAO''s identity as the group''s risk-taking brand — the release schedule that enthusiasts follow for novelty while they rely on Macanudo for consistency.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'General Cigar acquired CAO in 2007, bringing the brand''s innovative character into a portfolio that needed what Macanudo''s reliable commercial dominance could not provide. The acquisition has maintained CAO''s identity as the group''s risk-taking brand — the release schedule that enthusiasts follow for novelty while they rely on Macanudo for consistency.', 'In 2007, CAO was bought by Henri Wintermans, a division of ST Tobacco, according to the trade press; Cigar Dojo names today''s Scandinavian Tobacco Group. The brand left Nashville for General Cigar''s headquarters in Richmond, Virginia. Tim Ozgener, the founder''s son, remained president until 2010; Cano Ozgener died on 9 June 2018 in Nashville, aged 81. In October 2026, the website caocigars.com carries the mention General Cigar Co., Inc.; depending on the line, the cigars are rolled in Estelí (Nicaragua), in Honduras or at General Cigar Dominicana (Dominican Republic).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('General Cigar compró CAO en 2007, haciendo entrar ese carácter inventivo en una cartera a la que la solidez comercial de Macanudo no podía aportarlo. La adquisición ha preservado el papel de CAO como la marca que toma los riesgos del grupo: aquella cuyo calendario de salidas siguen los aficionados por la novedad, mientras cuentan con Macanudo para la regularidad.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'General Cigar compró CAO en 2007, haciendo entrar ese carácter inventivo en una cartera a la que la solidez comercial de Macanudo no podía aportarlo. La adquisición ha preservado el papel de CAO como la marca que toma los riesgos del grupo: aquella cuyo calendario de salidas siguen los aficionados por la novedad, mientras cuentan con Macanudo para la regularidad.', 'En 2007, CAO fue comprada por Henri Wintermans, división de ST Tobacco, según la prensa del sector; Cigar Dojo nombra al actual Scandinavian Tobacco Group. La marca dejó Nashville por la sede de General Cigar en Richmond, Virginia. Tim Ozgener, hijo del fundador, siguió de presidente hasta 2010; Cano Ozgener murió el 9 de junio de 2018 en Nashville, a los 81 años. En octubre de 2026, el sitio caocigars.com lleva la mención General Cigar Co., Inc.; según las líneas, los puros se lían en Estelí (Nicaragua), en Honduras o en General Cigar Dominicana (República Dominicana).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('General Cigar kaufte CAO 2007 und holte damit dieses erfinderische Wesen in ein Portfolio, dem die kaufmännische Festigkeit von Macanudo es nicht geben konnte. Die Übernahme hat CAOs Rolle als jene Marke bewahrt, die im Konzern die Risiken eingeht: die, deren Neuheitenkalender die Liebhaber der Neugier wegen verfolgen, während sie sich bei Macanudo auf die Gleichmäßigkeit verlassen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'General Cigar kaufte CAO 2007 und holte damit dieses erfinderische Wesen in ein Portfolio, dem die kaufmännische Festigkeit von Macanudo es nicht geben konnte. Die Übernahme hat CAOs Rolle als jene Marke bewahrt, die im Konzern die Risiken eingeht: die, deren Neuheitenkalender die Liebhaber der Neugier wegen verfolgen, während sie sich bei Macanudo auf die Gleichmäßigkeit verlassen.', '2007 wurde CAO laut Fachpresse von Henri Wintermans übernommen, einer Division von ST Tobacco; Cigar Dojo nennt die heutige Scandinavian Tobacco Group. Die Marke verließ Nashville und zog zum Sitz von General Cigar in Richmond, Virginia. Tim Ozgener, Sohn des Gründers, blieb bis 2010 Präsident; Cano Ozgener starb am 9. Juni 2018 in Nashville im Alter von 81 Jahren. Im Oktober 2026 trägt die Website caocigars.com den Vermerk General Cigar Co., Inc.; je nach Linie werden die Zigarren in Estelí (Nicaragua), in Honduras oder bei General Cigar Dominicana (Dominikanische Republik) gerollt.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('2007年，General Cigar 收购了 CAO，把这股发明的劲头带进一个组合里——那是马卡努多的商业稳健所无法提供的。这次收购保住了 CAO 在集团里担任冒险者的角色：爱好者盯着它的上市日程是为了新意，而把稳定寄托在马卡努多身上。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '2007年，General Cigar 收购了 CAO，把这股发明的劲头带进一个组合里——那是马卡努多的商业稳健所无法提供的。这次收购保住了 CAO 在集团里担任冒险者的角色：爱好者盯着它的上市日程是为了新意，而把稳定寄托在马卡努多身上。', '据行业媒体，2007年，CAO 被 ST Tobacco 旗下的 Henri Wintermans 收购；Cigar Dojo 点出的是如今的 Scandinavian Tobacco Group。品牌由此离开纳什维尔，迁往 General Cigar 位于弗吉尼亚州里士满的总部。创始人之子蒂姆·奥兹格纳一直担任总裁到2010年；卡诺·奥兹格纳于2018年6月9日在纳什维尔去世，享年81岁。2026年10月，caocigars.com 网站标注为 General Cigar Co., Inc.；各系列的雪茄视不同情况在埃斯特利（尼加拉瓜）、洪都拉斯或 General Cigar Dominicana（多米尼加共和国）卷制。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('اشترت «جنرال سيغار» شركة CAO عام 2007، فأدخلت هذا الطبع المبتكر في حافظة لم تكن متانة ماكانودو التجارية قادرة على منحه إياها. وقد حفظ الاستحواذ دور CAO بوصفها العلامة التي تخوض مخاطر المجموعة: تلك التي يتابع الهواة رزنامة إصداراتها طلبًا للجديد، بينما يعوّلون على ماكانودو في الانتظام.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'اشترت «جنرال سيغار» شركة CAO عام 2007، فأدخلت هذا الطبع المبتكر في حافظة لم تكن متانة ماكانودو التجارية قادرة على منحه إياها. وقد حفظ الاستحواذ دور CAO بوصفها العلامة التي تخوض مخاطر المجموعة: تلك التي يتابع الهواة رزنامة إصداراتها طلبًا للجديد، بينما يعوّلون على ماكانودو في الانتظام.', 'في عام 2007 اشترى Henri Wintermans، وهو قسم من ST Tobacco، شركة CAO بحسب صحافة المهنة؛ وتسمّي Cigar Dojo الكيان الحالي Scandinavian Tobacco Group. وغادرت العلامة ناشفيل إلى مقرّ General Cigar في ريتشموند بولاية فيرجينيا. وبقي تيم أوزغنر، ابن المؤسس، رئيسًا حتى عام 2010؛ وتُوفّي كانو أوزغنر في 9 يونيو 2018 في ناشفيل عن 81 عامًا. وفي أكتوبر 2026 يحمل موقع caocigars.com عبارة General Cigar Co., Inc.؛ وبحسب الخطوط تُلفّ السيجارات في إستيلي (نيكاراغوا) أو في هندوراس أو لدى General Cigar Dominicana (الجمهورية الدومينيكية).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO';

UPDATE `brands` SET
  `limited_eds` = '["CAO Zócalo (2018, régulière depuis 2021)","CAO Arcana (série annuelle depuis 2021)"]',
  `founded` = '1968 selon Cigar Dojo — Nashville, Tennessee',
  `factory` = 'Selon la ligne : STG Estelí (Nicaragua), STG Danlí et HATSA (Honduras), General Cigar Dominicana (République dominicaine)',
  `gamme` = '[{"name":"CAO Cameroon","color":"#8B6914","force":null,"story":"Cape du Cameroun sur liaison et tripe du Nicaragua, selon la page de la maison en octobre 2026. Formats : Churchill 6,875 x 48, Belicoso 6 x 54, Toro 5,5 x 55, Robusto 5 x 50, Perfecto 4 x 48.","vitolas":["Toro","Churchill","Robusto","Corona","Figurado"],"wrapper":"Cameroun"},{"name":"CAO Flathead","color":"#1C0A00","force":null,"story":"Gamme à l''imagerie hot rod et moto, avec des formats nommés d''après des pièces de moteur : V660 Carb, V554 Camshaft, V642 Piston, V450 Sparkplug, V770 Big Block (d''après une critique de Stogie Press). La maison la dit bâtie sur une cape Connecticut Broadleaf ; pour la V19 de 2019, Cigar Dojo cite une liaison Connecticut Habano et une tripe dominicaine et nicaraguayenne, roulée à STG Danlí. Les mélanges varient selon les éditions.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Connecticut Broadleaf"},{"name":"CAO Pilón","color":"#722F37","force":null,"story":"Cape Ecuadorian Habano Viso sur liaison et tripe du Nicaragua, selon la page de la maison en octobre 2026. Formats : Churchill 7 x 49, Toro 6,25 x 54, Gigante 6 x 60, Corona 5,5 x 44, Robusto Extra 5 x 52. Le pilón est la pile de feuilles où le tabac fermente.","vitolas":["Robusto","Toro","Churchill","Torpedo","Pyramid"],"wrapper":"Équateur (Habano Viso)"}]',
  `gamme_en` = '[{"name":"CAO Cameroon","color":"#8B6914","force":null,"story":"Cameroon wrapper over a Nicaraguan binder and filler, according to the house''s page in October 2026. Formats: Churchill 6.875 x 48, Belicoso 6 x 54, Toro 5.5 x 55, Robusto 5 x 50, Perfecto 4 x 48.","vitolas":["Toro","Churchill","Robusto","Corona","Figurado"],"wrapper":"Cameroon"},{"name":"CAO Flathead","color":"#1C0A00","force":null,"story":"Range with hot rod and motorcycle imagery, with formats named after engine parts: V660 Carb, V554 Camshaft, V642 Piston, V450 Sparkplug, V770 Big Block (from a Stogie Press review). The house says it is built on a Connecticut Broadleaf wrapper; for the 2019 V19, Cigar Dojo cites a Connecticut Habano binder and a Dominican and Nicaraguan filler, rolled at STG Danlí. Blends vary from one edition to another.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Connecticut Broadleaf"},{"name":"CAO Pilón","color":"#722F37","force":null,"story":"Ecuadorian Habano Viso wrapper over a Nicaraguan binder and filler, according to the house''s page in October 2026. Formats: Churchill 7 x 49, Toro 6.25 x 54, Gigante 6 x 60, Corona 5.5 x 44, Robusto Extra 5 x 52. The pilón is the pile of leaves in which the tobacco ferments.","vitolas":["Robusto","Toro","Churchill","Torpedo","Pyramid"],"wrapper":"Ecuador (Habano Viso)"}]',
  `gamme_es` = '[{"name":"CAO Cameroon","color":"#8B6914","force":null,"story":"Capa de Camerún sobre capote y tripa de Nicaragua, según la página de la casa en octubre de 2026. Formatos: Churchill 6,875 x 48, Belicoso 6 x 54, Toro 5,5 x 55, Robusto 5 x 50, Perfecto 4 x 48.","vitolas":["Toro","Churchill","Robusto","Corona","Figurado"],"wrapper":"Camerún"},{"name":"CAO Flathead","color":"#1C0A00","force":null,"story":"Gama de imaginería hot rod y moto, con formatos que llevan nombres de piezas de motor: V660 Carb, V554 Camshaft, V642 Piston, V450 Sparkplug, V770 Big Block (según una reseña de Stogie Press). La casa dice que está construida sobre una capa Connecticut Broadleaf; para la V19 de 2019, Cigar Dojo cita un capote Connecticut Habano y una tripa dominicana y nicaragüense, liada en STG Danlí. Las mezclas varían según las ediciones.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Connecticut Broadleaf"},{"name":"CAO Pilón","color":"#722F37","force":null,"story":"Capa Ecuadorian Habano Viso sobre capote y tripa de Nicaragua, según la página de la casa en octubre de 2026. Formatos: Churchill 7 x 49, Toro 6,25 x 54, Gigante 6 x 60, Corona 5,5 x 44, Robusto Extra 5 x 52. El pilón es la pila de hojas donde fermenta el tabaco.","vitolas":["Robusto","Toro","Churchill","Torpedo","Pyramid"],"wrapper":"Ecuador (Habano Viso)"}]',
  `gamme_de` = '[{"name":"CAO Cameroon","color":"#8B6914","force":null,"story":"Deckblatt aus Kamerun über Umblatt und Einlage aus Nicaragua, laut Seite des Hauses im Oktober 2026. Formate: Churchill 6,875 x 48, Belicoso 6 x 54, Toro 5,5 x 55, Robusto 5 x 50, Perfecto 4 x 48.","vitolas":["Toro","Churchill","Robusto","Corona","Figurado"],"wrapper":"Kamerun"},{"name":"CAO Flathead","color":"#1C0A00","force":null,"story":"Linie mit Hot-Rod- und Motorradbildwelt, deren Formate nach Motorteilen benannt sind: V660 Carb, V554 Camshaft, V642 Piston, V450 Sparkplug, V770 Big Block (nach einer Kritik von Stogie Press). Das Haus sagt, sie sei auf einem Deckblatt Connecticut Broadleaf aufgebaut; für die V19 von 2019 nennt Cigar Dojo ein Umblatt Connecticut Habano und eine dominikanische und nicaraguanische Einlage, gerollt bei STG Danlí. Die Mischungen variieren je nach Ausgabe.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Connecticut Broadleaf"},{"name":"CAO Pilón","color":"#722F37","force":null,"story":"Deckblatt Ecuadorian Habano Viso über Umblatt und Einlage aus Nicaragua, laut Seite des Hauses im Oktober 2026. Formate: Churchill 7 x 49, Toro 6,25 x 54, Gigante 6 x 60, Corona 5,5 x 44, Robusto Extra 5 x 52. Der Pilón ist der Blätterstapel, in dem der Tabak fermentiert.","vitolas":["Robusto","Toro","Churchill","Torpedo","Pyramid"],"wrapper":"Ecuador (Habano Viso)"}]',
  `gamme_zh` = '[{"name":"CAO Cameroon","color":"#8B6914","force":null,"story":"喀麦隆茄衣，茄套和茄芯来自尼加拉瓜，依据公司页面（2026年10月）。规格：Churchill 6.875 x 48、Belicoso 6 x 54、Toro 5.5 x 55、Robusto 5 x 50、Perfecto 4 x 48。","vitolas":["Toro","Churchill","Robusto","Corona","Figurado"],"wrapper":"喀麦隆"},{"name":"CAO Flathead","color":"#1C0A00","force":null,"story":"以改装老爷车（hot rod）与摩托车为意象的系列，规格以发动机零件命名：V660 Carb、V554 Camshaft、V642 Piston、V450 Sparkplug、V770 Big Block（出自 Stogie Press 的一篇评测）。公司称其以 Connecticut Broadleaf 茄衣为基础；对于2019年的 V19，Cigar Dojo 引述为 Connecticut Habano 茄套，以及多米尼加与尼加拉瓜的茄芯，在 STG Danlí 卷制。各版本的配方有所不同。","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Connecticut Broadleaf"},{"name":"CAO Pilón","color":"#722F37","force":null,"story":"Ecuadorian Habano Viso 茄衣，茄套和茄芯来自尼加拉瓜，依据公司页面（2026年10月）。规格：Churchill 7 x 49、Toro 6.25 x 54、Gigante 6 x 60、Corona 5.5 x 44、Robusto Extra 5 x 52。pilón 是烟叶堆垛，烟叶在其中发酵。","vitolas":["Robusto","Toro","Churchill","Torpedo","Pyramid"],"wrapper":"厄瓜多尔（Habano Viso）"}]',
  `gamme_ar` = '[{"name":"CAO Cameroon","color":"#8B6914","force":null,"story":"غلاف من الكاميرون فوق رابط وحشوة من نيكاراغوا، بحسب صفحة الدار في أكتوبر 2026. القياسات: Churchill 6,875 x 48، وBelicoso 6 x 54، وToro 5,5 x 55، وRobusto 5 x 50، وPerfecto 4 x 48.","vitolas":["Toro","Churchill","Robusto","Corona","Figurado"],"wrapper":"الكاميرون"},{"name":"CAO Flathead","color":"#1C0A00","force":null,"story":"تشكيلة بصور السيارات المعدَّلة (hot rod) والدراجات النارية، وقياساتها مسمّاة على قطع المحرّك: V660 Carb، وV554 Camshaft، وV642 Piston، وV450 Sparkplug، وV770 Big Block (عن مراجعة في Stogie Press). تقول الدار إنها مبنية على غلاف Connecticut Broadleaf؛ أما V19 لعام 2019 فتذكر Cigar Dojo رابطًا Connecticut Habano وحشوة دومينيكية ونيكاراغوية، لُفّت في STG Danlí. وتتفاوت الخلطات بحسب الإصدارات.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Connecticut Broadleaf"},{"name":"CAO Pilón","color":"#722F37","force":null,"story":"غلاف Ecuadorian Habano Viso فوق رابط وحشوة من نيكاراغوا، بحسب صفحة الدار في أكتوبر 2026. القياسات: Churchill 7 x 49، وToro 6,25 x 54، وGigante 6 x 60، وCorona 5,5 x 44، وRobusto Extra 5 x 52. والـpilón هو كومة الأوراق التي يتخمّر فيها التبغ.","vitolas":["Robusto","Toro","Churchill","Torpedo","Pyramid"],"wrapper":"الإكوادور (Habano Viso)"}]',
  `celebrities` = '[{"name":"Cano Ozgener","anecdote":"Né à Istanbul en 1937, ingénieur, fondateur de C.A.O. International à Nashville ; entré dans le cigare en 1993, premier CAO en 1995. La maison fut vendue en 2007 ; il est mort à Nashville le 9 juin 2018, à 81 ans, selon la presse du métier."}]',
  `celebrities_en` = '[{"name":"Cano Ozgener","anecdote":"Born in Istanbul in 1937, an engineer, founder of C.A.O. International in Nashville; entered cigars in 1993, first CAO in 1995. The house was sold in 2007; he died in Nashville on 9 June 2018, aged 81, according to the trade press."}]',
  `celebrities_es` = '[{"name":"Cano Ozgener","anecdote":"Nacido en Estambul en 1937, ingeniero, fundador de C.A.O. International en Nashville; entró en el puro en 1993, primer CAO en 1995. La casa se vendió en 2007; murió en Nashville el 9 de junio de 2018, a los 81 años, según la prensa del sector."}]',
  `celebrities_de` = '[{"name":"Cano Ozgener","anecdote":"Geboren 1937 in Istanbul, Ingenieur, Gründer von C.A.O. International in Nashville; stieg 1993 ins Zigarrengeschäft ein, erste CAO 1995. Das Haus wurde 2007 verkauft; er starb am 9. Juni 2018 in Nashville im Alter von 81 Jahren, laut Fachpresse."}]',
  `celebrities_zh` = '[{"name":"Cano Ozgener","anecdote":"1937年生于伊斯坦布尔，工程师，C.A.O. International 在纳什维尔的创办人；1993年进入雪茄行业，1995年推出首支 CAO。公司于2007年出售；据行业媒体，他于2018年6月9日在纳什维尔去世，享年81岁。"}]',
  `celebrities_ar` = '[{"name":"Cano Ozgener","anecdote":"وُلد في إسطنبول عام 1937، مهندس، مؤسس C.A.O. International في ناشفيل؛ دخل عالم السيجار عام 1993، وصدر أول CAO عام 1995. بيعت الدار عام 2007؛ وتُوفّي في ناشفيل في 9 يونيو 2018 عن 81 عامًا، بحسب صحافة المهنة."}]',
  `pairings` = '[{"type":"Café","name":"Café turc","notes":"Clin d''œil à l''origine stambouliote du fondateur : un café épais et intense, en accord avec un cigare corsé."}]',
  `pairings_en` = '[{"type":"Coffee","name":"Turkish coffee","notes":"A nod to the founder''s Istanbul origins: a thick, intense coffee, in keeping with a full-bodied cigar."}]',
  `pairings_es` = '[{"type":"Café","name":"Turkish coffee","notes":"Guiño al origen del fundador, natural de Estambul: un café espeso e intenso, en armonía con un puro recio."}]',
  `pairings_de` = '[{"type":"Kaffee","name":"Turkish coffee","notes":"Eine Verbeugung vor der Istanbuler Herkunft des Gründers: ein dicker, intensiver Kaffee, passend zu einer kräftigen Zigarre."}]',
  `pairings_zh` = '[{"type":"咖啡","name":"Turkish coffee","notes":"向创始人的伊斯坦布尔出身致意：浓稠而强烈的咖啡，与一支浓郁的雪茄相配。"}]',
  `pairings_ar` = '[{"type":"القهوة","name":"Turkish coffee","notes":"تحية إلى أصل المؤسِّس الإسطنبولي: قهوة كثيفة قوية، تنسجم مع سيجار شديد القوة."}]',
  `source` = IF(LOCATE(CAST('caocigars.com et cigaraficionado.com (Cano A. Ozgener, 1968 à Nashville ; le passage des accessoires au cigare ; rachat par Scandinavian Tobacco Group, production General Cigar à Danlí et Estelí)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'caocigars.com et cigaraficionado.com (Cano A. Ozgener, 1968 à Nashville ; le passage des accessoires au cigare ; rachat par Scandinavian Tobacco Group, production General Cigar à Danlí et Estelí)', 'caocigars.com (accueil, pages Pilón, Cameroon, Flathead ; octobre 2026 : propriétaire General Cigar Co., Inc., blends) ; cigaraficionado.com « Cano Ozgener, 81, dies » (2018 : mort le 9 juin 2018, cigare en 1993, premier CAO en 1995, rachat 2007 par Henri Wintermans / ST Tobacco) ; cigardojo.com « Ozgener family cigars announcement » (2022-06-30 : fondation 1968, rachat 2007) ; cigardojo.com « CAO Flathead Camshaft V19 » (2020 : Flathead 2013, STG Danlí) ; cigar-coop.com « PCA 2024 CAO » (2024-04-08 : HATSA, STG Estelí)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO';

-- ── Les sceaux des champs réécrits, calculés depuis les colonnes françaises ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` WHEN 'pairings' THEN b.`pairings` ELSE b.`gamme` END), 'machine', NULL, NOW()
  FROM `brands` b
  JOIN (SELECT 'Drew Estate' hote, 'celebrities' champ
        UNION ALL SELECT 'Drew Estate' hote, 'gamme' champ
        UNION ALL SELECT 'Drew Estate' hote, 'history' champ
        UNION ALL SELECT 'Drew Estate' hote, 'pairings' champ
        UNION ALL SELECT 'Liga Privada' hote, 'celebrities' champ
        UNION ALL SELECT 'Liga Privada' hote, 'gamme' champ
        UNION ALL SELECT 'Liga Privada' hote, 'history' champ
        UNION ALL SELECT 'My Father' hote, 'celebrities' champ
        UNION ALL SELECT 'My Father' hote, 'gamme' champ
        UNION ALL SELECT 'My Father' hote, 'history' champ
        UNION ALL SELECT 'My Father' hote, 'pairings' champ
        UNION ALL SELECT 'Oliva' hote, 'celebrities' champ
        UNION ALL SELECT 'Oliva' hote, 'gamme' champ
        UNION ALL SELECT 'Oliva' hote, 'history' champ
        UNION ALL SELECT 'Perdomo' hote, 'celebrities' champ
        UNION ALL SELECT 'Perdomo' hote, 'gamme' champ
        UNION ALL SELECT 'Perdomo' hote, 'history' champ
        UNION ALL SELECT 'Perdomo' hote, 'pairings' champ
        UNION ALL SELECT 'Plasencia' hote, 'celebrities' champ
        UNION ALL SELECT 'Plasencia' hote, 'gamme' champ
        UNION ALL SELECT 'Plasencia' hote, 'history' champ
        UNION ALL SELECT 'Plasencia' hote, 'pairings' champ
        UNION ALL SELECT 'Alec Bradley' hote, 'celebrities' champ
        UNION ALL SELECT 'Alec Bradley' hote, 'gamme' champ
        UNION ALL SELECT 'Alec Bradley' hote, 'history' champ
        UNION ALL SELECT 'Alec Bradley' hote, 'pairings' champ
        UNION ALL SELECT 'CAO' hote, 'celebrities' champ
        UNION ALL SELECT 'CAO' hote, 'gamme' champ
        UNION ALL SELECT 'CAO' hote, 'history' champ
        UNION ALL SELECT 'CAO' hote, 'pairings' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

