-- ── Contrôle : chaque ligne doit valoir 1 ──
SELECT 'Drew Estate' AS hote, 'fr' AS lang, 'founded' AS quoi, (CAST(`founded` AS BINARY) = CAST('1996 (kiosque dès 1995) — New York / Estelí' AS BINARY)) AS ok FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Drew Estate, Estelí, Nicaragua — La Gran Fabrica (ouverte en 2007 selon la presse du métier ; première fabrique de la maison à Estelí en 1998, dit la maison)' AS BINARY)) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Drew Estate naît à New York. En 1995, Jonathan Drew ouvre un kiosque de cigares de 16 pieds carrés au Mall du World Trade Center ; en 1996, lui et Marvin Samel, un camarade d''université, forment Drew Estate Inc., selon la presse du métier (la maison, elle, date ses débuts de 1995). Sa première marque, La Vieja Habana, est produite chez Tabacalera Perdomo. La page ACID de la maison date la naissance d''ACID de 1996 et dit qu''elle voulait rendre le cigare premium abordable à d''autres que les habitués des costumes d''affaires.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Jonathan Drew et Marvin Samuels fondèrent Drew Estate à New York en 1996 avec une idée que l''industrie établie jugeait quelque part entre la sottise et l''offense : infuser les cigares de composés aromatiques — café, vanille, chocolat, rhum — et les vendre à des gens qui trouvaient jusque-là le cigare inabordable. La gamme ACID qui en sortit connut un succès que le métier traditionnel ne savait pas expliquer. Elle vendit des cigares à des gens qui ne fumaient pas le cigare. Elle vendit des produits au prix du premium à des consommateurs qui n''étaient jamais entrés dans une cave. Elle créa un segment là où il n''y avait qu''un mur.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Drew Estate was born in New York. In 1995, Jonathan Drew opened a 16-square-foot cigar kiosk in the World Trade Center mall; in 1996, he and Marvin Samel, a university friend, formed Drew Estate Inc., according to the trade press (the house itself dates its beginnings to 1995). Its first brand, La Vieja Habana, was produced at Tabacalera Perdomo. The house''s ACID page dates ACID''s birth to 1996 and says it wanted to make the premium cigar affordable to people other than regulars in business suits.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Jonathan Drew and Marvin Samuels founded Drew Estate in New York in 1996 with an idea the established cigar industry found somewhere between foolish and offensive: infuse cigars with aromatic compounds — coffee, vanilla, chocolate, rum — and sell them to people who had previously found cigars unapproachable. The ACID line that resulted from this approach was immediately successful in ways that the traditional industry could not fully account for. It sold cigars to people who did not smoke cigars. It sold premium-priced products to consumers who had never entered a cigar shop. It created a new segment where previously there had been a wall.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Drew Estate nace en Nueva York. En 1995, Jonathan Drew abre un quiosco de puros de 16 pies cuadrados en el centro comercial del World Trade Center; en 1996, él y Marvin Samel, un compañero de universidad, fundan Drew Estate Inc., según la prensa del sector (la casa, por su parte, data sus comienzos en 1995). Su primera marca, La Vieja Habana, se produce en Tabacalera Perdomo. La página ACID de la casa data el nacimiento de ACID en 1996 y dice que quería hacer el puro premium asequible para personas distintas de los habituales de los trajes de negocios.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Jonathan Drew y Marvin Samuels fundaron Drew Estate en Nueva York en 1996 con una idea que la industria establecida situaba entre la tontería y la ofensa: infundir los puros con compuestos aromáticos —café, vainilla, chocolate, ron— y venderlos a gente que hasta entonces encontraba el puro inabordable. La gama ACID que salió de ahí conoció un éxito que el oficio tradicional no sabía explicar. Vendió puros a gente que no fumaba puros. Vendió productos a precio premium a consumidores que nunca habían entrado en una casa de puros. Creó un segmento donde solo había un muro.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Drew Estate entsteht in New York. 1995 eröffnet Jonathan Drew im Einkaufszentrum des World Trade Center einen 16 Quadratfuß großen Zigarrenkiosk; 1996 gründen er und Marvin Samel, ein Studienfreund, Drew Estate Inc., so die Fachpresse (das Haus selbst datiert seine Anfänge auf 1995). Seine erste Marke, La Vieja Habana, wird bei Tabacalera Perdomo hergestellt. Die ACID-Seite des Hauses datiert die Geburt von ACID auf 1996 und sagt, man habe die Premiumzigarre auch für andere erschwinglich machen wollen als für die Stammkunden in Geschäftsanzügen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Jonathan Drew und Marvin Samuels gründeten Drew Estate 1996 in New York mit einem Einfall, den die eingeführte Branche irgendwo zwischen Dummheit und Beleidigung ansiedelte: Zigarren mit Aromastoffen zu versetzen — Kaffee, Vanille, Schokolade, Rum — und sie an Leute zu verkaufen, denen die Zigarre bis dahin unzugänglich schien. Die daraus hervorgegangene Linie ACID hatte einen Erfolg, den das herkömmliche Fach nicht zu erklären wusste. Sie verkaufte Zigarren an Leute, die keine Zigarren rauchten. Sie verkaufte Waren zum Premiumpreis an Käufer, die nie ein Zigarrenhaus betreten hatten. Sie schuf ein Segment, wo zuvor nur eine Mauer stand.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Drew Estate 诞生于纽约。1995年，Jonathan Drew 在世界贸易中心的购物中心里开了一个16平方英尺的雪茄小亭；据业内媒体，1996年他与大学同学 Marvin Samel 创立了 Drew Estate Inc.（该厂自己则把起步定在1995年）。其首个品牌 La Vieja Habana 由 Tabacalera Perdomo 生产。该厂的 ACID 页面把 ACID 的诞生定在1996年，并称当时想让高端雪茄不再只属于西装革履的常客，而是让其他人也买得起。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('1996年，乔纳森·德鲁与马文·塞缪尔斯在纽约创办了德鲁庄园，凭的是一个成熟行业认为介于愚蠢与冒犯之间的想法：给雪茄注入香气化合物——咖啡、香草、巧克力、朗姆酒——再卖给那些此前觉得雪茄高不可攀的人。由此而来的 ACID 系列取得了传统行当解释不了的成功。它把雪茄卖给了不抽雪茄的人；它以高端价格把产品卖给了从未踏进雪茄行的顾客；它在原本只有一堵墙的地方开出了一个细分。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تولد Drew Estate في نيويورك. ففي عام 1995 افتتح Jonathan Drew كشك سيجار مساحته 16 قدمًا مربعة في مركز التسوق التابع لمركز التجارة العالمي؛ وفي عام 1996 أسّس هو وMarvin Samel، زميله في الجامعة، شركة Drew Estate Inc.، بحسب صحافة المهنة (أما الدار فتؤرّخ بداياتها بعام 1995). وعلامتها الأولى La Vieja Habana تُنتَج لدى Tabacalera Perdomo. وتؤرّخ صفحة ACID لدى الدار ولادة ACID بعام 1996 وتقول إنها أرادت جعل السيجار الفاخر في متناول غير المعتادين على بدلات العمل.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('أسّس جوناثان درو ومارفن صامويلز «درو إستيت» في نيويورك عام 1996 بفكرة رأت فيها الصناعة الراسخة ما هو بين الحماقة والإهانة: أن يُشرَب السيجار مركّبات عطرية — قهوة، وفانيليا، وشوكولاتة، ورَمّ — ويُباع لأناس كان السيجار في نظرهم بعيد المنال. وحقّقت تشكيلة ACID التي خرجت من ذلك نجاحًا عجزت المهنة التقليدية عن تفسيره. باعت سيجارًا لمن لا يدخّنون السيجار. وباعت بأسعار الفخامة لزبائن لم يدخلوا دار سيجار قط. وأنشأت قطاعًا حيث لم يكن سوى جدار.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Les ACID sont des cigares infusés : selon des détaillants (Simply Cigars, Element Vape), l''ACID Kuba Kuba est un robusto 5 x 54 pouces à cape Sumatra, liant et tripes du Nicaragua, infusé d''herbes et de botaniques. La maison ne détaille pas ces mélanges sur sa page ACID.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La réaction des puristes était prévisible, et en partie fondée. Les ACID ne sont pas, au sens traditionnel, des expressions d''un terroir : les arômes ajoutés dominent les apports de la cape, de la sous-cape et de la tripe au point de rendre la discussion technique de l''assemblage à peu près sans objet. Les dégustateurs expérimentés ne les commentaient pas. La presse spécialisée traitait la marque comme une catégorie à part, reconnaissant implicitement que les règles d''évaluation du premium ne s''y appliquaient pas.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('ACID cigars are infused cigars: according to retailers (Simply Cigars, Element Vape), the ACID Kuba Kuba is a 5 x 54 inch robusto with a Sumatra wrapper, a Nicaraguan binder and fillers, infused with herbs and botanicals. The house does not detail these blends on its ACID page.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The purist reaction was predictable and partially valid. ACID cigars were not, in the traditional sense, expressions of tobacco terroir. The added aromatics dominated the wrapper, binder, and filler contributions in ways that made technical discussion of the blend largely irrelevant. Experienced tasters did not review ACID. The established trade press treated the brand as a separate category, implicitly acknowledging that the rules governing premium evaluation did not apply.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Los ACID son puros infusionados: según detallistas (Simply Cigars, Element Vape), el ACID Kuba Kuba es un robusto de 5 x 54 pulgadas con capa Sumatra, capote y tripas de Nicaragua, infusionado con hierbas y botánicos. La casa no detalla estas mezclas en su página ACID.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La reacción de los puristas era previsible, y en parte fundada. Los ACID no son, en sentido tradicional, expresiones de un terruño: los aromas añadidos dominan las aportaciones de la capa, del capote y de la tripa hasta volver la discusión técnica de la ligada poco menos que sin objeto. Los catadores experimentados no los comentaban. La prensa especializada trataba la marca como una categoría aparte, reconociendo implícitamente que las reglas de evaluación del premium no se le aplicaban.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Die ACID sind infundierte Zigarren: Laut Händlern (Simply Cigars, Element Vape) ist die ACID Kuba Kuba ein Robusto von 5 x 54 Zoll mit Deckblatt Sumatra, Umblatt und Einlagen aus Nicaragua, infundiert mit Kräutern und Pflanzenstoffen. Das Haus gibt diese Mischungen auf seiner ACID-Seite nicht näher an.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die Reaktion der Puristen war vorhersehbar und zum Teil begründet. Die ACID sind im herkömmlichen Sinn keine Ausdrucksformen eines Bodens: Die zugesetzten Aromen überlagern die Beiträge von Deckblatt, Umblatt und Einlage so weit, dass die technische Erörterung der Mischung nahezu gegenstandslos wird. Erfahrene Verkoster besprachen sie nicht. Die Fachpresse behandelte die Marke als eigene Kategorie und räumte damit stillschweigend ein, dass die Maßstäbe des Premiums auf sie nicht zutrafen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('ACID 系列是加香雪茄：据零售商（Simply Cigars、Element Vape），ACID Kuba Kuba 是一款 5 x 54 英寸的罗布图，茄衣为苏门答腊，茄套与茄芯来自尼加拉瓜，以草本和植物成分加香。该厂在其 ACID 页面上并未详述这些配方。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('纯粹主义者的反应可以预料，也有一部分道理。就传统意义而言，ACID 并不是某片风土的表达：外加的香气压过了茄衣、茄套与茄芯的贡献，以致对配方的技术讨论几乎失去了对象。老练的品鉴者不去评论它们。专业媒体把这个品牌当作单独一类看待，等于默认高端雪茄的评价规则并不适用于它。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('سيجار ACID سيجار منقوع: بحسب تجار التجزئة (Simply Cigars وElement Vape) فإن ACID Kuba Kuba روبوستو 5 × 54 بوصة بغلاف سومطرة، ورابط وحشوات من نيكاراغوا، منقوع بالأعشاب والنباتات. ولا تفصّل الدار هذه الخلطات في صفحة ACID.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('وكان ردّ فعل المتشدّدين متوقّعًا، وله وجه من الصواب. فسيجار ACID ليس، بالمعنى التقليدي، تعبيرًا عن أرض: إذ تطغى النكهات المضافة على إسهام الغلاف والرابط والحشوة إلى حدّ يجعل النقاش التقني في الخلطة بلا موضوع تقريبًا. لم يكن الذوّاقة المتمرّسون يعلّقون عليه. وعاملته الصحافة المتخصّصة كصنف قائم بذاته، معترفةً ضمنًا بأن قواعد تقييم الفاخر لا تنطبق عليه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('En 1998, l''ouragan Mitch interrompt la production de La Vieja Habana ; Jonathan Drew part pour le Nicaragua et, dit la maison, ouvre à l''automne 1998 sa première fabrique à Estelí. La Gran Fabrica Drew Estate, où sont aujourd''hui roulées ses lignes, a ouvert en 2007 selon la presse du métier. La même année, la Liga Privada No. 9 fait ses débuts (cape Connecticut broadleaf, mélange de quatre pays, selon la même source) ; la maison date sa marque Liga Privada de 2007.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('L''installation à Estelí, au Nicaragua, en 2000, donna la base industrielle qui permit à la fois de produire les ACID à grande échelle et de mener le projet tabacole sérieux qui allait devenir Liga Privada. La même manufacture qui roulait des cigarillos infusés assemblait des capes Connecticut Broadleaf sur du ligero nicaraguayen, pour une série privée que Drew n''avait pas l''intention de commercialiser. Les deux activités cohabitaient sans contradiction apparente, parce que Drew les comprenait comme deux expressions de la même chose : un point de vue tranché sur ce que doit faire un cigare.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('In 1998, Hurricane Mitch interrupted the production of La Vieja Habana; Jonathan Drew left for Nicaragua and, says the house, opened its first factory in Estelí in the autumn of 1998. La Gran Fabrica Drew Estate, where its lines are rolled today, opened in 2007 according to the trade press. In the same year, the Liga Privada No. 9 made its debut (Connecticut broadleaf wrapper, a blend from four countries, according to the same source); the house dates its Liga Privada brand to 2007.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Drew Estate''s move to Estelí, Nicaragua in 2000 established the manufacturing base that allowed the company to scale ACID production while simultaneously developing the serious tobacco project that would become Liga Privada. The same factory that produced infused cigarillos was blending Connecticut Broadleaf Habano wrappers over Nicaraguan ligero for a private label that Drew had no intention of commercializing. The two activities coexisted in the same building without apparent contradiction because Drew understood them as separate expressions of the same thing: a strong point of view about what a cigar should do.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('En 1998, el huracán Mitch interrumpe la producción de La Vieja Habana; Jonathan Drew parte hacia Nicaragua y, dice la casa, abre en el otoño de 1998 su primera fábrica en Estelí. La Gran Fabrica Drew Estate, donde hoy se tuercen sus líneas, abrió en 2007 según la prensa del sector. El mismo año, el Liga Privada No. 9 hace su debut (capa Connecticut broadleaf, mezcla de cuatro países, según la misma fuente); la casa data su marca Liga Privada de 2007.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La instalación en Estelí, en Nicaragua, en 2000, dio la base industrial que permitió a la vez producir los ACID a gran escala y llevar el proyecto tabaquero serio que iba a convertirse en Liga Privada. La misma manufactura que liaba cigarrillos infundidos montaba capas Connecticut Broadleaf sobre ligero nicaragüense, para una serie privada que Drew no pensaba comercializar. Las dos actividades convivían sin contradicción aparente, porque Drew las entendía como dos expresiones de lo mismo: un punto de vista tajante sobre lo que debe hacer un puro.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('1998 unterbricht der Hurrikan Mitch die Produktion von La Vieja Habana; Jonathan Drew geht nach Nicaragua und eröffnet, so das Haus, im Herbst 1998 seine erste Fabrik in Estelí. La Gran Fabrica Drew Estate, in der heute seine Linien gerollt werden, wurde laut der Fachpresse 2007 eröffnet. Im selben Jahr debütiert die Liga Privada No. 9 (Deckblatt Connecticut Broadleaf, Mischung aus vier Ländern, laut derselben Quelle); das Haus datiert seine Marke Liga Privada auf 2007.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Die Ansiedlung in Estelí in Nicaragua im Jahr 2000 gab die gewerbliche Grundlage, um zugleich die ACID in großem Umfang herzustellen und jenes ernsthafte Tabakvorhaben zu betreiben, aus dem Liga Privada werden sollte. Dieselbe Manufaktur, die versetzte Zigarillos rollte, setzte Connecticut-Broadleaf-Deckblätter auf nicaraguanischen Ligero, für eine private Reihe, die Drew nicht in den Handel bringen wollte. Beide Tätigkeiten bestanden ohne sichtbaren Widerspruch nebeneinander, weil Drew sie als zwei Ausdrucksformen derselben Sache verstand: einer entschiedenen Ansicht darüber, was eine Zigarre tun soll.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('1998年，飓风米奇中断了 La Vieja Habana 的生产；Jonathan Drew 前往尼加拉瓜，据该厂称，1998年秋在埃斯特利开设了首家工厂。据业内媒体，如今卷制其各条产品线的 La Gran Fabrica Drew Estate 于2007年开业。同年，Liga Privada No. 9 首次亮相（康涅狄格宽叶茄衣，四国混合配方，据同一来源）；该厂把 Liga Privada 品牌定在2007年。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('2000年落户尼加拉瓜的埃斯特利，带来了工业基础：既能大规模生产 ACID，也能推进那个后来成为 Liga Privada 的认真烟草项目。同一家工厂，一边卷着加香小雪茄，一边把康涅狄格宽叶茄衣覆在尼加拉瓜利加罗上，做一个德鲁本没打算上市的私人系列。两条线并存而看不出矛盾，因为在德鲁看来它们是同一件事的两种表达：关于一支雪茄该做什么的一个鲜明立场。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('في عام 1998 أوقف إعصار ميتش إنتاج La Vieja Habana؛ فتوجّه Jonathan Drew إلى نيكاراغوا وافتتح، بحسب الدار، في خريف 1998 أول مصنع لها في إستيلي. أما La Gran Fabrica Drew Estate، التي تُلَفّ فيها خطوطها اليوم، فقد افتُتحت عام 2007 بحسب صحافة المهنة. وفي السنة نفسها ظهرت Liga Privada No. 9 لأول مرة (غلاف كونيتيكت برودليف، خلطة من أربعة بلدان، بحسب المصدر نفسه)؛ وتؤرّخ الدار علامتها Liga Privada بعام 2007.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وقد أتاح الانتقال إلى إستيلي في نيكاراغوا عام 2000 القاعدة الصناعية التي سمحت في آن بإنتاج ACID على نطاق واسع وبإدارة المشروع التبغي الجادّ الذي سيصير «ليغا بريفادا». فالمصنع نفسه الذي كان يلفّ السيجار الصغير المُشرَب كان يركّب أغلفة «كونيتيكت برودليف» على ليغيرو نيكاراغوي، لسلسلة خاصة لم يكن درو ينوي طرحها في السوق. تعايش النشاطان بلا تناقض ظاهر، لأن درو كان يفهمهما تعبيرين عن الشيء نفسه: رأيٌ حاسم في ما ينبغي أن يفعله السيجار.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Le 20 octobre 2014, Swisher International annonce un accord pour acquérir Drew Estate en totalité, marques et fabrique comprises : la maison resterait une filiale à part entière, son équipe de direction maintenue ; les conditions n''étaient pas divulguées et la clôture était attendue avant la fin 2014 (presse du métier, 20 octobre 2014). En octobre 2026, la page À propos de la maison ne nomme pas de propriétaire.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La percée commerciale du Liga Privada No.9, en 2008, obligea le marché à réviser entièrement son jugement. Une maison qui fait à la fois un cigare premium recherché et un cigare aromatisé largement diffusé occupe une place qu''aucune catégorie antérieure ne décrivait. Ce que Drew Estate laissera, quoi qu''il en soit, tiendra à ce fait : elle a élargi la catégorie par les deux bouts en même temps.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('On 20 October 2014, Swisher International announced an agreement to acquire Drew Estate in full, brands and factory included: the house would remain a wholly owned subsidiary, with its management team kept in place; the terms were not disclosed and closing was expected before the end of 2014 (trade press, 20 October 2014). In October 2026, the house''s About page names no owner.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Liga Privada No.9''s commercial breakthrough in 2008, and the critical recognition that followed, forced the market to revise its assessment of Drew Estate entirely. A house that makes both a sought-after premium cigar and a widely sold flavoured one occupies a position in the industry no earlier category could describe. Drew Estate''s legacy, whatever it ultimately turns out to be, will be built on the fact that it expanded the category at both ends simultaneously.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('El 20 de octubre de 2014, Swisher International anuncia un acuerdo para adquirir Drew Estate por completo, marcas y fábrica incluidas: la casa seguiría siendo una filial de pleno derecho, con su equipo directivo mantenido; las condiciones no se divulgaron y se esperaba el cierre antes de finales de 2014 (prensa del sector, 20 de octubre de 2014). En octubre de 2026, la página «Acerca de» de la casa no nombra a ningún propietario.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('El éxito comercial del Liga Privada No.9, en 2008, obligó al mercado a revisar enteramente su juicio. Una casa que hace a la vez un puro premium buscado y un puro aromatizado ampliamente difundido ocupa un lugar que ninguna categoría anterior describía. Lo que Drew Estate deje, sea como sea, se sostendrá en ese hecho: ha ensanchado la categoría por los dos extremos a la vez.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Am 20. Oktober 2014 kündigt Swisher International eine Vereinbarung an, Drew Estate vollständig zu übernehmen, Marken und Fabrik eingeschlossen: Das Haus bliebe eine hundertprozentige Tochtergesellschaft, sein Führungsteam bliebe erhalten; die Bedingungen wurden nicht offengelegt, der Abschluss wurde vor Ende 2014 erwartet (Fachpresse, 20. Oktober 2014). Im Oktober 2026 nennt die Seite „Über uns“ des Hauses keinen Eigentümer.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Drew Estate'
UNION ALL SELECT 'Drew Estate', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Der Durchbruch der Liga Privada No.9 im Jahr 2008 zwang den Markt, sein Urteil vollständig zu überprüfen. Ein Haus, das zugleich eine gesuchte Premiumzigarre und eine weit verbreitete aromatisierte Zigarre macht, nimmt einen Platz ein, den keine frühere Einteilung beschrieb. Was Drew Estate hinterlassen wird, hängt jedenfalls an dieser Tatsache: Sie hat die Kategorie an beiden Enden zugleich geweitet.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Drew Estate'
