UNION ALL SELECT 'Liga Privada', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Liga Privada, qui veut dire mélange privé, naît chez Drew Estate d''un travail d''assemblage commencé à l''été 2005, selon Cigar Dojo (2018) : en 2006, Jonathan Drew, Steve Saka et Nicholas Melillo disposent d''une collection de plus de cinquante mélanges, dont trois finalistes numérotés 3, 4 et 9. Les débuts publics de la marque sont datés de 2007 par la maison et par Cigar Dojo (RTDA 2007, un seul toro 6 x 52), du No.9 de 2008 par Cigar Coop (2013), qui y voit le neuvième assemblage travaillé par Saka.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Liga Privada n''était pas censé exister. Jonathan Drew composa ces cigares pour lui-même et quelques proches — « liga privada » signifie littéralement « mélange privé » en espagnol. L''assemblage No.9 fut conçu pour un cercle d''une quinzaine de personnes. Quand les premières boîtes arrivèrent, à titre d''essai, dans les caves de quelques détaillants américains, elles partirent presque aussitôt.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Liga Privada, which means private blend, was born at Drew Estate from blending work begun in the summer of 2005, according to Cigar Dojo (2018): in 2006, Jonathan Drew, Steve Saka and Nicholas Melillo had a collection of more than fifty blends, including three finalists numbered 3, 4 and 9. The brand''s public debut is dated 2007 by the house and by Cigar Dojo (RTDA 2007, a single 6 x 52 toro), and 2008, with the No.9, by Cigar Coop (2013), which sees in it the ninth blend worked on by Saka.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Liga Privada was never meant to exist. Jonathan Drew put these cigars together for himself and a few close friends — liga privada is literally "private blend" in Spanish. The No.9 blend was made for a circle of about fifteen people. When the first boxes reached a handful of American retailers'' humidors as a trial, they were gone almost at once.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Liga Privada, que significa mezcla privada, nace en Drew Estate de un trabajo de ligada iniciado en el verano de 2005, según Cigar Dojo (2018): en 2006, Jonathan Drew, Steve Saka y Nicholas Melillo disponen de una colección de más de cincuenta mezclas, entre ellas tres finalistas numeradas 3, 4 y 9. Los inicios públicos de la marca se fechan en 2007 por la casa y por Cigar Dojo (RTDA 2007, un solo toro de 6 x 52), y en 2008, con el No.9, por Cigar Coop (2013), que ve en él la novena ligada trabajada por Saka.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Liga Privada no estaba destinada a existir. Jonathan Drew compuso estos puros para sí mismo y unos allegados: «liga privada» significa literalmente «mezcla privada». La ligada del No.9 se creó para un círculo de unas quince personas. Cuando las primeras cajas llegaron, a modo de prueba, a los humidores de unos pocos detallistas estadounidenses, se agotaron casi de inmediato.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Liga Privada, was „private Mischung“ bedeutet, entsteht bei Drew Estate aus einer Mischungsarbeit, die im Sommer 2005 begann, laut Cigar Dojo (2018): 2006 verfügen Jonathan Drew, Steve Saka und Nicholas Melillo über eine Sammlung von mehr als fünfzig Mischungen, darunter drei Finalisten mit den Nummern 3, 4 und 9. Den öffentlichen Start der Marke datieren das Haus und Cigar Dojo auf 2007 (RTDA 2007, ein einziger Toro 6 x 52), Cigar Coop (2013) auf 2008 mit der No.9, in der es die neunte von Saka bearbeitete Mischung sieht.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Liga Privada war nie zum Verkauf gedacht. Jonathan Drew stellte diese Zigarren für sich und einige Vertraute zusammen — „liga privada“ heißt wörtlich „private Mischung“. Die No.9 entstand für einen Kreis von etwa fünfzehn Personen. Als die ersten Kisten versuchsweise in die Humidore einiger amerikanischer Händler kamen, waren sie fast sofort vergriffen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Liga Privada 意为「私人配方」，据 Cigar Dojo（2018年），它源自 Drew Estate 自2005年夏天开始的调配工作：2006年，Jonathan Drew、Steve Saka 与 Nicholas Melillo 手中有一套五十多种配方的收集，其中三个入围者编号为3、4和9。该厂与 Cigar Dojo 把该品牌的公开亮相定在2007年（RTDA 2007，仅一款 6 x 52 的 toro），Cigar Coop（2013年）则定在2008年，以 No.9 为代表，认为它是 Saka 调配的第九个配方。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Liga Privada 本不该问世。乔纳森·德鲁最初只为自己和几位挚友调配这批雪茄——liga privada 在西班牙语中字面即「私人配方」。No.9 的配方是为大约十五人的小圈子而作。第一批木盒作为试销送到少数美国零售商的恒湿柜时，几乎立刻售罄。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Liga Privada، وتعني الخلطة الخاصة، وُلدت في Drew Estate من عمل خلطٍ بدأ في صيف 2005، بحسب Cigar Dojo (2018): ففي عام 2006 توافرت لدى Jonathan Drew وSteve Saka وNicholas Melillo مجموعة تضم ما يزيد على خمسين خلطة، منها ثلاث خلطات نهائية تحمل الأرقام 3 و4 و9. وتؤرّخ الدار وCigar Dojo الظهور العلني للعلامة بعام 2007 (RTDA 2007، toro واحد بقياس 6 × 52)، بينما تؤرّخه Cigar Coop (2013) بعام 2008 مع No.9، وترى فيها الخلطة التاسعة التي اشتغل عليها Saka.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('لم يكن لـ«ليغا بريفادا» أن توجد أصلًا. ركّب جوناثان درو هذه السيجارات لنفسه ولبضعة مقرّبين — و«liga privada» تعني حرفيًا «الخلطة الخاصة» بالإسبانية. وُضعت خلطة No.9 لدائرة من نحو خمسة عشر شخصًا. وحين وصلت العلب الأولى على سبيل التجربة إلى مخازن الترطيب لدى قلّة من تجار التجزئة الأمريكيين، نفدت في الحال تقريبًا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Le T52 suit en 2009 et l''Unico Serie en 2010, d''après Cigar Coop (2013). La maison dit rouler chaque Liga Privada dans une salle dédiée de La Gran Fabrica Drew Estate, au Nicaragua. Le 20 octobre 2014, Swisher International annonçait l''achat de Drew Estate, fabrique comprise, avec une clôture prévue au quatrième trimestre 2014 (Cigar Coop). Steve Saka quitte Drew Estate en juillet 2013, la presse notant que son héritage reste lié à la Liga Privada.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La liste d''attente qui suivit — parfois six à douze mois — transforma un cigare confidentiel en phénomène. Le No.9 et le T52 ont installé la gamme durablement. La rareté n''y est pas un argument de vente : on ne fait pas plus de Liga Privada sans cultiver davantage de la cape voulue, et il faut trois ans entre la plantation et le roulage. Drew Estate, maison alors connue pour ses cigares infusés Acid, montrait qu''elle savait aussi faire des cigares classiques que l''on recherche.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The T52 followed in 2009 and the Unico Serie in 2010, according to Cigar Coop (2013). The house says it rolls each Liga Privada in a dedicated room of La Gran Fabrica Drew Estate, in Nicaragua. On 20 October 2014, Swisher International announced the purchase of Drew Estate, factory included, with closing expected in the fourth quarter of 2014 (Cigar Coop). Steve Saka left Drew Estate in July 2013, the press noting that his legacy remains tied to Liga Privada.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The waiting list that followed — sometimes six to twelve months — turned a private cigar into a phenomenon. The No.9 and the T52 established the line for good. The scarcity is not a sales pitch: you cannot make more Liga Privada without growing more of the wrapper it needs, and that takes three years from planting to rolling. Drew Estate, then known for its Acid infused cigars, was showing that it could also make classic cigars people seek out.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('El T52 sigue en 2009 y el Unico Serie en 2010, según Cigar Coop (2013). La casa dice torcer cada Liga Privada en una sala dedicada de La Gran Fabrica Drew Estate, en Nicaragua. El 20 de octubre de 2014, Swisher International anunciaba la compra de Drew Estate, fábrica incluida, con un cierre previsto para el cuarto trimestre de 2014 (Cigar Coop). Steve Saka deja Drew Estate en julio de 2013, y la prensa señala que su legado sigue ligado a la Liga Privada.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La lista de espera que siguió —a veces de seis a doce meses— convirtió un puro confidencial en un fenómeno. El No.9 y el T52 asentaron la gama. La escasez no es un argumento de venta: no se puede hacer más Liga Privada sin cultivar más de la capa que exige, y eso lleva tres años desde la plantación hasta el torcido. Drew Estate, casa conocida entonces por sus puros infusionados Acid, demostraba que también sabía hacer puros clásicos y buscados.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Die T52 folgt 2009 und die Unico Serie 2010, laut Cigar Coop (2013). Das Haus sagt, es rolle jede Liga Privada in einem eigenen Raum von La Gran Fabrica Drew Estate in Nicaragua. Am 20. Oktober 2014 kündigte Swisher International den Kauf von Drew Estate an, Fabrik eingeschlossen, mit einem für das vierte Quartal 2014 vorgesehenen Abschluss (Cigar Coop). Steve Saka verlässt Drew Estate im Juli 2013; die Presse vermerkt, sein Erbe bleibe mit der Liga Privada verbunden.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die Warteliste, die folgte — mitunter sechs bis zwölf Monate —, machte aus einer privaten Zigarre ein Phänomen. No.9 und T52 haben die Linie dauerhaft etabliert. Die Knappheit ist kein Verkaufsargument: Mehr Liga Privada gibt es nur mit mehr vom passenden Deckblatt, und das braucht drei Jahre von der Pflanzung bis zum Rollen. Drew Estate, damals für seine aromatisierten Acid-Zigarren bekannt, zeigte, dass es auch klassische, gesuchte Zigarren kann.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('据 Cigar Coop（2013年），T52 于2009年随后推出，Unico Serie 于2010年推出。该厂称每一支 Liga Privada 都在尼加拉瓜 La Gran Fabrica Drew Estate 的专用房间中卷制。2014年10月20日，Swisher International 宣布收购 Drew Estate，工厂包括在内，预计2014年第四季度完成交割（Cigar Coop）。Steve Saka 于2013年7月离开 Drew Estate，媒体指出他的遗产仍与 Liga Privada 相连。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('随之而来的等候名单——有时长达六到十二个月——把一支私密雪茄变成了现象。No.9 与 T52 让这一系列长久立足。稀缺并非营销说辞：要做更多 Liga Privada，就得种出更多所需的茄衣，而从栽种到卷制需要三年。当时以 Acid 加味雪茄闻名的德鲁庄园，由此证明自己同样做得出受人追捧的传统雪茄。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تلتها T52 عام 2009 ثم Unico Serie عام 2010، بحسب Cigar Coop (2013). وتقول الدار إنها تلفّ كل Liga Privada في قاعة مخصّصة داخل La Gran Fabrica Drew Estate في نيكاراغوا. وفي 20 أكتوبر 2014 أعلنت Swisher International شراء Drew Estate، بمصنعها، مع إغلاق متوقع في الربع الرابع من 2014 (Cigar Coop). وغادر Steve Saka شركة Drew Estate في يوليو 2013، مع إشارة الصحافة إلى أن إرثه لا يزال مرتبطًا بـLiga Privada.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('قائمة الانتظار التي تلت — ستة إلى اثني عشر شهرًا أحيانًا — حوّلت سيجارة خاصة إلى ظاهرة. ورسّخت No.9 وT52 هذه التشكيلة. والندرة هنا ليست حجّة تسويقية: لا مزيد من «ليغا بريفادا» من دون زراعة مزيد من الغلافة المطلوبة، وذلك يستغرق ثلاث سنوات من الزراعة إلى اللف. وهكذا أثبتت «درو إستيت»، المعروفة يومها بسيجاراتها المعطّرة Acid، أنها تُتقن أيضًا السيجارات الكلاسيكية المطلوبة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Chaque ligne a sa cape. Le No.9 porte, dit la maison, une Connecticut River Valley Broadleaf No. 1 Dark, séchée à l''air ; le T52, une Habano du Connecticut coupée et séchée à la tige, vieillie de 30 à 36 mois. Les deux reposent sur une sous-cape Mata Fina du Brésil et une tripe du Honduras et du Nicaragua.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Liga Privada'
UNION ALL SELECT 'Liga Privada', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Chaque module a sa cape. Le No.9 porte une Connecticut Broadleaf maduro — sombre, huileuse, presque noire ; le T52, une habano de la vallée du Connecticut récoltée à la tige. Toutes deux fermentent trois ans avant le roulage. Le cigare, lui, tire de cette cape une douceur qui vient contredire la puissance nicaraguayenne de sa tripe.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Liga Privada'
