UNION ALL SELECT 'Oliva', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('يبدأ تاريخ عائلة أوليفا في مقاطعة بينار ديل ريو بكوبا، عام 1886 — حين زرعت التبغ لأول مرة في أقصى غرب الجزيرة، فيما سيُسمّى لاحقًا فويلتا أباخو. وطوال أكثر من ستين عامًا زرع آل أوليفا هذه الأرض الحمراء، وكسبوا فيها المعرفة التي سيحملها أحفادهم إلى المنفى.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Quand Cuba changea de régime, le petit-fils Gilberto Oliva passa de la culture au courtage de tabac. Selon la maison, il quitta l''île au début des années 1960 et chercha au Honduras, au Panama, au Mexique et aux Philippines des conditions proches du goût cubain, avant de s''établir au Nicaragua. Les dates divergent : Wikipédia le fait partir pour l''Espagne en 1964, cultiver au Nicaragua en 1969, puis quitter le pays en 1979 pour y revenir en 1995.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Quand Oswaldo Oliva quitta Cuba après la révolution, il emporta des semences, un savoir agricole, et la conviction qu''un bon tabac exige des conditions précises pour donner sa mesure. Après des séjours au Honduras et à Miami, il établit en 1968 des plantations dans la vallée nicaraguayenne de Jalapa — une région où sols volcaniques, altitude et humidité constante créent ce que les dégustateurs expérimentés reconnaissent comme l''équivalent le plus proche de la Vuelta Abajo hors de Cuba.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Cuando Cuba cambió de régimen, el nieto Gilberto Oliva pasó del cultivo al corretaje de tabaco. Según la casa, dejó la isla a principios de los años 1960 y buscó en Honduras, Panamá, México y Filipinas condiciones cercanas al gusto cubano, antes de establecerse en Nicaragua. Las fechas divergen: Wikipedia lo hace partir a España en 1964, cultivar en Nicaragua en 1969, y luego dejar el país en 1979 para volver en 1995.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Cuando Oswaldo Oliva dejó Cuba después de la revolución, se llevó semillas, un saber agrícola y la convicción de que un buen tabaco exige condiciones precisas para dar su medida. Tras estancias en Honduras y en Miami, estableció en 1968 plantaciones en el valle nicaragüense de Jalapa —una región donde suelos volcánicos, altitud y humedad constante crean lo que los catadores experimentados reconocen como el equivalente más cercano a la Vuelta Abajo fuera de Cuba.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Als Kuba das Regime wechselte, ging der Enkel Gilberto Oliva vom Anbau zum Tabakmaklergeschäft über. Laut dem Haus verließ er die Insel Anfang der 1960er Jahre und suchte in Honduras, Panama, Mexiko und auf den Philippinen nach Bedingungen, die dem kubanischen Geschmack nahekamen, bevor er sich in Nicaragua niederließ. Die Daten weichen ab: Wikipedia lässt ihn 1964 nach Spanien gehen, 1969 in Nicaragua anbauen, das Land dann 1979 verlassen und 1995 zurückkehren.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Als Oswaldo Oliva Kuba nach der Revolution verließ, nahm er Saatgut mit, ein landwirtschaftliches Wissen und die Überzeugung, dass guter Tabak genaue Bedingungen braucht, um sein Maß zu zeigen. Nach Aufenthalten in Honduras und Miami legte er 1968 Plantagen im nicaraguanischen Tal von Jalapa an — einer Gegend, in der vulkanische Böden, Höhenlage und gleichbleibende Feuchte das schaffen, was erfahrene Verkoster als die nächste Entsprechung zur Vuelta Abajo außerhalb Kubas erkennen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('古巴政权更迭时，孙辈的 Gilberto Oliva 由种植转向烟草经纪。据该公司称，他在20世纪60年代初离开古巴，先后到洪都拉斯、巴拿马、墨西哥和菲律宾寻找接近古巴口味的条件，之后才在尼加拉瓜安顿下来。各处日期不一：维基百科称他1964年前往西班牙，1969年在尼加拉瓜种植，1979年离开该国，1995年回来。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('革命之后奥斯瓦尔多·奥利瓦离开古巴时，带走的是种子、一身农艺，以及一个信念：好烟草需要精确的条件才能显出它的分量。在洪都拉斯与迈阿密辗转之后，他于1968年在尼加拉瓜的哈拉帕山谷建起种植园——那里的火山土壤、海拔与恒定湿度，造出了老练的品鉴者公认的、古巴之外最接近阿巴霍谷的条件。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('عندما تغيّر النظام في كوبا، انتقل الحفيد Gilberto Oliva من الزراعة إلى سمسرة التبغ. وبحسب الدار، غادر الجزيرة في مطلع ستينيات القرن الماضي، وبحث في هندوراس وبنما والمكسيك والفلبين عن شروط قريبة من الذوق الكوبي، قبل أن يستقر في نيكاراغوا. وتتباين التواريخ: فتجعله ويكيبيديا يغادر إلى إسبانيا عام 1964، ويزرع في نيكاراغوا عام 1969، ثم يترك البلد عام 1979 ليعود إليه عام 1995.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('وحين غادر أوسفالدو أوليفا كوبا بعد الثورة، حمل معه بذورًا، ومعرفة زراعية، وقناعةً بأن التبغ الجيد يحتاج شروطًا دقيقة كي يُظهر قدره. وبعد إقامات في هندوراس وميامي، أنشأ عام 1968 مزارع في وادي خالابا النيكاراغوي — منطقة تخلق فيها التربة البركانية والارتفاع والرطوبة الثابتة ما يعدّه الذوّاقة المتمرّسون أقرب مكافئ لفويلتا أباخو خارج كوبا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Pendant des années, la famille fut planteuse et courtière, sans marque à son nom. Son fils José raconte que Gilberto père faisait pousser du tabac chaque année et le mettait de côté (presse du métier, décembre 2017). Aucune page lue ne nomme les fabricants acheteurs.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Pendant près de trois décennies, Oliva fut le secret le moins bien gardé du métier. Si vous avez fumé un cigare premium nicaraguayen ou hondurien entre 1970 et 1995, il y a de bonnes chances que la feuille que vous teniez ait poussé sur des terres Oliva avant d''être vendue au fabricant dont le nom figurait sur la bague. Davidoff, Padrón, Ashton et des dizaines d''autres s''y sont approvisionnés. La famille vendait sans se plaindre et sans publicité : ils étaient planteurs, pas bâtisseurs de marque.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Durante años, la familia fue plantadora y corredora, sin marca a su nombre. Su hijo José cuenta que Gilberto padre hacía crecer tabaco cada año y lo guardaba (prensa del sector, diciembre de 2017). Ninguna página leída nombra a los fabricantes compradores.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Durante casi tres décadas, Oliva fue el secreto peor guardado del oficio. Si usted fumó un puro premium nicaragüense u hondureño entre 1970 y 1995, hay buenas probabilidades de que la hoja que sostenía hubiera crecido en tierras Oliva antes de venderse al fabricante cuyo nombre figuraba en la anilla. Davidoff, Padrón, Ashton y decenas de otros se abastecieron allí. La familia vendía sin quejarse y sin publicidad: eran plantadores, no constructores de marca.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Jahrelang war die Familie Pflanzer und Makler, ohne Marke unter eigenem Namen. Sein Sohn José erzählt, dass der Vater Gilberto jedes Jahr Tabak anbaute und ihn zurücklegte (Fachpresse, Dezember 2017). Keine der gelesenen Seiten nennt die kaufenden Hersteller.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Fast drei Jahrzehnte lang war Oliva das schlechtest gehütete Geheimnis des Fachs. Wer zwischen 1970 und 1995 eine nicaraguanische oder honduranische Premiumzigarre rauchte, hielt mit guter Wahrscheinlichkeit ein Blatt in der Hand, das auf Oliva-Land gewachsen war, bevor es an den Hersteller verkauft wurde, dessen Name auf der Banderole stand. Davidoff, Padrón, Ashton und Dutzende andere bezogen dort. Die Familie verkaufte ohne Klage und ohne Werbung: Sie waren Pflanzer, keine Markenbauer.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('多年来，这个家族是种植者兼经纪商，没有以自己名字命名的品牌。其子 José 说，老 Gilberto 每年都种烟草并把它留存起来（行业媒体，2017年12月）。所查阅的页面均未点名购买烟叶的制造商。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('将近三十年里，奥利瓦是这一行里守得最差的秘密。若你在1970年至1995年间抽过一支尼加拉瓜或洪都拉斯的高端雪茄，你手里那片叶子很可能长在奥利瓦的地里，然后才卖给了烟标上署名的那家厂。大卫杜夫、帕德龙、阿什顿，以及几十家别的字号，都从这里进货。这个家族卖得毫无怨言，也不做宣传：他们是种植者，不是品牌营造者。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('ظلّت العائلة سنوات مزارعة وسمسارة، من دون علامة تحمل اسمها. ويروي ابنه José أن Gilberto الأب كان يزرع التبغ كل سنة ويدّخره (الصحافة المتخصصة، كانون الأول/ديسمبر 2017). ولا تذكر أي صفحة مقروءة أسماء المصنّعين المشترين.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وطوال ثلاثة عقود تقريبًا، كانت أوليفا أسوأ أسرار المهنة حفظًا. فمن دخّن سيجارًا فاخرًا نيكاراغويًّا أو هندوراسيًّا بين 1970 و1995، يُرجَّح أن الورقة التي بين يديه نبتت في أرض أوليفا قبل أن تُباع إلى الصانع الذي حمل اسمُه الحلقة. دافيدوف، وبادرون، وآشتون، وعشرات غيرهم تزوّدوا من هناك. وكانت العائلة تبيع بلا شكوى وبلا إعلان: كانوا مزارعين، لا بُناة علامات.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('En 1995, Gilberto Oliva et son fils Gilberto Jr. firent un cigare dans la fabrique de Néstor Plasencia père, au Honduras, qu''ils nommèrent Gilberto Oliva ; un an plus tard, ils ouvrirent leur propre fabrique au Nicaragua et raccourcirent le nom en Oliva. La Serie V est la ligne phare de la maison ; son année de lancement diverge selon les sources (2004 dans l''ancienne fiche, 2006 selon Wikipédia, juin 2007 selon Halfwheel).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La troisième génération changea ce calcul. En 1995, convaincue que la qualité de sa feuille méritait une identité propre, elle lança Oliva Cigars. La Serie V — pour Vuelta, en hommage au Vuelta Abajo cubain — fut lancée en 2004 et devint la gamme sur laquelle la maison serait jugée.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('En 1995, Gilberto Oliva y su hijo Gilberto Jr. hicieron un puro en la fábrica de Néstor Plasencia padre, en Honduras, al que llamaron Gilberto Oliva; un año después abrieron su propia fábrica en Nicaragua y acortaron el nombre a Oliva. La Serie V es la línea insignia de la casa; su año de lanzamiento diverge según las fuentes (2004 en la ficha anterior, 2006 según Wikipedia, junio de 2007 según Halfwheel).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La tercera generación cambió ese cálculo. En 1995, convencida de que la calidad de su hoja merecía una identidad propia, lanzó Oliva Cigars. La Serie V —por Vuelta, en homenaje al Vuelta Abajo cubano— se lanzó en 2004 y se convirtió en la gama por la que se juzgaría a la casa.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('1995 stellten Gilberto Oliva und sein Sohn Gilberto Jr. in der Fabrik von Néstor Plasencia dem Älteren in Honduras eine Zigarre her, die sie Gilberto Oliva nannten; ein Jahr später eröffneten sie ihre eigene Fabrik in Nicaragua und kürzten den Namen zu Oliva. Die Serie V ist die Flaggschiff-Linie des Hauses; ihr Einführungsjahr weicht je nach Quelle ab (2004 im früheren Eintrag, 2006 laut Wikipedia, Juni 2007 laut Halfwheel).' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Die dritte Generation änderte diese Rechnung. 1995, überzeugt, dass die Güte ihres Blattes eine eigene Identität verdiente, gründete sie Oliva Cigars. Die Serie V — für Vuelta, als Verbeugung vor der kubanischen Vuelta Abajo — kam 2004 heraus und wurde zu der Linie, an der das Haus gemessen wird.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('1995年，Gilberto Oliva 与其子 Gilberto Jr. 在洪都拉斯老 Néstor Plasencia 的工厂里做了一款雪茄，取名 Gilberto Oliva；一年后，他们在尼加拉瓜开设了自己的工厂，并把名字缩短为 Oliva。Serie V 是该公司的主打系列；其推出年份因来源而异（旧资料页为2004年，据维基百科为2006年，据 Halfwheel 为2007年6月）。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('第三代改变了这笔账。1995年，他们确信自家叶子的品质配得上一个自己的名号，于是推出了奥利瓦雪茄。V系列——V 取自 Vuelta，向古巴的阿巴霍谷致意——于2004年问世，并成为衡量这家字号的那条线。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('في عام 1995 صنع Gilberto Oliva وابنه Gilberto Jr. سيجارًا في مصنع Néstor Plasencia الأب في هندوراس، وسمّياه Gilberto Oliva؛ وبعد عام افتتحا مصنعهما الخاص في نيكاراغوا واختصرا الاسم إلى Oliva. والـSerie V هي الخط الرئيسي للدار؛ وتختلف سنة إطلاقها بحسب المصادر (2004 في البطاقة السابقة، و2006 بحسب ويكيبيديا، وحزيران/يونيو 2007 بحسب Halfwheel).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'ar', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('غيّر الجيل الثالث هذه الحسبة. ففي 1995، اقتناعًا بأن جودة ورقتهم تستحق هوية خاصة، أطلقوا «أوليفا سيغارز». وصدرت السلسلة V — نسبةً إلى فويلتا، تحيةً لفويلتا أباخو الكوبية — عام 2004، وصارت التشكيلة التي تُقاس بها الدار.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'fr', 'histoire 5 (nouveau texte)', (LOCATE(CAST('La famille cultive du tabac de graine cubaine au Nicaragua, dit la maison. En juillet 2016, Oliva Cigar Co. a été rachetée par le groupe belge J. Cortès ; en 2021, la presse du métier la décrit comme sa filiale, la famille restant à la tête de l''entreprise à Miami Lakes (Floride).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'fr', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('L''avantage structurel de la maison tient à la propriété : chaque feuille qui entre dans un cigare Oliva a poussé sur des terres familiales, à Jalapa ou à Estelí. Gilberto Oliva Jr. inspecte ses plantations en personne, à cheval, à chaque saison. Ce lien direct entre la famille et le sol explique une régularité que peu d''approvisionnements sous contrat permettent.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'es', 'histoire 5 (nouveau texte)', (LOCATE(CAST('La familia cultiva en Nicaragua tabaco de semilla cubana, dice la casa. En julio de 2016, Oliva Cigar Co. fue comprada por el grupo belga J. Cortès; en 2021, la prensa del sector la describe como su filial, y la familia sigue al frente de la empresa en Miami Lakes (Florida).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'es', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('La ventaja estructural de la casa está en la propiedad: cada hoja que entra en un puro Oliva ha crecido en tierras familiares, en Jalapa o en Estelí. Gilberto Oliva Jr. inspecciona sus plantaciones en persona, a caballo, cada temporada. Ese vínculo directo entre la familia y el suelo explica una regularidad que pocos abastecimientos por contrato permiten.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'de', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Die Familie baut in Nicaragua Tabak aus kubanischem Saatgut an, sagt das Haus. Im Juli 2016 wurde Oliva Cigar Co. von der belgischen Gruppe J. Cortès übernommen; 2021 beschreibt die Fachpresse sie als deren Tochtergesellschaft, wobei die Familie in Miami Lakes (Florida) weiterhin an der Spitze des Unternehmens steht.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'de', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Der strukturelle Vorteil des Hauses liegt im Besitz: Jedes Blatt, das in eine Oliva-Zigarre eingeht, ist auf Familienland gewachsen, in Jalapa oder Estelí. Gilberto Oliva Jr. begeht seine Plantagen in jeder Saison selbst, zu Pferd. Diese unmittelbare Bindung zwischen Familie und Boden erklärt eine Gleichmäßigkeit, die wenige Lieferverträge zulassen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'zh', 'histoire 5 (nouveau texte)', (LOCATE(CAST('公司称，这个家族在尼加拉瓜种植古巴种子的烟草。2016年7月，Oliva Cigar Co. 被比利时的 J. Cortès 集团收购；2021年，行业媒体称它是该集团的子公司，家族仍在位于 Miami Lakes（佛罗里达）的公司担任领导。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'zh', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('这家字号在结构上的优势在于所有权：进入一支奥利瓦雪茄的每一片叶子，都长在哈拉帕或埃斯特利的家族土地上。吉尔贝托·奥利瓦二世每季都亲自骑马巡视自家的种植园。家族与土地之间这条直接的联系，解释了一种少有合同供货能够保证的稳定。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'ar', 'histoire 5 (nouveau texte)', (LOCATE(CAST('تزرع العائلة في نيكاراغوا تبغًا من بذور كوبية، بحسب الدار. وفي تموز/يوليو 2016 اشترت المجموعة البلجيكية J. Cortès شركة Oliva Cigar Co.؛ وفي عام 2021 تصفها الصحافة المتخصصة بأنها شركتها التابعة، مع بقاء العائلة على رأس الشركة في Miami Lakes (فلوريدا).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva'
UNION ALL SELECT 'Oliva', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('وميزة الدار البنيوية في الملكية: فكل ورقة تدخل سيجار أوليفا نبتت في أرض العائلة، في خالابا أو إستيلي. ويتفقّد غيلبرتو أوليفا الابن مزارعه بنفسه، على ظهر حصان، في كل موسم. وهذه الصلة المباشرة بين العائلة والتربة تفسّر انتظامًا قلّما يتيحه التزوّد بالعقود.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva'
