UNION ALL SELECT 'Perdomo', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Nick Perdomo Jr. lance Nick''s Cigar Co. à Miami en août 1992 (dans son garage, selon Wikipédia), sans quitter son poste de contrôleur aérien à l''aéroport de Miami. La famille a des racines cubaines : Wikipédia la rattache à San José de las Lajas, d''où venait son grand-père Silvio, et son père Nick Sr. a travaillé chez Partagás puis chez H. Upmann avant de quitter Cuba après la révolution. Les sources divergent sur les débuts nicaraguayens : la presse du métier de 2001 place une première fabrique à Estelí en 1995 et une plus grande en 1999, Wikipédia une installation en 1997 remplacée en 1999.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Le lien de Nick Perdomo avec le tabac nicaraguayen est généalogique avant d''être commercial. Sa famille cultivait le tabac dans la province cubaine de Pinar del Río depuis des générations avant que la révolution ne referme ce chapitre. Les semences et le savoir emportés en exil n''étaient pas des métaphores : les Perdomo, comme les Oliva et les Plasencia, ont conservé du matériel génétique de plants cubains, qu''ils ont fini par mettre en terre au Nicaragua.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Nick Perdomo Jr. launched Nick''s Cigar Co. in Miami in August 1992 (in his garage, according to Wikipedia), without leaving his job as an air traffic controller at Miami airport. The family has Cuban roots: Wikipedia ties it to San José de las Lajas, where his grandfather Silvio came from, and his father Nick Sr. worked at Partagás and then at H. Upmann before leaving Cuba after the revolution. Sources diverge on the Nicaraguan beginnings: the trade press in 2001 places a first factory in Estelí in 1995 and a larger one in 1999, Wikipedia an installation in 1997 replaced in 1999.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Nick Perdomo''s relationship with Nicaraguan tobacco is genealogical before it is commercial. His family cultivated tobacco in Cuba''s Pinar del Río province for generations before the revolution that ended that chapter. The seeds and knowledge they carried into exile were not metaphorical — the Perdomo family, like the Olivás and the Plasencias, preserved actual genetic material from Cuban tobacco plants that they eventually planted in Nicaraguan soil.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Nick Perdomo Jr. lanza Nick''s Cigar Co. en Miami en agosto de 1992 (en su garaje, según Wikipedia), sin dejar su puesto de controlador aéreo en el aeropuerto de Miami. La familia tiene raíces cubanas: Wikipedia la vincula con San José de las Lajas, de donde venía su abuelo Silvio, y su padre Nick Sr. trabajó en Partagás y luego en H. Upmann antes de dejar Cuba tras la revolución. Las fuentes divergen sobre los inicios nicaragüenses: la prensa del sector de 2001 sitúa una primera fábrica en Estelí en 1995 y otra mayor en 1999; Wikipedia, una instalación en 1997 sustituida en 1999.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('El vínculo de Nick Perdomo con el tabaco nicaragüense es genealógico antes que comercial. Su familia cultivaba tabaco en la provincia cubana de Pinar del Río desde hacía generaciones antes de que la revolución cerrara ese capítulo. Las semillas y el saber llevados al exilio no eran metáforas: los Perdomo, como los Oliva y los Plasencia, conservaron material genético de plantas cubanas, que acabaron sembrando en Nicaragua.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Nick Perdomo Jr. gründet Nick''s Cigar Co. im August 1992 in Miami (laut Wikipedia in seiner Garage), ohne seine Stelle als Fluglotse am Flughafen Miami aufzugeben. Die Familie hat kubanische Wurzeln: Wikipedia verbindet sie mit San José de las Lajas, woher sein Großvater Silvio stammte, und sein Vater Nick Sr. arbeitete bei Partagás und danach bei H. Upmann, bevor er Kuba nach der Revolution verließ. Über die nicaraguanischen Anfänge gehen die Quellen auseinander: Die Fachpresse von 2001 nennt eine erste Fabrik in Estelí 1995 und eine größere 1999, Wikipedia eine Niederlassung 1997, die 1999 ersetzt wurde.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Bindung von Nick Perdomo an den nicaraguanischen Tabak ist genealogisch, bevor sie kaufmännisch ist. Seine Familie baute in der kubanischen Provinz Pinar del Río seit Generationen Tabak an, ehe die Revolution dieses Kapitel schloss. Saatgut und Wissen, ins Exil mitgenommen, waren keine Bilder: Die Perdomos haben, wie die Olivas und die Plasencias, Erbmaterial kubanischer Pflanzen bewahrt und schließlich in Nicaragua in die Erde gebracht.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('尼克·佩尔多莫（Nick Perdomo Jr.）于1992年8月在迈阿密创办 Nick''s Cigar Co.（据维基百科，地点是他的车库），当时他并未辞去迈阿密机场空中交通管制员的职务。这个家族有古巴渊源：维基百科把它与圣何塞-德拉斯拉赫斯（San José de las Lajas）联系起来，他的祖父西尔维奥（Silvio）即来自那里；其父老尼克（Nick Sr.）先后在 Partagás 与 H. Upmann 工作，革命后离开古巴。关于尼加拉瓜的起步，各方说法不一：2001年的行业媒体称1995年在埃斯特利有首家工厂，1999年有一家更大的；维基百科则称1997年设厂，1999年被取代。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('尼克·佩尔多莫与尼加拉瓜烟草的关系，先是血脉的，然后才是生意的。革命合上那一章之前，他家在古巴的比那尔德里奥省已经种了几代烟草。带去流亡的种子与本事并不是比喻：佩尔多莫家和奥利瓦家、普拉森西亚家一样，保住了古巴烟株的遗传材料，最终把它们种进了尼加拉瓜的土里。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('أطلق نيك بيردومو الابن شركة Nick''s Cigar Co. في ميامي في أغسطس 1992 (في مرآبه، بحسب ويكيبيديا)، دون أن يترك عمله مراقبًا جويًّا في مطار ميامي. وللعائلة جذور كوبية: تربطها ويكيبيديا بسان خوسيه دي لاس لاخاس، التي جاء منها جدّه سيلفيو، وقد عمل أبوه نيك الأب في Partagás ثم في H. Upmann قبل أن يغادر كوبا بعد الثورة. وتتباين المصادر في بدايات نيكاراغوا: فالصحافة المتخصصة عام 2001 تضع مصنعًا أول في إستيلي عام 1995 ومصنعًا أوسع منه عام 1999، وتذكر ويكيبيديا منشأة عام 1997 حلّت محلها أخرى عام 1999.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('صلة نيك بيردومو بالتبغ النيكاراغوي نَسَبية قبل أن تكون تجارية. فقد كانت عائلته تزرع التبغ في مقاطعة بينار ديل ريو الكوبية منذ أجيال، قبل أن تغلق الثورة ذلك الفصل. ولم تكن البذور والمعرفة المحمولتان إلى المنفى استعارة: فآل بيردومو، مثل آل أوليفا وآل بلاسينسيا، حفظوا مادة وراثية من شتلات كوبية، وانتهوا إلى غرسها في نيكاراغوا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo'
UNION ALL SELECT 'Perdomo', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Cette continuité compte, parce que l''argument central de la maison — le tabac nicaraguayen de la vallée de Jalapa peut rivaliser de complexité et de profondeur avec le cubain — n''est pas une formule publicitaire mais la conclusion de quelqu''un qui a grandi avec les deux. Le père de Nick Perdomo savait le goût du tabac de la Vuelta Abajo parce qu''il l''avait cultivé. Nick le savait parce que son père le lui avait montré. La comparaison qu''il fait en décrivant sa feuille nicaraguayenne s''appuie sur une mémoire sensorielle transmise.

' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo'
