UNION ALL SELECT 'Plasencia', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The Plasencia family has grown tobacco since 1865 — a continuity spanning five generations, two continents, and one of the tobacco industry''s most profound upheavals. What began in Cuba''s Pinar del Río province survived the Cuban revolution, the Nicaraguan revolution, the Contra war, and a half-century of economic instability across Central America and the family has kept growing tobacco through all of it.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La familia Plasencia cultiva tabaco desde 1865, dice la casa (plasenciacigars.com, octubre de 2026), que cuenta cinco generaciones. Según el blog de Cigars Direct (2020), todo empieza con Eduardo Plasencia, llegado de Canarias a Vuelta Abajo, en Cuba.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La familia Plasencia cultiva tabaco desde 1865 —una continuidad de cinco generaciones, en dos continentes, a través de uno de los vuelcos más profundos que ha conocido el oficio. Lo que empezó en la provincia cubana de Pinar del Río sobrevivió a la revolución cubana, a la revolución nicaragüense, a la guerra de la Contra y a medio siglo de inestabilidad económica en Centroamérica —y la familia no dejó de cultivar.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Die Familie Plasencia baut seit 1865 Tabak an, sagt das Haus (plasenciacigars.com, Oktober 2026), das fünf Generationen zählt. Laut dem Blog von Cigars Direct (2020) beginnt alles mit Eduardo Plasencia, der von den Kanarischen Inseln nach Vuelta Abajo auf Kuba kam.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Familie Plasencia baut seit 1865 Tabak an — eine Fortdauer über fünf Generationen, auf zwei Erdteilen, durch einen der tiefsten Umbrüche, die das Fach erlebt hat. Was in der kubanischen Provinz Pinar del Río begann, überstand die kubanische Revolution, die nicaraguanische Revolution, den Contra-Krieg und ein halbes Jahrhundert wirtschaftlicher Unsicherheit in Mittelamerika — und die Familie hörte nicht auf anzubauen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('据该厂所述（plasenciacigars.com，2026年10月），普拉森西亚家族自1865年起种植烟草，已传五代。据 Cigars Direct 的博客（2020年），一切始于爱德华多·普拉森西亚（Eduardo Plasencia），他从加那利群岛来到古巴的阿巴霍谷。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('普拉森西亚家族自1865年起种植烟草——五代人的延续，跨越两个大陆，穿过这一行所经历的最深刻的剧变之一。始于古巴比那尔德里奥省的事业，熬过了古巴革命、尼加拉瓜革命、反政府武装战争，以及中美洲半个世纪的经济动荡——而这个家族始终没有停止耕作。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تزرع عائلة بلاسينسيا التبغ منذ 1865، بحسب الدار (plasenciacigars.com، أكتوبر 2026)، وهي تعدّ خمسة أجيال. وبحسب مدونة Cigars Direct (2020)، يبدأ كل شيء مع إدواردو بلاسينسيا، الذي جاء من جزر الكناري إلى فويلتا أباخو في كوبا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('تزرع عائلة بلاسينسيا التبغ منذ 1865 — استمرارٌ عبر خمسة أجيال، في قارّتين، وعبر واحد من أعمق الانقلابات التي عرفتها المهنة. فما بدأ في مقاطعة بينار ديل ريو الكوبية نجا من الثورة الكوبية، ومن الثورة النيكاراغوية، ومن حرب الكونترا، ومن نصف قرن من عدم الاستقرار الاقتصادي في أمريكا الوسطى — ولم تكفّ العائلة عن الزراعة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Les sources divergent sur la suite. Selon Cigars Direct (2020), le gouvernement cubain saisit la ferme en 1963, Don Sixto passe par le Mexique puis le Nicaragua, où il plante vers 1965 ; des rebelles sandinistes brûlent ses fermes en 1978 et la famille part au Honduras. Selon la presse du métier, c''est la prise de pouvoir sandiniste de 1979 qui saisit les fermes ; Wikipédia parle du début des années 1980. Néstor Plasencia reprend les opérations de tabac en 1986 (Cigars Direct) ; la fabrique d''Ocotal, au Nicaragua, ouvre en 1992 selon Wikipédia, en 1994 selon la presse du métier.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('L''exil de Cuba, en 1961, fixa la trajectoire. Comme la plupart des familles de tabac cubaines, les Plasencia emportèrent leurs semences, leur savoir et leurs relations professionnelles. À la différence de la plupart, ils trouvèrent des terres réellement exceptionnelles. La vallée de Jalapa, dans le nord du Nicaragua — un bassin volcanique à 900 mètres d''altitude, dont l''humidité et les amplitudes de température rappellent une partie de ce qui fait la Vuelta Abajo — devint leur base principale.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Sources diverge on what follows. According to Cigars Direct (2020), the Cuban government seized the farm in 1963, Don Sixto went through Mexico and then Nicaragua, where he planted around 1965; Sandinista rebels burned his farms in 1978 and the family left for Honduras. According to the trade press, it was the Sandinista takeover of 1979 that seized the farms; Wikipedia speaks of the early 1980s. Néstor Plasencia took over the tobacco operations in 1986 (Cigars Direct); the Ocotal factory, in Nicaragua, opened in 1992 according to Wikipedia, in 1994 according to the trade press.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The exile from Cuba in 1961 set the trajectory. Like most Cuban tobacco families, the Plasencias carried their seeds, their knowledge, and their professional contacts into displacement. Unlike most, they found their way to land that proved genuinely exceptional. The Jalapa Valley in northern Nicaragua — a volcanic basin at 900 meters altitude, with consistent humidity and temperature ranges that replicate many of the conditions that make Vuelta Abajo distinctive — became their primary base of operations.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Las fuentes divergen sobre lo que sigue. Según Cigars Direct (2020), el gobierno cubano confisca la finca en 1963, Don Sixto pasa por México y luego por Nicaragua, donde planta hacia 1965; rebeldes sandinistas queman sus fincas en 1978 y la familia parte a Honduras. Según la prensa del sector, es la toma del poder sandinista de 1979 la que confisca las fincas; Wikipedia habla de principios de la década de 1980. Néstor Plasencia retoma las operaciones tabaqueras en 1986 (Cigars Direct); la fábrica de Ocotal, en Nicaragua, abre en 1992 según Wikipedia y en 1994 según la prensa del sector.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('El exilio de Cuba, en 1961, fijó la trayectoria. Como la mayoría de las familias tabaqueras cubanas, los Plasencia se llevaron sus semillas, su saber y sus relaciones profesionales. A diferencia de la mayoría, encontraron tierras realmente excepcionales. El valle de Jalapa, en el norte de Nicaragua —una cuenca volcánica a 900 metros de altitud, cuya humedad y amplitudes de temperatura recuerdan parte de lo que hace la Vuelta Abajo—, se convirtió en su base principal.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Über den weiteren Verlauf gehen die Quellen auseinander. Laut Cigars Direct (2020) beschlagnahmt die kubanische Regierung die Farm 1963, Don Sixto geht über Mexiko und dann nach Nicaragua, wo er um 1965 pflanzt; sandinistische Rebellen brennen 1978 seine Farmen nieder, und die Familie geht nach Honduras. Laut der Fachpresse ist es die sandinistische Machtübernahme von 1979, die die Farmen beschlagnahmt; Wikipedia nennt den Beginn der 1980er Jahre. Néstor Plasencia übernimmt 1986 die Tabakgeschäfte (Cigars Direct); die Fabrik in Ocotal in Nicaragua eröffnet laut Wikipedia 1992, laut Fachpresse 1994.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Das Exil aus Kuba legte 1961 die Bahn fest. Wie die meisten kubanischen Tabakfamilien nahmen die Plasencias ihr Saatgut, ihr Wissen und ihre beruflichen Beziehungen mit. Anders als die meisten fanden sie wirklich außergewöhnliches Land. Das Tal von Jalapa im Norden Nicaraguas — ein vulkanisches Becken auf 900 Metern Höhe, dessen Feuchte und Temperaturspannen einen Teil dessen wachrufen, was die Vuelta Abajo ausmacht — wurde ihre Hauptbasis.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('关于后来的事，各方说法不一。据 Cigars Direct（2020年），古巴政府于1963年没收了农场，堂·西斯托（Don Sixto）取道墨西哥前往尼加拉瓜，约在1965年于当地种植；桑地诺叛军1978年烧毁了他的农场，家族迁往洪都拉斯。据行业媒体，没收农场的是1979年桑地诺政权的上台；维基百科则说是1980年代初。内斯托·普拉森西亚（Néstor Plasencia）于1986年接手烟草业务（Cigars Direct）；尼加拉瓜的奥科塔尔工厂，据维基百科1992年开业，据行业媒体则为1994年。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('1961年离开古巴的流亡，定下了此后的走向。和多数古巴烟草家族一样，普拉森西亚家带走了种子、本事与职业上的人脉。与多数人不同的是，他们找到了真正出色的土地。尼加拉瓜北部的哈拉帕山谷——一处海拔900米的火山盆地，其湿度与温差让人想起构成阿巴霍谷的一部分条件——成了他们的主基地。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('وتتباين المصادر في ما تلا ذلك. فبحسب Cigars Direct (2020)، صادرت الحكومة الكوبية المزرعة عام 1963، ومرّ دون سيكستو بالمكسيك ثم بنيكاراغوا، حيث زرع نحو عام 1965؛ وأحرق متمرّدون ساندينيون مزارعه عام 1978، فرحلت العائلة إلى هندوراس. وبحسب الصحافة المتخصصة، فإن استيلاء الساندينيين على الحكم عام 1979 هو الذي صادر المزارع؛ أما ويكيبيديا فتتحدث عن مطلع الثمانينيات. وتولّى نستور بلاسينسيا عمليات التبغ عام 1986 (Cigars Direct)؛ وافتُتح مصنع أوكوتال في نيكاراغوا عام 1992 بحسب ويكيبيديا، وعام 1994 بحسب الصحافة المتخصصة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('حدّد المنفى من كوبا، عام 1961، المسار. فكما فعلت معظم عائلات التبغ الكوبية، حملت عائلة بلاسينسيا بذورها ومعرفتها وعلاقاتها المهنية. لكنها، خلافًا لمعظمها، وجدت أرضًا استثنائية حقًّا. فصار وادي خالابا في شمال نيكاراغوا — حوض بركاني على ارتفاع 900 متر، تستحضر رطوبته وفوارقه الحرارية جانبًا مما يصنع فويلتا أباخو — قاعدتها الرئيسة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Pendant longtemps, la famille a surtout été connue comme cultivatrice et comme fabricante pour compte de tiers. Selon la presse du métier, elle fournit de la feuille à Davidoff et fabrique des cigares pour Rocky Patel et Alec Bradley, entre autres ; Wikipédia ajoute Swisher.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Pendant des décennies, l''histoire des Plasencia fut invisible pour le fumeur et essentielle pour presque tous les fabricants. La famille a fourni la feuille à Davidoff, qui l''emploie dans le Millennium Blend. À Padrón, qui l''emploie dans la série 1926. À My Father, qui a bâti en partie sur elle son identité nicaraguayenne. Ashton, Rocky Patel, Alec Bradley — la liste des maisons dont la production premium nicaraguayenne dépend de la feuille Plasencia se lit comme un annuaire du marché américain.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('For a long time, the family was known above all as a grower and as a contract manufacturer. According to the trade press, it supplies leaf to Davidoff and makes cigars for Rocky Patel and Alec Bradley, among others; Wikipedia adds Swisher.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('For decades, the Plasencia story was invisible to cigar consumers but essential to virtually every major manufacturer. The family supplied leaf to Davidoff, who used it in the Millennium Blend. They supplied Padrón, who used it in the 1926 Series. They supplied My Father, who built his Nicaraguan identity partly on their leaf. Ashton, Rocky Patel, Alec Bradley — the list of houses whose premium Nicaraguan production depends on Plasencia leaf reads like a directory of the American market.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Durante mucho tiempo, la familia fue conocida sobre todo como cultivadora y como fabricante por cuenta de terceros. Según la prensa del sector, suministra hoja a Davidoff y fabrica puros para Rocky Patel y Alec Bradley, entre otros; Wikipedia añade a Swisher.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Durante décadas, la historia de los Plasencia fue invisible para el fumador y esencial para casi todos los fabricantes. La familia ha suministrado la hoja a Davidoff, que la emplea en el Millennium Blend. A Padrón, que la emplea en la serie 1926. A My Father, que levantó en parte sobre ella su identidad nicaragüense. Ashton, Rocky Patel, Alec Bradley —la lista de casas cuya producción premium nicaragüense depende de la hoja Plasencia se lee como un directorio del mercado estadounidense.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Lange Zeit war die Familie vor allem als Anbauerin und als Lohnfertigerin bekannt. Laut der Fachpresse liefert sie Blatt an Davidoff und fertigt Zigarren unter anderem für Rocky Patel und Alec Bradley; Wikipedia nennt zusätzlich Swisher.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Jahrzehntelang war die Geschichte der Plasencias für den Raucher unsichtbar und für fast jeden Hersteller wesentlich. Die Familie hat das Blatt an Davidoff geliefert, das es im Millennium Blend verwendet. An Padrón, das es in der Serie 1926 verwendet. An My Father, das seine nicaraguanische Identität zum Teil darauf gebaut hat. Ashton, Rocky Patel, Alec Bradley — die Liste der Häuser, deren nicaraguanische Premiumproduktion vom Plasencia-Blatt abhängt, liest sich wie ein Verzeichnis des amerikanischen Marktes.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('很长一段时间里，这个家族主要以种植者和代工制造商闻名。据行业媒体，它向 Davidoff 供应烟叶，并为 Rocky Patel 和 Alec Bradley 等品牌制造雪茄；维基百科还提到 Swisher。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('数十年间，普拉森西亚的故事对烟客是隐形的，对几乎所有厂商却是根本的。这个家族向大卫杜夫供叶，用于千禧配方；向帕德龙供叶，用于1926系列；向 My Father 供叶，后者的尼加拉瓜身份有一部分正建立在它之上。阿什顿、洛基·帕特尔、亚历克·布拉德利——那些高端尼加拉瓜产品依赖普拉森西亚叶子的字号，列出来像一份美国市场的名录。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('ظلّت العائلة زمنًا طويلًا معروفة قبل كل شيء بوصفها مزارعة ومصنِّعة لحساب الغير. وبحسب الصحافة المتخصصة، تورّد الورقة إلى Davidoff وتصنع سيجارًا لحساب Rocky Patel وAlec Bradley، من بين آخرين؛ وتضيف ويكيبيديا Swisher.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وطوال عقود، كان تاريخ آل بلاسينسيا غير مرئي للمدخّن وجوهريًّا لكل الصنّاع تقريبًا. فقد زوّدت العائلة بالورقة دافيدوف، التي تستعملها في «ميلينيوم بلند». وبادرون، التي تستعملها في سلسلة 1926. وماي فاذر، التي بنت عليها جزئيًّا هويتها النيكاراغوية. وآشتون، وروكي باتيل، وأليك برادلي — وقائمة الدور التي يعتمد إنتاجها النيكاراغوي الفاخر على ورقة بلاسينسيا تُقرأ كدليل للسوق الأمريكية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('En 2016, la famille crée Plasencia 1865, société de distribution, et sort sous son propre nom la série Alma, dont l''Alma Fuerte (âme forte) est le premier cigare. Selon Cigar Coop (2018), c''est un puro nicaraguayen bâti sur le Criollo ''98, avec des tabacs de Condega, d''Estelí, de Jalapa et d''Ometepe. La série Cosecha, du Honduras, suit fin 2017 avec la Cosecha 146.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Plasencia'
UNION ALL SELECT 'Plasencia', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('L''Alma Fuerte, lancée en 2018, fut la première tentative sérieuse de la famille de faire des cigares sous sa propre identité. Le nom — âme forte — dit ce que les Plasencia voulaient exprimer après cinquante ans passés à soutenir les marques des autres. L''assemblage réunit leurs meilleurs tabacs du Nicaragua et du Honduras, roulés dans des formats d''une taille et d''une complexité de construction inhabituelles. La réponse du marché fut immédiate : la demande dépassa la production dès la première année.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Plasencia'
