UNION ALL SELECT 'Alec Bradley', 'fr', 'histoire 6 (nouveau texte)', (LOCATE(CAST('Viennent ensuite Tempus (2007 ou 2009 selon les sources), Black Market (2011), Coyol (2014), Magic Toast (2018) et Project 40 (2019). En 2018, les fils de Rubin lancent leur propre marque, Alec & Bradley, d''où vient Kintsugi selon Wikipédia. Le 1er mars 2023, Scandinavian Tobacco Group reprend le portefeuille Alec Bradley ; Rubin reste conseiller et la maison est aujourd''hui rattachée à Forged Cigar Co.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Alec Bradley'
UNION ALL SELECT 'Alec Bradley', 'fr', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('La maison a continué depuis sans chercher l''effet : le Tempus, le Medalist, la série Black Market déclinent la même approche — des assemblages honduriens et guatémaltèques sérieux, roulés avec précision, vendus sans tapage.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Alec Bradley'
