UNION ALL SELECT 'Alec Bradley', 'de', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('Das Haus hat seither weitergemacht, ohne den Effekt zu suchen: die Tempus, die Medalist, die Reihe Black Market wandeln denselben Ansatz ab — ernsthafte honduranische und guatemaltekische Mischungen, genau gerollt, ohne Lärm verkauft.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Alec Bradley'
