UNION ALL SELECT 'CAO', 'fr', 'limited_eds : CAO Zócalo (2018, régulière depuis 2021)', (JSON_CONTAINS(`limited_eds`, '"CAO Zócalo (2018, régulière depuis 2021)"')) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'fr', 'limited_eds : CAO Arcana (série annuelle depuis 2021)', (JSON_CONTAINS(`limited_eds`, '"CAO Arcana (série annuelle depuis 2021)"')) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'fr', 'founded', (CAST(`founded` AS BINARY) = CAST('1968 selon Cigar Dojo — Nashville, Tennessee' AS BINARY)) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Selon la ligne : STG Estelí (Nicaragua), STG Danlí et HATSA (Honduras), General Cigar Dominicana (République dominicaine)' AS BINARY)) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('L''histoire de CAO commence avec des pipes, pas des cigares. Selon Cigar Dojo, Cano Aret Ozgener lança la maison à Nashville en 1968 et la nomma d''après ses initiales ; elle fabriquait d''abord des pipes et des humidors. La presse du métier précise qu''Ozgener, né à Istanbul en 1937, ingénieur, avait travaillé chez DuPont en Caroline du Nord, où il réparait des pipes turques en écume de mer défectueuses, et qu''il se consacra à plein temps à la pipe en 1977 : les deux pages ne donnent donc pas le même point de départ (1968 ou 1977).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('L''histoire de CAO commence avec des pipes, pas des cigares. Cano Ozgener, émigré de Turquie à Nashville dans les années 1960, fonda son affaire en 1968 comme importateur spécialisé de bruyères turques et de pipes en écume de mer — des produits auxquels son origine lui donnait accès par des relations que ses concurrents américains ne pouvaient pas reproduire. Nashville était un lieu improbable pour un négoce de tabac haut de gamme, mais Ozgener avait compris que sa clientèle n''était pas géographique mais démographique : le collectionneur sérieux existe dans chaque ville américaine, et la vente par correspondance permettait de l''atteindre sans boutique.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('The CAO story begins with pipes, not cigars. According to Cigar Dojo, Cano Aret Ozgener launched the house in Nashville in 1968 and named it after his initials; it first made pipes and humidors. The trade press adds that Ozgener, born in Istanbul in 1937, an engineer, had worked at DuPont in North Carolina, where he repaired defective Turkish meerschaum pipes, and that he went full time into pipes in 1977: the two pages therefore do not give the same starting point (1968 or 1977).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The CAO story begins with pipes, not cigars. Cano Ozgener, who had emigrated from Turkey to Nashville in the 1960s, founded his business in 1968 as a specialist importer of Turkish briars and Meerschaum pipes — products that his cultural background gave him access to through relationships that American competitors could not replicate. Nashville was an unlikely location for a premium tobacco business, but Ozgener understood that his customer base was not geographic but demographic: the serious pipe collector existed in every American city, and direct mail could reach them without a street-level presence.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La historia de CAO empieza con pipas, no con puros. Según Cigar Dojo, Cano Aret Ozgener lanzó la casa en Nashville en 1968 y la nombró por sus iniciales; fabricaba al principio pipas y humidores. La prensa del sector precisa que Ozgener, nacido en Estambul en 1937, ingeniero, había trabajado en DuPont en Carolina del Norte, donde reparaba pipas turcas de espuma de mar defectuosas, y que se dedicó a tiempo completo a la pipa en 1977: las dos páginas no dan, pues, el mismo punto de partida (1968 o 1977).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La historia de CAO empieza con pipas, no con puros. Cano Ozgener, emigrado de Turquía a Nashville en los años sesenta, fundó su negocio en 1968 como importador especializado de brezos turcos y de pipas de espuma de mar —productos a los que su origen le daba acceso por relaciones que sus competidores estadounidenses no podían reproducir. Nashville era un lugar improbable para un comercio de tabaco de gama alta, pero Ozgener había comprendido que su clientela no era geográfica sino demográfica: el coleccionista serio existe en cada ciudad estadounidense, y la venta por correspondencia permitía alcanzarlo sin tienda.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Die Geschichte von CAO beginnt mit Pfeifen, nicht mit Zigarren. Laut Cigar Dojo gründete Cano Aret Ozgener das Haus 1968 in Nashville und benannte es nach seinen Initialen; zunächst stellte es Pfeifen und Humidore her. Die Fachpresse präzisiert, dass Ozgener, 1937 in Istanbul geboren, Ingenieur, bei DuPont in Nord-Carolina gearbeitet hatte, wo er fehlerhafte türkische Meerschaumpfeifen reparierte, und sich 1977 ganz der Pfeife widmete: Die beiden Seiten geben also nicht denselben Ausgangspunkt an (1968 oder 1977).' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Geschichte von CAO beginnt mit Pfeifen, nicht mit Zigarren. Cano Ozgener, in den sechziger Jahren aus der Türkei nach Nashville ausgewandert, gründete sein Geschäft 1968 als Facheinführer türkischer Bruyère- und Meerschaumpfeifen — Waren, zu denen ihm seine Herkunft über Beziehungen Zugang verschaffte, die seine amerikanischen Mitbewerber nicht nachbilden konnten. Nashville war ein unwahrscheinlicher Ort für einen gehobenen Tabakhandel, doch Ozgener hatte begriffen, dass seine Kundschaft nicht geografisch war, sondern demografisch: Den ernsthaften Sammler gibt es in jeder amerikanischen Stadt, und der Versandhandel erreichte ihn ohne Ladenlokal.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO 的故事始于烟斗，而不是雪茄。据 Cigar Dojo，卡诺·阿雷特·奥兹格纳于1968年在纳什维尔创办了这家公司，并以自己姓名的首字母命名；它起初制作烟斗和雪茄保湿盒。行业媒体补充说，奥兹格纳1937年生于伊斯坦布尔，是工程师，曾在北卡罗来纳州的 DuPont 工作，在那里修理有缺陷的土耳其海泡石烟斗，并于1977年全职投入烟斗：因此两个页面给出的起点并不相同（1968年或1977年）。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('CAO 的故事始于烟斗，而不是雪茄。卡诺·奥兹格纳在六十年代从土耳其移居纳什维尔，1968年创办了自己的生意，专做土耳其石楠木烟斗与海泡石烟斗的进口——凭他的出身，他能通过美国同行无法复制的人脉拿到这些货。纳什维尔并不像一个高端烟草生意该在的地方，但奥兹格纳想明白了：他的客群不是地理意义上的，而是人口意义上的——认真的收藏者在每一座美国城市都有，而邮购让他不必开店就能触及他们。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تبدأ قصة CAO بالغلايين لا بالسيجار. وبحسب Cigar Dojo أطلق كانو آريت أوزغنر الدار في ناشفيل عام 1968 وسمّاها على أحرف اسمه الأولى؛ وكانت تصنع في البداية الغلايين وحافظات الرطوبة. وتوضّح صحافة المهنة أن أوزغنر، المولود في إسطنبول عام 1937، مهندس، كان قد عمل في DuPont بولاية كارولاينا الشمالية، حيث كان يصلح غلايين زبد البحر التركية المعيبة، وأنه تفرّغ للغليون عام 1977: فالصفحتان لا تعطيان إذن نقطة الانطلاق نفسها (1968 أو 1977).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('تبدأ قصة CAO بالغلايين لا بالسيجار. فقد هاجر كانو أوزغنر من تركيا إلى ناشفيل في الستينيات، وأسّس عمله عام 1968 مستوردًا متخصّصًا في غلايين الخلنج التركي وغلايين زبد البحر — بضائع أتاحت له أصولُه الوصول إليها عبر علاقات لم يستطع منافسوه الأمريكيون استنساخها. لم تكن ناشفيل مكانًا مرجَّحًا لتجارة تبغ راقية، لكنّ أوزغنر كان قد فهم أن زبائنه ليسوا جغرافيا بل ديموغرافيا: فالجامع الجادّ موجود في كل مدينة أمريكية، والبيع بالبريد يتيح بلوغه بلا متجر.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Le cigare vient plus tard. Cigar Dojo écrit que la maison tenta le cigare premium en 1980, puis y revint au milieu des années 1990 ; la presse du métier date l''entrée d''Ozgener sur le marché du cigare de 1993 et le premier CAO, roulé au Honduras, de 1995. Au début des années 2000, la marque s''était fait connaître par des mélanges audacieux et contemporains.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Le passage au cigare, dans les années 1990, fut à la fois opportuniste et réfléchi. L''engouement américain de cette décennie créait une demande que les manufactures établies peinaient à satisfaire, et Ozgener reconnut dans la culture du cigare le même goût de connaisseur qu''il servait depuis vingt ans sur le marché de la pipe. Le client qui avait passé des années à former son goût en bruyère était exactement celui qui apprécierait des cigares sérieux — et Ozgener avait vingt ans de relation avec lui.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The cigar comes later. Cigar Dojo writes that the house tried the premium cigar in 1980, then returned to it in the mid-1990s; the trade press dates Ozgener''s entry into the cigar market to 1993 and the first CAO, rolled in Honduras, to 1995. By the early 2000s, the brand had made a name for itself with bold, contemporary blends.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The transition to cigars in the 1990s was both opportunistic and philosophically motivated. The American cigar boom of that decade was creating demand that the established manufacturers were struggling to meet, and Ozgener recognized in cigar culture the same connoisseurship that he had spent twenty years serving in the pipe market. The customer who had spent years developing their taste in briars was exactly the customer who would appreciate serious cigars, and Ozgener had twenty years of relationship with them.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('El puro llega más tarde. Cigar Dojo escribe que la casa probó el puro premium en 1980 y volvió a él a mediados de los años noventa; la prensa del sector fecha la entrada de Ozgener en el mercado del puro en 1993 y el primer CAO, liado en Honduras, en 1995. A principios de los años dos mil, la marca se había dado a conocer por mezclas audaces y contemporáneas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('El paso al puro, en los años noventa, fue a la vez oportunista y meditado. El entusiasmo estadounidense de esa década creaba una demanda que las manufacturas establecidas apenas satisfacían, y Ozgener reconoció en la cultura del puro el mismo gusto de conocedor que servía desde hacía veinte años en el mercado de la pipa. El cliente que había pasado años formando su gusto en brezo era exactamente el que apreciaría puros serios —y Ozgener llevaba veinte años de relación con él.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Die Zigarre kommt später. Cigar Dojo schreibt, das Haus habe es 1980 mit der Premiumzigarre versucht und sei Mitte der neunziger Jahre darauf zurückgekommen; die Fachpresse datiert Ozgeners Einstieg in den Zigarrenmarkt auf 1993 und die erste CAO, in Honduras gerollt, auf 1995. Anfang der zweitausender Jahre hatte sich die Marke durch kühne, zeitgemäße Mischungen einen Namen gemacht.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Der Übergang zur Zigarre in den neunziger Jahren war zugleich Gelegenheit und Überlegung. Die amerikanische Begeisterung jenes Jahrzehnts schuf eine Nachfrage, der die eingeführten Manufakturen kaum nachkamen, und Ozgener erkannte in der Zigarrenkultur denselben Kennergeschmack, den er seit zwanzig Jahren im Pfeifenmarkt bediente. Der Kunde, der Jahre darauf verwandt hatte, seinen Geschmack am Bruyère zu bilden, war genau jener, der ernsthafte Zigarren schätzen würde — und Ozgener hatte zwanzig Jahre Beziehung zu ihm.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('雪茄是后来的事。据 Cigar Dojo，公司在1980年尝试过高端雪茄，之后在1990年代中期重新回到雪茄；行业媒体则把奥兹格纳进入雪茄市场的时间定在1993年，把在洪都拉斯卷制的首支 CAO 定在1995年。到2000年代初，这个品牌已凭大胆而当代的配方为人所知。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('九十年代转向雪茄，既是抓住时机，也是深思之后的选择。那十年的美国热潮造出了成熟工厂难以满足的需求，而奥兹格纳在雪茄文化里认出了他二十年来在烟斗市场服务的同一种行家口味。那位花了多年在石楠木上养成品味的客人，恰恰就是会欣赏认真雪茄的人——而奥兹格纳与他已有二十年的交情。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('ويأتي السيجار لاحقًا. تكتب Cigar Dojo أن الدار جرّبت السيجار الفاخر عام 1980، ثم عادت إليه في منتصف التسعينيات؛ وتؤرّخ صحافة المهنة دخول أوزغنر سوق السيجار بعام 1993، وأول CAO، الملفوف في هندوراس، بعام 1995. ومع مطلع الألفينات كانت العلامة قد عُرفت بخلطات جريئة ومعاصرة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('وكان الانتقال إلى السيجار، في التسعينيات، اغتنامًا للفرصة وتفكيرًا في آن. فحماسة ذلك العقد الأمريكية خلقت طلبًا كادت المصانع الراسخة لا تلبّيه، ورأى أوزغنر في ثقافة السيجار ذوق العارفين نفسه الذي كان يخدمه منذ عشرين عامًا في سوق الغليون. فالزبون الذي أمضى سنوات يبني ذائقته على الخلنج هو بالضبط من سيقدّر سيجارًا جادًّا — وكانت تربط أوزغنر به عشرون سنة من العلاقة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('CAO a cultivé un registre à part, tourné vers l''imagerie américaine. La gamme Flathead, lancée en 2013 selon Cigar Dojo, puise dans l''univers des hot rods, des pin-up et des motos custom ; ses formats portent des noms de pièces de moteur (Carb, Camshaft, Piston, Big Block). La page de la maison, en octobre 2026, la décrit bâtie sur une cape Connecticut Broadleaf, sans citer de marque de moto.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('L''identité de CAO fut d''emblée différente de celle des maisons établies. Là où Arturo Fuente parle d''héritage et de continuité familiale, et Davidoff de précision suisse et d''ascendance cubaine, CAO parle d''innovation et de référence culturelle. La gamme Flathead, nommée d''après l''esthétique des moteurs V-twin Harley-Davidson d''époque et dessinée autour d''elle, en fut la déclaration la plus explicite : un cigare premium qui s''adressait directement au monde de l''amateur américain, au lieu de traduire en tabac les conventions du luxe européen. L''assemblage nicaraguayen et hondurien à l''intérieur, lui, était sérieux.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('CAO cultivated a register of its own, turned towards American imagery. The Flathead range, launched in 2013 according to Cigar Dojo, draws on the world of hot rods, pin-ups and custom motorcycles; its formats bear the names of engine parts (Carb, Camshaft, Piston, Big Block). The house''s page, in October 2026, describes it as built on a Connecticut Broadleaf wrapper, without citing any motorcycle make.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('CAO''s early cigar identity was deliberately different from the established houses. Where Arturo Fuente communicated heritage and family continuity, and Davidoff communicated Swiss precision and Cuban ancestry, CAO communicated innovation and cultural reference. The Flathead range, named for and designed around the aesthetic of vintage Harley-Davidson V-twin engines, was the most explicit statement of this identity: a premium cigar that addressed the American enthusiast''s world directly rather than translating European luxury conventions into tobacco form. The Nicaraguan-Honduran blend inside was serious. The packaging and marketing spoke a language the established Havana-influenced houses would not have recognized.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('CAO ha cultivado un registro aparte, orientado a la imaginería estadounidense. La gama Flathead, lanzada en 2013 según Cigar Dojo, bebe del universo de los hot rods, las pin-up y las motos custom; sus formatos llevan nombres de piezas de motor (Carb, Camshaft, Piston, Big Block). La página de la casa, en octubre de 2026, la describe construida sobre una capa Connecticut Broadleaf, sin citar ninguna marca de moto.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La identidad de CAO fue desde el principio distinta de la de las casas establecidas. Allí donde Arturo Fuente habla de herencia y de continuidad familiar, y Davidoff de precisión suiza y de ascendencia cubana, CAO habla de innovación y de referencia cultural. La gama Flathead, nombrada según la estética de los motores V-twin Harley-Davidson de época y dibujada en torno a ella, fue su declaración más explícita: un puro premium que se dirigía directamente al mundo del aficionado estadounidense, en lugar de traducir en tabaco las convenciones del lujo europeo. La ligada nicaragüense y hondureña del interior, en cambio, era seria.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('CAO hat ein eigenes Register gepflegt, das sich der amerikanischen Bildwelt zuwendet. Die Linie Flathead, laut Cigar Dojo 2013 eingeführt, schöpft aus der Welt der Hot Rods, der Pin-ups und der Custom-Motorräder; ihre Formate tragen die Namen von Motorteilen (Carb, Camshaft, Piston, Big Block). Die Seite des Hauses beschreibt sie im Oktober 2026 als auf einem Deckblatt Connecticut Broadleaf aufgebaut, ohne eine Motorradmarke zu nennen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Die Identität von CAO war von Anfang an eine andere als die der eingeführten Häuser. Wo Arturo Fuente von Erbe und familiärer Fortdauer spricht und Davidoff von Schweizer Genauigkeit und kubanischer Abstammung, spricht CAO von Neuerung und kultureller Anspielung. Die Linie Flathead, nach der Ästhetik der alten V-Twin-Motoren von Harley-Davidson benannt und um sie herum gezeichnet, war die ausdrücklichste Ansage: eine Premiumzigarre, die sich unmittelbar an die Welt des amerikanischen Liebhabers richtete, statt die Konventionen europäischen Luxus in Tabak zu übersetzen. Die nicaraguanische und honduranische Mischung im Inneren war dagegen ernst gemeint.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('CAO 经营着一条独立的路线，朝向美国意象。据 Cigar Dojo，Flathead 系列于2013年推出，取材于改装老爷车（hot rod）、海报女郎（pin-up）和定制摩托的世界；其规格以发动机零件命名（Carb、Camshaft、Piston、Big Block）。公司页面在2026年10月称其以 Connecticut Broadleaf 茄衣为基础，未提及任何摩托车品牌。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('CAO 的气质从一开始就与老字号不同。阿图罗·富恩特讲的是传承与家族的延续，大卫杜夫讲的是瑞士式的精确与古巴血统，CAO 讲的则是创新与文化引用。Flathead 系列以哈雷戴维森老式 V-twin 发动机的美学命名并据此设计，是这一姿态最直白的宣示：一支直接对着美国爱好者的世界说话的高端雪茄，而不是把欧洲奢侈品的成规翻译成烟草。至于里面的尼加拉瓜与洪都拉斯配方，则是认真的。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('نمّت CAO نمطًا خاصًا بها، متجهًا إلى الصور الأمريكية. وتستمد تشكيلة Flathead، التي أُطلقت عام 2013 بحسب Cigar Dojo، من عالم السيارات المعدَّلة (hot rods) والـpin-up والدراجات النارية المصمَّمة حسب الطلب؛ وتحمل قياساتها أسماء قطع المحرّك (Carb وCamshaft وPiston وBig Block). وتصفها صفحة الدار، في أكتوبر 2026، بأنها مبنية على غلاف Connecticut Broadleaf، من دون أن تذكر ماركة دراجة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وكانت هوية CAO منذ البداية مختلفة عن هوية الدور الراسخة. فحيث تتحدّث أرتورو فوينتي عن الإرث واستمرار العائلة، ودافيدوف عن الدقّة السويسرية والنسب الكوبي، تتحدّث CAO عن الابتكار والإحالة الثقافية. وكانت تشكيلة «فلاتهيد»، المسمّاة على جماليات محرّكات هارلي ديفيدسون ثنائية الأسطوانة القديمة والمرسومة حولها، أوضح إعلان عن ذلك: سيجار فاخر يخاطب عالم الهاوي الأمريكي مباشرة، بدل أن يترجم أعراف الترف الأوروبي إلى تبغ. أما الخلطة النيكاراغوية والهندوراسية في الداخل فكانت جادّة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('En 2007, CAO fut rachetée par Henri Wintermans, division de ST Tobacco, selon la presse du métier ; Cigar Dojo nomme l''actuel Scandinavian Tobacco Group. La marque quitta Nashville pour le siège de General Cigar à Richmond, en Virginie. Tim Ozgener, fils du fondateur, resta président jusqu''en 2010 ; Cano Ozgener est mort le 9 juin 2018 à Nashville, à 81 ans. En octobre 2026, le site caocigars.com porte la mention General Cigar Co., Inc. ; selon les lignes, les cigares sont roulés à Estelí (Nicaragua), au Honduras ou chez General Cigar Dominicana (République dominicaine).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('General Cigar racheta CAO en 2007, faisant entrer ce caractère inventif dans un portefeuille auquel la solidité commerciale de Macanudo ne pouvait pas l''apporter. L''acquisition a préservé le rôle de CAO comme marque qui prend les risques du groupe : celle dont les amateurs suivent le calendrier de sorties pour la nouveauté, quand ils comptent sur Macanudo pour la régularité.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('In 2007, CAO was bought by Henri Wintermans, a division of ST Tobacco, according to the trade press; Cigar Dojo names today''s Scandinavian Tobacco Group. The brand left Nashville for General Cigar''s headquarters in Richmond, Virginia. Tim Ozgener, the founder''s son, remained president until 2010; Cano Ozgener died on 9 June 2018 in Nashville, aged 81. In October 2026, the website caocigars.com carries the mention General Cigar Co., Inc.; depending on the line, the cigars are rolled in Estelí (Nicaragua), in Honduras or at General Cigar Dominicana (Dominican Republic).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('General Cigar acquired CAO in 2007, bringing the brand''s innovative character into a portfolio that needed what Macanudo''s reliable commercial dominance could not provide. The acquisition has maintained CAO''s identity as the group''s risk-taking brand — the release schedule that enthusiasts follow for novelty while they rely on Macanudo for consistency.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('En 2007, CAO fue comprada por Henri Wintermans, división de ST Tobacco, según la prensa del sector; Cigar Dojo nombra al actual Scandinavian Tobacco Group. La marca dejó Nashville por la sede de General Cigar en Richmond, Virginia. Tim Ozgener, hijo del fundador, siguió de presidente hasta 2010; Cano Ozgener murió el 9 de junio de 2018 en Nashville, a los 81 años. En octubre de 2026, el sitio caocigars.com lleva la mención General Cigar Co., Inc.; según las líneas, los puros se lían en Estelí (Nicaragua), en Honduras o en General Cigar Dominicana (República Dominicana).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('General Cigar compró CAO en 2007, haciendo entrar ese carácter inventivo en una cartera a la que la solidez comercial de Macanudo no podía aportarlo. La adquisición ha preservado el papel de CAO como la marca que toma los riesgos del grupo: aquella cuyo calendario de salidas siguen los aficionados por la novedad, mientras cuentan con Macanudo para la regularidad.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('2007 wurde CAO laut Fachpresse von Henri Wintermans übernommen, einer Division von ST Tobacco; Cigar Dojo nennt die heutige Scandinavian Tobacco Group. Die Marke verließ Nashville und zog zum Sitz von General Cigar in Richmond, Virginia. Tim Ozgener, Sohn des Gründers, blieb bis 2010 Präsident; Cano Ozgener starb am 9. Juni 2018 in Nashville im Alter von 81 Jahren. Im Oktober 2026 trägt die Website caocigars.com den Vermerk General Cigar Co., Inc.; je nach Linie werden die Zigarren in Estelí (Nicaragua), in Honduras oder bei General Cigar Dominicana (Dominikanische Republik) gerollt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('General Cigar kaufte CAO 2007 und holte damit dieses erfinderische Wesen in ein Portfolio, dem die kaufmännische Festigkeit von Macanudo es nicht geben konnte. Die Übernahme hat CAOs Rolle als jene Marke bewahrt, die im Konzern die Risiken eingeht: die, deren Neuheitenkalender die Liebhaber der Neugier wegen verfolgen, während sie sich bei Macanudo auf die Gleichmäßigkeit verlassen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('据行业媒体，2007年，CAO 被 ST Tobacco 旗下的 Henri Wintermans 收购；Cigar Dojo 点出的是如今的 Scandinavian Tobacco Group。品牌由此离开纳什维尔，迁往 General Cigar 位于弗吉尼亚州里士满的总部。创始人之子蒂姆·奥兹格纳一直担任总裁到2010年；卡诺·奥兹格纳于2018年6月9日在纳什维尔去世，享年81岁。2026年10月，caocigars.com 网站标注为 General Cigar Co., Inc.；各系列的雪茄视不同情况在埃斯特利（尼加拉瓜）、洪都拉斯或 General Cigar Dominicana（多米尼加共和国）卷制。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('2007年，General Cigar 收购了 CAO，把这股发明的劲头带进一个组合里——那是马卡努多的商业稳健所无法提供的。这次收购保住了 CAO 在集团里担任冒险者的角色：爱好者盯着它的上市日程是为了新意，而把稳定寄托在马卡努多身上。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO'
UNION ALL SELECT 'CAO', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('في عام 2007 اشترى Henri Wintermans، وهو قسم من ST Tobacco، شركة CAO بحسب صحافة المهنة؛ وتسمّي Cigar Dojo الكيان الحالي Scandinavian Tobacco Group. وغادرت العلامة ناشفيل إلى مقرّ General Cigar في ريتشموند بولاية فيرجينيا. وبقي تيم أوزغنر، ابن المؤسس، رئيسًا حتى عام 2010؛ وتُوفّي كانو أوزغنر في 9 يونيو 2018 في ناشفيل عن 81 عامًا. وفي أكتوبر 2026 يحمل موقع caocigars.com عبارة General Cigar Co., Inc.؛ وبحسب الخطوط تُلفّ السيجارات في إستيلي (نيكاراغوا) أو في هندوراس أو لدى General Cigar Dominicana (الجمهورية الدومينيكية).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO'
